css:
/* Barline: a workout logger. Sets are the interface; logging one starts the
   rest ring, re-scores the lift's e1RM and reloads the bar. */
@property --aph-lift-a { syntax: "<angle>"; inherits: true; initial-value: 360deg; }

.aph-lift {
  /* re-theme: bg, ink, accent, gold */
  --aph-lift-bg: oklch(0.205 0.008 255);
  --aph-lift-ink: oklch(0.955 0.006 95);
  --aph-lift-accent: oklch(0.75 0.165 55);
  --aph-lift-gold: oklch(0.86 0.14 92);
  --aph-lift-panel: color-mix(in oklch, var(--aph-lift-bg) 95%, var(--aph-lift-ink));
  --aph-lift-raise: color-mix(in oklch, var(--aph-lift-bg) 89%, var(--aph-lift-ink));
  --aph-lift-sunk: color-mix(in oklch, var(--aph-lift-bg) 82%, black);
  --aph-lift-line: color-mix(in oklch, var(--aph-lift-ink) 10%, transparent);
  --aph-lift-line2: color-mix(in oklch, var(--aph-lift-ink) 19%, transparent);
  --aph-lift-mute: color-mix(in oklch, var(--aph-lift-ink) 62%, var(--aph-lift-bg));
  --aph-lift-faint: color-mix(in oklch, var(--aph-lift-ink) 38%, var(--aph-lift-bg));
  --aph-lift-tint: color-mix(in oklab, var(--aph-lift-accent) 14%, var(--aph-lift-bg)); /* oklab: no hue swing through violet */
  --aph-lift-on: color-mix(in oklch, var(--aph-lift-accent) 18%, black);
  --aph-lift-ease: cubic-bezier(.2, .8, .2, 1);
  --aph-lift-snap: cubic-bezier(.3, 1.4, .5, 1);
  --aph-lift-spring: linear(0, 0.09 4%, 0.36 10%, 0.73 17%, 0.96 24%, 1.05 30%, 1.06 35%, 1.02 45%, 0.995 58%, 1);

  position: relative; width: 100%; height: var(--aph-lift-h, 680px);
  container-type: inline-size; container-name: aph-lift; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--aph-lift-bg); color: var(--aph-lift-ink); color-scheme: dark;
  accent-color: var(--aph-lift-accent); border-radius: 14px;
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--aph-lift-accent); outline-offset: 2px; border-radius: 6px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button[aria-disabled="true"], & button:disabled { cursor: not-allowed; opacity: .42; }
  & h2, & h3, & h4, & p, & ol, & ul, & dl, & dd { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & h2, & h3, & h4 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; display: inline-block; text-align: center; border: 1px solid var(--aph-lift-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--aph-lift-mute); }
  & [hidden] { display: none !important; }
}

.aph-lift .aph-lift-app {
  height: 100%; display: grid;
  grid-template-columns: 236px minmax(0, 1fr) 300px;
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "top top top" "side main aside" "tabs tabs tabs";
}

/* ── top bar ── */
.aph-lift .aph-lift-top {
  grid-area: top; display: flex; align-items: center; gap: 18px; padding: 12px 16px 12px 18px;
  border-bottom: 1px solid var(--aph-lift-line); background: var(--aph-lift-sunk);
}
.aph-lift .aph-lift-brand {
  display: flex; align-items: center; gap: 8px; padding-right: 16px; border-right: 1px solid var(--aph-lift-line);
  & svg { color: var(--aph-lift-accent); width: 22px; height: 22px; stroke-width: 2.2; }
  & b { font-weight: 800; letter-spacing: -.02em; font-size: 15px; }
}
.aph-lift .aph-lift-title {
  min-width: 0;
  & h2 { font-size: clamp(15px, 1.45cqi, 18px); font-weight: 760; letter-spacing: -.015em; white-space: nowrap; }
  & h2 span { color: var(--aph-lift-mute); font-weight: 500; }
  & p { display: flex; gap: 6px; color: var(--aph-lift-mute); font-size: 12px; white-space: nowrap; }
}
.aph-lift .aph-lift-prog {
  flex: 1; min-width: 80px; display: grid; gap: 6px;
  & .aph-lift-progtxt { font-size: 11px; color: var(--aph-lift-mute); display: flex; justify-content: space-between; font-variant-numeric: tabular-nums; }
  & .aph-lift-progtxt b { color: var(--aph-lift-ink); font-weight: 650; }
  & .aph-lift-bars { display: flex; gap: 3px; height: 5px; }
  & .aph-lift-bars i { flex: var(--n) 1 0; border-radius: 3px; background: linear-gradient(90deg, var(--aph-lift-accent) var(--p), var(--aph-lift-line2) var(--p)); }
  & .aph-lift-bars i.is-cur { box-shadow: 0 0 0 1.5px var(--aph-lift-bg), 0 0 0 2.5px color-mix(in oklch, var(--aph-lift-accent) 70%, transparent); }
}
.aph-lift .aph-lift-clock {
  margin-left: auto; display: grid; justify-items: end; line-height: 1.1;
  & small { font-size: 10px; text-transform: uppercase; letter-spacing: .1em; color: var(--aph-lift-faint); font-weight: 650; }
  & output { font: 650 18px/1.1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
}
.aph-lift .aph-lift-finish {
  display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 14px 0 11px; border-radius: 10px;
  background: var(--aph-lift-accent); color: var(--aph-lift-on); font-weight: 750;
  transition: transform .18s var(--aph-lift-ease), filter .18s;
  & svg { stroke-width: 2.4; width: 16px; height: 16px; }
  &:hover { filter: brightness(1.07); }
  &:active { transform: scale(.96); }
  &[data-saved] { background: var(--aph-lift-raise); color: var(--aph-lift-ink); }
}

/* ── side ── */
.aph-lift .aph-lift-side {
  grid-area: side; overflow: auto; overscroll-behavior: contain; padding: 14px 10px 18px; border-right: 1px solid var(--aph-lift-line);
  scrollbar-width: thin; scrollbar-color: var(--aph-lift-line2) transparent;
}
.aph-lift .aph-lift-head {
  display: flex; align-items: baseline; justify-content: space-between; padding: 0 8px 8px;
  & h3 { font-size: 11px; text-transform: uppercase; letter-spacing: .12em; color: var(--aph-lift-faint); font-weight: 700; }
  & small { color: var(--aph-lift-faint); font-size: 11px; font-variant-numeric: tabular-nums; }
  &.is-sub { margin-top: 18px; }
}
.aph-lift .aph-lift-exlist { display: grid; gap: 2px; }
.aph-lift .aph-lift-ex {
  position: relative; display: grid; grid-template-columns: 24px minmax(0, 1fr); gap: 2px 10px; align-items: center; text-align: left;
  padding: 9px 10px; border-radius: 10px; transition: background .2s;
  & .aph-lift-exn { grid-row: span 2; width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center; font: 700 11px/1 ui-monospace, Menlo, monospace; background: var(--aph-lift-raise); color: var(--aph-lift-mute); }
  & b { font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .aph-lift-exmeta { display: flex; align-items: center; gap: 8px; font-size: 11.5px; color: var(--aph-lift-mute); font-variant-numeric: tabular-nums; }
  & .aph-lift-dots { display: flex; gap: 3px; }
  & .aph-lift-dots i { width: 6px; height: 6px; border-radius: 2px; background: var(--aph-lift-line2); }
  & .aph-lift-dots i.is-done { background: var(--aph-lift-accent); }
  & .aph-lift-dots i.is-pr { background: var(--aph-lift-gold); }
  &:hover { background: var(--aph-lift-panel); }
  &[aria-selected="true"] { background: var(--aph-lift-raise); }
  &[aria-selected="true"]::before { content: ""; position: absolute; left: -10px; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--aph-lift-accent); }
  &[aria-selected="true"] .aph-lift-exn { background: var(--aph-lift-accent); color: var(--aph-lift-on); }
  &.is-complete .aph-lift-exn { background: color-mix(in oklab, var(--aph-lift-accent) 26%, var(--aph-lift-bg)); color: var(--aph-lift-accent); }
}
.aph-lift .aph-lift-recent { display: grid; gap: 2px; }
.aph-lift .aph-lift-sess {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0 8px; text-align: left; padding: 8px 10px; border-radius: 10px;
  & b { font-weight: 600; }
  & span { color: var(--aph-lift-mute); font-size: 11.5px; }
  & em { grid-row: span 2; align-self: center; font: 600 11.5px/1 ui-monospace, Menlo, monospace; color: var(--aph-lift-mute); font-style: normal; font-variant-numeric: tabular-nums; }
  &:hover { background: var(--aph-lift-panel); }
  &.is-new { animation: aph-lift-in .5s var(--aph-lift-ease); }
}

/* ── main ── */
.aph-lift .aph-lift-main {
  grid-area: main; overflow: auto; overscroll-behavior: contain; padding: 18px 22px 24px; min-width: 0; container-type: inline-size; container-name: aph-lift-main;
  scrollbar-width: thin; scrollbar-color: var(--aph-lift-line2) transparent;
}
.aph-lift .aph-lift-exhead {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 12px; align-items: end; margin-bottom: 14px;
  & h2 { font-size: clamp(20px, 4.4cqi, 28px); line-height: 1.05; font-weight: 800; letter-spacing: -.03em; }
  & .aph-lift-target { display: flex; flex-wrap: wrap; gap: 6px 12px; color: var(--aph-lift-mute); font-size: 12px; }
  & .aph-lift-target b { color: var(--aph-lift-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
  & .aph-lift-kit { text-transform: uppercase; letter-spacing: .1em; font-size: 10px; font-weight: 750; padding: 3px 7px; border-radius: 5px; background: var(--aph-lift-raise); color: var(--aph-lift-mute); }
  & .aph-lift-acts { grid-row: 1 / span 2; grid-column: 2; display: flex; gap: 6px; }
}
.aph-lift .aph-lift-ghost {
  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 11px; border-radius: 9px;
  border: 1px solid var(--aph-lift-line2); color: var(--aph-lift-ink); font-weight: 560; font-size: 12.5px;
  transition: background .15s, border-color .15s, transform .15s var(--aph-lift-ease);
  & svg { width: 15px; height: 15px; }
  &:hover { background: var(--aph-lift-panel); border-color: color-mix(in oklch, var(--aph-lift-ink) 30%, transparent); }
  &:active { transform: scale(.97); }
  &[aria-expanded="true"], &[aria-pressed="true"] { background: var(--aph-lift-raise); border-color: var(--aph-lift-accent); }
}
.aph-lift .aph-lift-cue { margin: 0 0 12px; }
.aph-lift .aph-lift-cue textarea {
  width: 100%; min-height: 58px; resize: vertical; padding: 9px 11px; border-radius: 10px; border: 1px solid var(--aph-lift-line2);
  background: var(--aph-lift-sunk); line-height: 1.45; font-size: 12.5px;
  &:focus { outline: 2px solid var(--aph-lift-accent); outline-offset: 0; }
}

/* set table: rows are subgrids of one column template, so every cell lines up */
.aph-lift .aph-lift-table {
  display: grid; grid-template-columns: 46px minmax(68px, 1fr) 78px 62px 56px 46px; column-gap: 6px;
  border: 1px solid var(--aph-lift-line); border-radius: 12px; overflow: hidden; background: var(--aph-lift-panel);
}
.aph-lift .aph-lift-row {
  position: relative; grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center;
  min-height: 42px; padding: 0 6px 0 4px; border-top: 1px solid var(--aph-lift-line); font-variant-numeric: tabular-nums;
  transition: background .18s;
  &.is-head { min-height: 32px; border-top: 0; font-size: 10px; text-transform: uppercase; letter-spacing: .1em; color: var(--aph-lift-faint); font-weight: 700; background: var(--aph-lift-sunk); }
  &:not(.is-head):hover { background: color-mix(in oklch, var(--aph-lift-panel) 70%, var(--aph-lift-raise)); }
  &[aria-selected="true"] { background: var(--aph-lift-tint); }
  &[aria-selected="true"]::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--aph-lift-accent); }
  &.is-done .aph-lift-w, &.is-done .aph-lift-r { color: var(--aph-lift-ink); }
  &.is-new { animation: aph-lift-row .42s var(--aph-lift-ease); }
  & .aph-lift-prev { color: var(--aph-lift-faint); font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .aph-lift-w, & .aph-lift-r { font: 650 15px/1 ui-monospace, Menlo, monospace; color: var(--aph-lift-mute); letter-spacing: -.02em; }
  & .aph-lift-w small { font: 500 10px/1 system-ui; color: var(--aph-lift-faint); margin-left: 2px; }
  & .aph-lift-rpe { font: 600 12px/1 ui-monospace, Menlo, monospace; color: var(--aph-lift-mute); }
  & .aph-lift-rpe:empty::before { content: "–"; color: var(--aph-lift-faint); }
}
.aph-lift .aph-lift-sel {
  width: 30px; height: 30px; border-radius: 8px; font: 700 12px/1 ui-monospace, Menlo, monospace; color: var(--aph-lift-mute);
  display: grid; place-items: center; position: static;
  &::after { content: ""; position: absolute; inset: 0; z-index: 0; }
  &[data-kind="w"] { color: var(--aph-lift-faint); font-size: 10.5px; letter-spacing: .04em; }
}
.aph-lift .aph-lift-row[aria-selected="true"] .aph-lift-sel { color: var(--aph-lift-accent); }
.aph-lift .aph-lift-pr {
  position: absolute; left: 30px; top: 6px; z-index: 1; pointer-events: none;
  font: 800 8.5px/1 system-ui; letter-spacing: .06em; padding: 2px 4px; border-radius: 4px; background: var(--aph-lift-gold); color: oklch(0.25 0.05 80);
  &.is-fresh { animation: aph-lift-pr .9s var(--aph-lift-snap) both; }
}
.aph-lift .aph-lift-check {
  position: relative; z-index: 1; width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; justify-self: end;
  border: 1.5px solid var(--aph-lift-line2); color: transparent; transition: background .2s, border-color .2s, transform .2s var(--aph-lift-snap);
  & svg { stroke-width: 2.6; width: 17px; height: 17px; }
  & svg path { stroke-dasharray: 22; stroke-dashoffset: 22; transition: stroke-dashoffset .32s var(--aph-lift-ease) .05s; }
  &:hover { border-color: var(--aph-lift-accent); color: color-mix(in oklch, var(--aph-lift-accent) 50%, transparent); }
  &:hover svg path { stroke-dashoffset: 0; }
  &[aria-pressed="true"] { background: var(--aph-lift-accent); border-color: var(--aph-lift-accent); color: var(--aph-lift-on); }
  &[aria-pressed="true"] svg path { stroke-dashoffset: 0; }
  &:active { transform: scale(.9); }
}
.aph-lift .aph-lift-addrow {
  display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 10px 0 18px;
  & .aph-lift-hint { color: var(--aph-lift-faint); font-size: 11px; display: flex; gap: 3px; align-items: center; flex-wrap: wrap; justify-content: flex-end; }
}

/* ── editor ── */
.aph-lift .aph-lift-editor {
  display: grid; grid-template-columns: auto auto minmax(0, 1fr); grid-template-areas: "cap cap cap" "w r go" "rpe rpe est";
  gap: 12px 18px; padding: 14px 16px; border-radius: 14px; background: var(--aph-lift-raise); border: 1px solid var(--aph-lift-line);
  & .aph-lift-cap { grid-area: cap; display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
  & .aph-lift-cap h4 { font-size: 13px; font-weight: 700; }
  & .aph-lift-cap h4 span { color: var(--aph-lift-mute); font-weight: 500; }
  & .aph-lift-field { display: grid; gap: 6px; }
  & .aph-lift-field > small { font-size: 10px; text-transform: uppercase; letter-spacing: .12em; color: var(--aph-lift-faint); font-weight: 700; }
  & .aph-lift-step { display: flex; align-items: center; gap: 4px; }
  & .aph-lift-step button { width: 34px; height: 40px; border-radius: 10px; background: var(--aph-lift-panel); display: grid; place-items: center; transition: background .15s, transform .15s var(--aph-lift-snap); }
  & .aph-lift-step button:hover { background: var(--aph-lift-sunk); }
  & .aph-lift-step button:active { transform: scale(.9); }
  & .aph-lift-step input { width: 72px; height: 40px; text-align: center; border: 0; border-radius: 10px; background: var(--aph-lift-sunk); font: 700 22px/1 ui-monospace, Menlo, monospace; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & .aph-lift-step input.is-r { width: 54px; }
  & .aph-lift-step input:focus { outline: 2px solid var(--aph-lift-accent); outline-offset: 0; }
  & .aph-lift-rpes { grid-area: rpe; }
  & .aph-lift-chips { display: flex; flex-wrap: wrap; gap: 4px; }
  & .aph-lift-chips button { min-width: 33px; height: 30px; padding: 0 6px; border-radius: 8px; background: var(--aph-lift-panel); font: 650 12px/1 ui-monospace, Menlo, monospace; color: var(--aph-lift-mute); transition: background .15s, color .15s; }
  & .aph-lift-chips button:hover { color: var(--aph-lift-ink); }
  & .aph-lift-chips button[aria-checked="true"] { background: var(--aph-lift-ink); color: var(--aph-lift-bg); }
  & .aph-lift-go { grid-area: go; align-self: end; justify-self: end; display: flex; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }
  & .aph-lift-est { grid-area: est; align-self: end; justify-self: end; text-align: right; font-size: 12px; color: var(--aph-lift-mute); font-variant-numeric: tabular-nums; }
  & .aph-lift-est b { display: block; font: 700 18px/1.1 ui-monospace, Menlo, monospace; color: var(--aph-lift-ink); letter-spacing: -.02em; }
  & .aph-lift-est.is-pr b { color: var(--aph-lift-gold); }
}
.aph-lift .aph-lift-primary {
  display: inline-flex; align-items: center; gap: 8px; height: 40px; padding: 0 16px; border-radius: 11px; font-weight: 750;
  background: var(--aph-lift-accent); color: var(--aph-lift-on); transition: transform .18s var(--aph-lift-snap), filter .15s;
  & kbd { border-color: color-mix(in oklch, var(--aph-lift-on) 35%, transparent); color: var(--aph-lift-on); }
  &:hover { filter: brightness(1.07); }
  &:active { transform: scale(.96); }
  &.is-undo { background: var(--aph-lift-panel); color: var(--aph-lift-ink); }
  &.is-undo kbd { color: var(--aph-lift-mute); border-color: var(--aph-lift-line2); }
}

/* ── loader ── */
.aph-lift .aph-lift-loader {
  margin-top: 14px; padding: 16px 18px 14px; border-radius: 14px; border: 1px dashed var(--aph-lift-line2);
  display: grid; gap: 10px;
  & header { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; flex-wrap: wrap; }
  & header b { font-size: 12px; text-transform: uppercase; letter-spacing: .12em; color: var(--aph-lift-faint); font-weight: 700; }
  & header span { font-size: 12.5px; color: var(--aph-lift-mute); font-variant-numeric: tabular-nums; }
  & header span b { color: var(--aph-lift-ink); font-size: inherit; text-transform: none; letter-spacing: 0; }
}
.aph-lift .aph-lift-bar {
  position: relative; height: 92px; display: grid; grid-template-columns: 1fr minmax(60px, 34%) 1fr; align-items: center;
  & .aph-lift-shaft { height: 8px; border-radius: 2px; background: linear-gradient(var(--aph-lift-faint), var(--aph-lift-mute) 50%, var(--aph-lift-faint)); }
  & .aph-lift-sleeve { position: relative; height: 92px; display: flex; align-items: center; gap: 2px; }
  & .aph-lift-sleeve::before { content: ""; position: absolute; top: 50%; height: 14px; margin-top: -7px; left: 0; right: 0; border-radius: 3px; background: linear-gradient(var(--aph-lift-mute), var(--aph-lift-ink) 45%, var(--aph-lift-mute)); opacity: .55; }
  & .aph-lift-sleeve.is-l { flex-direction: row-reverse; }
  & .aph-lift-collar { position: relative; width: 7px; height: 26px; border-radius: 2px; background: var(--aph-lift-mute); flex: none; }
}
.aph-lift .aph-lift-plate {
  position: relative; flex: none; width: var(--pw); height: var(--ph); border-radius: 4px; background: var(--pc);
  box-shadow: inset 0 0 0 1px oklch(1 0 0 / .14), inset -3px 0 0 oklch(0 0 0 / .18);
  display: grid; place-items: center; transition: transform .45s var(--aph-lift-spring), opacity .3s;
  transition-delay: calc(var(--i) * 45ms);
  & span { font: 800 8px/1 system-ui; writing-mode: vertical-rl; transform: rotate(180deg); color: oklch(0 0 0 / .55); letter-spacing: .04em; }
  &[data-w="25"] { --pw: 24px; --ph: 92px; --pc: oklch(0.58 0.19 27); }
  &[data-w="20"] { --pw: 21px; --ph: 92px; --pc: oklch(0.55 0.14 255); }
  &[data-w="15"] { --pw: 18px; --ph: 92px; --pc: oklch(0.84 0.15 95); }
  &[data-w="10"] { --pw: 15px; --ph: 92px; --pc: oklch(0.6 0.14 150); }
  &[data-w="5"] { --pw: 11px; --ph: 54px; --pc: oklch(0.93 0.004 95); }
  &[data-w="2.5"] { --pw: 9px; --ph: 44px; --pc: oklch(0.33 0.01 255); }
  &[data-w="1.25"] { --pw: 7px; --ph: 36px; --pc: oklch(0.8 0.01 255); }
  &[data-w="2.5"] span { color: oklch(1 0 0 / .6); }
  &[data-w="5"] span, &[data-w="2.5"] span, &[data-w="1.25"] span { font-size: 6.5px; }
  @starting-style { transform: translateX(var(--from, 40px)) scaleY(.6); opacity: 0; }
  &.is-out { transform: translateX(var(--from, 40px)) scaleY(.6); opacity: 0; transition-delay: 0ms; }
}
.aph-lift .aph-lift-sleeve.is-l .aph-lift-plate { --from: -40px; }
.aph-lift .aph-lift-legend {
  display: flex; flex-wrap: wrap; gap: 6px; font-size: 11.5px; color: var(--aph-lift-mute); font-variant-numeric: tabular-nums;
  & span { display: inline-flex; align-items: center; gap: 5px; padding: 3px 8px 3px 6px; border-radius: 99px; background: var(--aph-lift-panel); }
  & i { width: 8px; height: 8px; border-radius: 2px; background: var(--pc); }
}
.aph-lift .aph-lift-bells {
  height: 92px; display: flex; align-items: center; justify-content: center; gap: 22%;
  & svg { width: 120px; height: 52px; stroke-width: 1.4; color: var(--aph-lift-mute); }
  & .aph-lift-bellw { font: 700 15px/1 ui-monospace, Menlo, monospace; fill: var(--aph-lift-ink); stroke: none; }
}
.aph-lift .aph-lift-stack {
  height: 92px; display: flex; align-items: flex-end; justify-content: center; gap: 3px;
  & i { width: 10px; border-radius: 2px; background: var(--aph-lift-line2); height: calc(30% + var(--k) * 3.2%); transition: background .25s; transition-delay: calc(var(--k) * 12ms); }
  & i.is-on { background: var(--aph-lift-accent); }
  & i.is-half { background: linear-gradient(var(--aph-lift-line2) 50%, var(--aph-lift-accent) 50%); }
}

/* ── aside: rest ring + records ── */
.aph-lift .aph-lift-aside {
  grid-area: aside; overflow: auto; overscroll-behavior: contain; border-left: 1px solid var(--aph-lift-line); padding: 16px 16px 20px;
  display: grid; align-content: start; gap: 14px; scrollbar-width: thin; scrollbar-color: var(--aph-lift-line2) transparent;
}
.aph-lift .aph-lift-rest {
  position: relative; display: grid; justify-items: center; gap: 12px; padding: 18px 14px 14px; border-radius: 16px; background: var(--aph-lift-panel); border: 1px solid var(--aph-lift-line);
  --aph-lift-a: 360deg;
  & .aph-lift-ring {
    position: relative; width: min(190px, 62cqi); aspect-ratio: 1; border-radius: 50%;
    background: conic-gradient(from 0deg, var(--aph-lift-accent) var(--aph-lift-a), var(--aph-lift-line) 0);
    mask: radial-gradient(farthest-side, transparent calc(100% - 9px), #000 calc(100% - 8px));
    transition: --aph-lift-a 1s linear;
  }
  & .aph-lift-ring i { position: absolute; inset: 0; border-radius: 50%; }
  & .aph-lift-restface { position: absolute; top: 18px; width: min(190px, 62cqi); aspect-ratio: 1; display: grid; place-content: center; text-align: center; pointer-events: none; }
  & .aph-lift-restface small { font-size: 10px; text-transform: uppercase; letter-spacing: .14em; color: var(--aph-lift-faint); font-weight: 700; }
  & .aph-lift-restface output { font: 700 clamp(34px, 4cqi, 46px)/1 ui-monospace, Menlo, monospace; letter-spacing: -.05em; font-variant-numeric: tabular-nums; }
  & .aph-lift-restface span { font-size: 11.5px; color: var(--aph-lift-mute); margin-top: 4px; max-width: 140px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .aph-lift-restctl { display: flex; gap: 6px; }
  & .aph-lift-restctl > button { height: 38px; min-width: 50px; border-radius: 10px; background: var(--aph-lift-raise); font: 650 12.5px/1 ui-monospace, Menlo, monospace; transition: transform .15s var(--aph-lift-snap), background .15s; }
  & .aph-lift-restctl > button:active { transform: scale(.93); }
  & .aph-lift-restctl .aph-lift-restgo { min-width: 104px; display: inline-flex; align-items: center; justify-content: center; gap: 7px; background: var(--aph-lift-ink); color: var(--aph-lift-bg); font: 750 13px/1 system-ui; }
  & .aph-lift-restgo kbd { color: color-mix(in oklch, var(--aph-lift-bg) 60%, transparent); border-color: color-mix(in oklch, var(--aph-lift-bg) 30%, transparent); }
  & .aph-lift-skip { font-size: 12px; color: var(--aph-lift-mute); text-decoration: underline; text-underline-offset: 3px; text-decoration-color: var(--aph-lift-line2); padding: 2px 6px; }
  &[data-state="run"] .aph-lift-ring { filter: drop-shadow(0 0 10px color-mix(in oklch, var(--aph-lift-accent) 45%, transparent)); }
  &[data-state="paused"] .aph-lift-ring { opacity: .55; }
  &[data-state="done"] .aph-lift-ring { background: var(--aph-lift-gold); animation: aph-lift-done 1.2s var(--aph-lift-ease) 2; }
  &[data-state="done"] output { color: var(--aph-lift-gold); }
}
.aph-lift .aph-lift-records {
  display: grid; gap: 12px; padding: 14px; border-radius: 16px; border: 1px solid var(--aph-lift-line);
  & header { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
  & header h3 { font-size: 13px; font-weight: 700; }
  & header small { font-size: 11px; color: var(--aph-lift-faint); }
  & .aph-lift-tiles { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
  & .aph-lift-tile { padding: 8px 9px; border-radius: 10px; background: var(--aph-lift-panel); display: grid; gap: 2px; min-width: 0; }
  & .aph-lift-tile small { font-size: 9.5px; text-transform: uppercase; letter-spacing: .1em; color: var(--aph-lift-faint); font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .aph-lift-tile b { font: 700 15px/1.1 ui-monospace, Menlo, monospace; letter-spacing: -.03em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & .aph-lift-tile span { font-size: 10.5px; color: var(--aph-lift-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .aph-lift-tile.is-pr b { color: var(--aph-lift-gold); }
  & .aph-lift-chart { width: 100%; height: auto; display: block; overflow: visible; }
  & .aph-lift-chart text { font: 600 9px ui-monospace, Menlo, monospace; fill: var(--aph-lift-faint); stroke: none; }
  & .aph-lift-chart .aph-lift-grid { stroke: var(--aph-lift-line); stroke-width: 1; }
  & .aph-lift-chart .aph-lift-line { stroke: var(--aph-lift-mute); stroke-width: 1.8; }
  & .aph-lift-chart .aph-lift-area { fill: color-mix(in oklch, var(--aph-lift-ink) 6%, transparent); stroke: none; }
  & .aph-lift-chart .aph-lift-best { stroke: var(--aph-lift-gold); stroke-dasharray: 3 4; stroke-width: 1.2; }
  & .aph-lift-chart circle { fill: var(--aph-lift-bg); stroke: var(--aph-lift-mute); stroke-width: 1.8; }
  & .aph-lift-chart circle.is-pr { stroke: var(--aph-lift-gold); fill: var(--aph-lift-gold); }
  & .aph-lift-chart circle.is-today { stroke: var(--aph-lift-accent); fill: var(--aph-lift-accent); r: 4.5px; }
  & .aph-lift-chart .aph-lift-draw { stroke-dasharray: 600; animation: aph-lift-draw 1.1s var(--aph-lift-ease) both; }
  & footer { font-size: 11px; color: var(--aph-lift-faint); }
}

/* ── tabs (narrow) ── */
.aph-lift .aph-lift-tabs {
  grid-area: tabs; display: none; border-top: 1px solid var(--aph-lift-line); background: var(--aph-lift-sunk); padding: 6px 8px;
  & button { flex: 1; display: grid; justify-items: center; gap: 2px; padding: 5px 0 3px; border-radius: 9px; color: var(--aph-lift-faint); font-size: 10.5px; font-weight: 650; transition: color .15s, background .15s; }
  & button[aria-current="page"] { color: var(--aph-lift-accent); background: var(--aph-lift-panel); }
}

/* ── floating layers ── */
.aph-lift .aph-lift-pill {
  position: absolute; left: 50%; top: 70px; translate: -50% 0; z-index: 6; display: flex; align-items: center; gap: 8px;
  height: 40px; padding: 0 16px 0 12px; border-radius: 99px; background: var(--aph-lift-ink); color: var(--aph-lift-bg);
  box-shadow: 0 10px 30px oklch(0 0 0 / .45); font: 700 15px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
  transition: translate .4s var(--aph-lift-spring), opacity .25s;
  & small { font: 600 11px/1 system-ui; color: color-mix(in oklch, var(--aph-lift-bg) 65%, transparent); }
  & .aph-lift-pilldot { width: 8px; height: 8px; border-radius: 50%; background: var(--aph-lift-accent); animation: aph-lift-blink 1s steps(2) infinite; }
  @starting-style { translate: -50% -24px; opacity: 0; }
}
.aph-lift .aph-lift-menu {
  position: absolute; z-index: 20; min-width: 250px; padding: 6px; border-radius: 12px; background: var(--aph-lift-raise);
  border: 1px solid var(--aph-lift-line2); box-shadow: 0 18px 50px oklch(0 0 0 / .5);
  transform-origin: top right; transition: opacity .18s, transform .22s var(--aph-lift-ease);
  @starting-style { opacity: 0; transform: translateY(-6px) scale(.97); }
  & > small { display: block; padding: 6px 10px 4px; font-size: 10px; text-transform: uppercase; letter-spacing: .12em; color: var(--aph-lift-faint); font-weight: 700; }
  & button { width: 100%; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 1px 10px; text-align: left; padding: 8px 10px; border-radius: 8px; }
  & button span { font-size: 11.5px; color: var(--aph-lift-mute); }
  & button em { grid-row: span 2; align-self: center; font-style: normal; font-size: 10px; text-transform: uppercase; letter-spacing: .08em; color: var(--aph-lift-faint); }
  & button:hover, & button:focus-visible { background: var(--aph-lift-panel); outline: none; }
}
.aph-lift .aph-lift-scrim {
  position: absolute; inset: 0; z-index: 30; background: oklch(0.1 0.01 255 / .6); backdrop-filter: blur(2px);
  transition: opacity .25s; @starting-style { opacity: 0; }
}
.aph-lift .aph-lift-sheet {
  position: absolute; z-index: 31; left: 50%; top: 50%; width: min(460px, calc(100% - 28px)); max-height: calc(100% - 40px); overflow: auto;
  translate: -50% -50%; padding: 20px; border-radius: 18px; background: var(--aph-lift-panel); border: 1px solid var(--aph-lift-line2);
  box-shadow: 0 30px 80px oklch(0 0 0 / .6); transition: opacity .25s, transform .4s var(--aph-lift-spring);
  @starting-style { opacity: 0; transform: translateY(18px) scale(.97); }
  & h3 { font-size: 19px; font-weight: 800; letter-spacing: -.02em; }
  & .aph-lift-shsub { color: var(--aph-lift-mute); font-size: 12.5px; margin-top: 2px; }
  & .aph-lift-sum { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin: 16px 0; }
  & .aph-lift-sum div { padding: 10px; border-radius: 11px; background: var(--aph-lift-raise); }
  & .aph-lift-sum small { display: block; font-size: 10px; text-transform: uppercase; letter-spacing: .1em; color: var(--aph-lift-faint); font-weight: 700; }
  & .aph-lift-sum b { font: 700 18px/1.2 ui-monospace, Menlo, monospace; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & table { width: 100%; border-collapse: collapse; font-size: 12.5px; font-variant-numeric: tabular-nums; }
  & th { text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: .1em; color: var(--aph-lift-faint); font-weight: 700; padding: 0 0 6px; }
  & td { padding: 7px 0; border-top: 1px solid var(--aph-lift-line); vertical-align: top; }
  & td:last-child, & th:last-child { text-align: right; font-family: ui-monospace, Menlo, monospace; }
  & td span { color: var(--aph-lift-mute); font-size: 11.5px; }
  & tfoot td { font-weight: 750; border-top: 1px solid var(--aph-lift-line2); }
  & .aph-lift-prs { margin-top: 12px; display: flex; flex-wrap: wrap; gap: 6px; }
  & .aph-lift-prs span { font-size: 11.5px; padding: 4px 9px; border-radius: 99px; background: color-mix(in oklab, var(--aph-lift-gold) 18%, var(--aph-lift-panel)); color: var(--aph-lift-gold); font-weight: 650; }
  & .aph-lift-shacts { display: flex; justify-content: flex-end; gap: 8px; margin-top: 18px; }
}
.aph-lift .aph-lift-toast {
  position: absolute; z-index: 40; left: 50%; bottom: 18px; translate: -50% 0; display: flex; align-items: center; gap: 12px;
  padding: 9px 9px 9px 14px; border-radius: 12px; background: var(--aph-lift-ink); color: var(--aph-lift-bg); font-weight: 600; font-size: 12.5px;
  box-shadow: 0 14px 40px oklch(0 0 0 / .5); transition: opacity .25s, translate .45s var(--aph-lift-spring); white-space: nowrap; max-width: calc(100% - 24px);
  &:empty { display: none; }
  &.is-pr { background: var(--aph-lift-gold); color: oklch(0.22 0.05 80); }
  & button { height: 28px; padding: 0 10px; border-radius: 8px; background: color-mix(in oklch, var(--aph-lift-bg) 12%, transparent); font-weight: 750; }
  @starting-style { opacity: 0; translate: -50% 16px; }
}

/* ── motion ── */
@keyframes aph-lift-in { from { opacity: 0; transform: translateY(-6px); } }
@keyframes aph-lift-row { from { opacity: 0; transform: translateY(-8px); clip-path: inset(0 0 100% 0); } to { clip-path: inset(0); } }
@keyframes aph-lift-pr { 0% { transform: scale(.2) rotate(-12deg); opacity: 0; } 60% { transform: scale(1.25) rotate(3deg); opacity: 1; } 100% { transform: none; } }
@keyframes aph-lift-done { 50% { transform: scale(1.04); filter: brightness(1.2); } }
@keyframes aph-lift-blink { 50% { opacity: .25; } }
@keyframes aph-lift-draw { from { stroke-dashoffset: 600; } to { stroke-dashoffset: 0; } }
@keyframes aph-lift-flash { from { background: color-mix(in oklab, var(--aph-lift-accent) 35%, var(--aph-lift-sunk)); } }
.aph-lift .is-flash { animation: aph-lift-flash .6s var(--aph-lift-ease); }

/* the exercise header sticks while the log scrolls; a scroll-driven shadow appears once content passes under it */
.aph-lift .aph-lift-exhead { position: sticky; top: -18px; z-index: 3; background: var(--aph-lift-bg); margin: -18px -22px 12px; padding: 18px 22px 12px; }
@supports (animation-timeline: scroll()) {
  .aph-lift .aph-lift-exhead { animation: aph-lift-stuck linear both; animation-timeline: scroll(nearest block); animation-range: 0 36px; }
}
@keyframes aph-lift-stuck { to { box-shadow: 0 1px 0 var(--aph-lift-line2), 0 14px 22px -14px oklch(0 0 0 / .7); } }

/* ── responsive: the component's own width, never the window ── */
@container aph-lift (max-width: 1099px) {
  .aph-lift .aph-lift-app { grid-template-columns: 214px minmax(0, 1fr) 272px; }
