}
@container aph-lift (max-width: 959px) {
  .aph-lift .aph-lift-app { grid-template-columns: 210px minmax(0, 1fr); grid-template-areas: "top top" "side main" "tabs tabs"; }
  .aph-lift .aph-lift-aside { grid-area: main; border-left: 0; }
  .aph-lift .aph-lift-tabs { display: flex; }
  .aph-lift .aph-lift-tabs [data-view-to="ex"] { display: none; }
  .aph-lift[data-view="prog"] .aph-lift-main { display: none; }
  .aph-lift:not([data-view="prog"]) .aph-lift-aside { display: none; }
  .aph-lift .aph-lift-brand b { display: none; }
  .aph-lift .aph-lift-toast { bottom: 72px; }
}
@container aph-lift (max-width: 759px) {
  .aph-lift .aph-lift-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "main" "tabs"; }
  .aph-lift .aph-lift-side { grid-area: main; border-right: 0; }
  .aph-lift:not([data-view="ex"]) .aph-lift-side { display: none; }
  .aph-lift[data-view="ex"] .aph-lift-main { display: none; }
  .aph-lift .aph-lift-tabs [data-view-to="ex"] { display: grid; }
  .aph-lift .aph-lift-top { gap: 10px; padding: 10px 12px; }
  .aph-lift .aph-lift-brand { display: none; }
  .aph-lift .aph-lift-title p .aph-lift-sep, .aph-lift .aph-lift-title p span:first-child { display: none; }
  .aph-lift .aph-lift-main { padding: 14px 12px 20px; }
  .aph-lift .aph-lift-exhead { top: -14px; margin: -14px -12px 12px; padding: 14px 12px 10px; }
  .aph-lift .aph-lift-table { grid-template-columns: 38px minmax(0, 1fr) 70px 48px 40px 42px; column-gap: 4px; }
  .aph-lift .aph-lift-clock { margin-left: auto; }
}
@container aph-lift (max-width: 459px) {
  .aph-lift .aph-lift-table { grid-template-columns: 36px 0 minmax(64px, 1fr) 46px 36px 40px; }
  .aph-lift .aph-lift-prev { visibility: hidden; overflow: hidden; }
  .aph-lift .aph-lift-title h2 span { display: none; }
  .aph-lift .aph-lift-clock small { display: none; }
  .aph-lift .aph-lift-finish span { display: none; }
  .aph-lift .aph-lift-finish { padding: 0 10px; }
  .aph-lift .aph-lift-exhead .aph-lift-acts .aph-lift-ghost span { display: none; }
}

@container aph-lift-main (max-width: 579px) {
  .aph-lift .aph-lift-editor { grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "cap cap" "w r" "rpe rpe" "go est"; }
  .aph-lift .aph-lift-editor .aph-lift-go { justify-self: start; }
  .aph-lift .aph-lift-addrow .aph-lift-hint { display: none; }
}
@container aph-lift-main (max-width: 400px) {
  .aph-lift .aph-lift-editor { grid-template-columns: minmax(0, 1fr); grid-template-areas: "cap" "w" "r" "rpe" "est" "go"; padding: 12px; }
