  .aph-lift .aph-lift-editor .aph-lift-cap .aph-lift-ghost span { font-size: 11.5px; }
}

@media (prefers-reduced-motion: reduce) {
  .aph-lift *, .aph-lift *::before, .aph-lift *::after { animation-duration: 1ms !important; animation-iteration-count: 1 !important; transition-duration: 1ms !important; transition-delay: 0ms !important; }
  .aph-lift .aph-lift-exhead { animation: none !important; }
  .aph-lift .aph-lift-rest .aph-lift-ring { transition: none; }
  .aph-lift .aph-lift-pilldot { animation: none !important; }
}

