/* Barline. Every number on screen is derived from the set list: progress, volume,
   e1RM (Epley: w × (1 + reps / 30)), PRs against history, and the plates on the bar. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const kg = w => String(Math.round(w * 100) / 100);
const big = n => Math.round(n).toLocaleString('en-GB');
const one = n => (Math.round(n * 10) / 10).toFixed(1);
const e1 = (w, r) => (r > 0 ? w * (1 + r / 30) : 0);
const mmss = s => { s = Math.max(0, Math.round(s)); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };
const snap = (v, step) => Math.round(v / step) * step;

