      '<div class="aph-lift-tile' + (heavy.d === 'Today' ? ' is-pr' : '') + '"><small>Heaviest</small><b>' + kg(heavy.w) + '×' + heavy.r + '</b><span>' + esc(heavy.d) + '</span></div>' +
      '<div class="aph-lift-tile' + (vb.d === 'Today' ? ' is-pr' : '') + '"><small>Volume</small><b>' + big(vb.v) + '</b><span>' + esc(vb.d) + '</span></div></div>' +
    '<svg class="aph-lift-chart" viewBox="0 0 ' + W + ' ' + Hh + '" role="img" aria-label="Estimated one-rep max per session, ' + one(pts[0].e) + ' to ' + one(pts[pts.length - 1].e) + ' kg">' +
      '<line class="aph-lift-grid" x1="' + padL + '" x2="' + (W - padR) + '" y1="' + Y(hi) + '" y2="' + Y(hi) + '"/><line class="aph-lift-grid" x1="' + padL + '" x2="' + (W - padR) + '" y1="' + Y(lo) + '" y2="' + Y(lo) + '"/>' +
      '<text x="' + (padL - 6) + '" y="' + (Y(hi) + 3) + '" text-anchor="end">' + hi + '</text><text x="' + (padL - 6) + '" y="' + (Y(lo) + 3) + '" text-anchor="end">' + lo + '</text>' +
