    case ' ': if (onBtn) return; e.preventDefault(); restToggle(); break;
    case 'n': case 'N': e.preventDefault(); addSet(); break;
    case 'j': case 'J': { const i = S.order.indexOf(S.cur); if (i < S.order.length - 1) selectEx(S.order[i + 1]); break; }
    case 'k': case 'K': { const i = S.order.indexOf(S.cur); if (i > 0) selectEx(S.order[i - 1]); break; }
    case 'Delete': case 'Backspace': e.preventDefault(); delSet(); break;
    case 'Escape': if (S.view !== 'log' && root.clientWidth < 960) setView('log'); break;
  }
});
root.addEventListener('pointerdown', e => { if (!e.target.closest('[data-menu], [data-act="swap"]')) closeMenu(); });

/* ── clock: one interval for elapsed time and the rest ring; it renders only while visible ── */
let visible = true, lastSec = -1;
const io = new IntersectionObserver(([en]) => { visible = en.isIntersecting; if (visible) tick(); });
io.observe(root);
function tick() {
  if (!root.isConnected) { clearInterval(iv); io.disconnect(); ro.disconnect(); return; }
  if (R.st === 'run' && Date.now() >= R.end) {
    R.st = 'done'; renderRest();
    if (visible && !doc.hidden) toast('Rest’s up · ' + LIB[R.ex].n + ', next set');
  }
  if (!visible || doc.hidden) return;
  const el = Math.floor((Date.now() - S.t0) / 1000);
  if (el !== lastSec) { lastSec = el; $('[data-elapsed]').textContent = Math.floor(el / 60) + ':' + String(el % 60).padStart(2, '0'); if (R.st === 'run') renderRest(); }
}
const iv = setInterval(() => { if (!root.isConnected) { clearInterval(iv); io.disconnect(); ro.disconnect(); return; } tick(); }, 250);
let lastW = 0;
const ro = new ResizeObserver(([en]) => {
  const w = en.contentRect.width;
  if ((w >= 760) !== (lastW >= 760) || (w >= 960) !== (lastW >= 960)) { lastW = w; if (S.view === 'ex' && w >= 760) setView('log'); else setView(S.view); }
  lastW = w;
});
ro.observe(root);

setView('log');
render();

css:
/* Tally: a habit tracker. The year is 12 rows of up to 31 days; consecutive
   days join into rails, so a streak reads as one continuous bar. */
@property --aph-habits-hc { syntax: "<color>"; inherits: true; initial-value: oklch(0.66 0.13 75); }
@property --aph-habits-n { syntax: "<integer>"; inherits: false; initial-value: 0; }
@property --aph-habits-v { syntax: "<number>"; inherits: false; initial-value: 0; }

.aph-habits {
  /* re-theme: paper, ink, accent (the habit colour arrives as --aph-habits-hc) */
  --aph-habits-paper: oklch(0.972 0.012 88);
  --aph-habits-ink: oklch(0.27 0.025 55);
  --aph-habits-accent: oklch(0.55 0.13 42);
  --aph-habits-card: color-mix(in oklab, var(--aph-habits-paper) 45%, white);
  --aph-habits-sunk: color-mix(in oklab, var(--aph-habits-paper) 93%, var(--aph-habits-ink));
  --aph-habits-line: color-mix(in oklab, var(--aph-habits-ink) 10%, transparent);
  --aph-habits-line2: color-mix(in oklab, var(--aph-habits-ink) 19%, transparent);
  --aph-habits-mute: color-mix(in oklab, var(--aph-habits-ink) 62%, var(--aph-habits-paper));
  --aph-habits-faint: color-mix(in oklab, var(--aph-habits-ink) 40%, var(--aph-habits-paper));
  --aph-habits-empty: color-mix(in oklab, var(--aph-habits-ink) 7%, var(--aph-habits-paper));
  --aph-habits-soft: color-mix(in oklab, var(--aph-habits-hc) 30%, var(--aph-habits-paper));
  --aph-habits-deep: color-mix(in oklab, var(--aph-habits-hc) 78%, var(--aph-habits-ink));
  --aph-habits-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --aph-habits-ease: cubic-bezier(.2, .8, .2, 1);
  --aph-habits-spring: linear(0, 0.1 4%, 0.38 10%, 0.75 17%, 0.98 24%, 1.06 30%, 1.06 36%, 1.02 46%, 0.995 60%, 1);

  position: relative; width: 100%; height: var(--aph-habits-h, 680px);
  container-type: inline-size; container-name: aph-habits; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--aph-habits-paper); color: var(--aph-habits-ink); color-scheme: light; accent-color: var(--aph-habits-deep);
  border-radius: 14px; font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  transition: --aph-habits-hc .55s var(--aph-habits-ease);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--aph-habits-ink); outline-offset: 2px; border-radius: 6px; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button[aria-disabled="true"], & button:disabled { cursor: not-allowed; }
  & h2, & h3, & h4, & p, & ul, & ol, & dl, & dd, & figure { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & h2, & h3 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; display: inline-block; text-align: center; border: 1px solid var(--aph-habits-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--aph-habits-mute); background: var(--aph-habits-card); }
  & [hidden] { display: none !important; }
}

.aph-habits .aph-habits-app { height: 100%; display: grid; grid-template-columns: 296px minmax(0, 1fr); grid-template-areas: "side main"; }

/* ── side ── */
.aph-habits .aph-habits-side {
  grid-area: side; display: grid; grid-template-rows: auto auto minmax(0, 1fr) auto auto; min-height: 0;
  border-right: 1px solid var(--aph-habits-line); background: var(--aph-habits-sunk);
}
.aph-habits .aph-habits-today { padding: 16px 18px 12px; display: grid; gap: 14px; }
.aph-habits .aph-habits-brand {
  display: flex; align-items: center; gap: 8px;
  & svg { width: 22px; height: 22px; color: var(--aph-habits-accent); stroke-width: 2; }
  & b { font: 700 16px/1 var(--aph-habits-serif); letter-spacing: -.01em; }
}
.aph-habits .aph-habits-daycard {
  display: flex; align-items: center; gap: 14px;
  & h2 { font: 600 clamp(22px, 2.4cqi, 28px)/1 var(--aph-habits-serif); letter-spacing: -.02em; }
  & p { color: var(--aph-habits-mute); margin-top: 4px; font-variant-numeric: tabular-nums; }
}
.aph-habits .aph-habits-dayring {
  --aph-habits-v: 0; width: 52px; height: 52px; border-radius: 50%; flex: none; position: relative;
  background: conic-gradient(var(--aph-habits-ink) calc(var(--aph-habits-v) * 1turn), var(--aph-habits-line2) 0);
  mask: radial-gradient(farthest-side, transparent calc(100% - 6px), #000 calc(100% - 5.5px));
  transition: --aph-habits-v .8s var(--aph-habits-spring);
}
.aph-habits .aph-habits-chips {
  display: flex; flex-wrap: wrap; gap: 5px 4px; padding: 0 14px 10px;
  & button { height: 28px; padding: 0 11px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--aph-habits-mute); border: 1px solid var(--aph-habits-line2); white-space: nowrap; transition: background .15s, color .15s, border-color .15s; }
  & button:hover { color: var(--aph-habits-ink); }
  & button[aria-selected="true"] { background: var(--aph-habits-ink); border-color: var(--aph-habits-ink); color: var(--aph-habits-paper); }
  & button span { opacity: .6; margin-left: 4px; font-variant-numeric: tabular-nums; }
}
.aph-habits .aph-habits-list {
  overflow: auto; overscroll-behavior: contain; padding: 2px 10px 10px; display: grid; align-content: start; gap: 2px;
  scrollbar-width: thin; scrollbar-color: var(--aph-habits-line2) transparent;
}
.aph-habits .aph-habits-item {
  --c: var(--aph-habits-ink);
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 8px; border-radius: 12px;
  transition: background .2s;
  &:hover { background: color-mix(in oklab, var(--aph-habits-paper) 60%, white); }
  &:has(.aph-habits-pick[aria-current="true"]) { background: var(--aph-habits-card); box-shadow: 0 1px 0 var(--aph-habits-line), 0 6px 18px -10px color-mix(in oklab, var(--aph-habits-ink) 40%, transparent); }
  &.is-new { animation: aph-habits-in .5s var(--aph-habits-ease); }
}
.aph-habits .aph-habits-pick {
  display: grid; grid-template-columns: 10px minmax(0, 1fr); gap: 1px 10px; align-items: center; text-align: left; padding: 10px 0 10px 12px; min-width: 0;
  & i { grid-row: span 2; width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & b { font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & span { font-size: 11.5px; color: var(--aph-habits-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & span em { font-style: normal; color: var(--aph-habits-ink); font-weight: 650; }
}
.aph-habits .aph-habits-check {
  position: relative; width: 40px; height: 40px; margin-right: 8px; border-radius: 50%; display: grid; place-items: center;
  --p: 0; background: conic-gradient(var(--c) calc(var(--p) * 1turn), var(--aph-habits-line) 0);
  transition: transform .25s var(--aph-habits-spring);
  &::before { content: ""; position: absolute; inset: 3px; border-radius: 50%; background: var(--aph-habits-paper); transition: inset .3s var(--aph-habits-spring), background .2s; }
  & svg { position: relative; width: 18px; height: 18px; stroke-width: 2.4; color: var(--aph-habits-faint); }
  & svg path { stroke-dasharray: 20; stroke-dashoffset: 20; transition: stroke-dashoffset .35s var(--aph-habits-ease) .08s; }
  & small { position: relative; font: 700 10px/1 ui-monospace, Menlo, monospace; color: var(--aph-habits-mute); font-variant-numeric: tabular-nums; }
  &:hover svg path { stroke-dashoffset: 12; }
  &[aria-pressed="true"]::before { inset: 0; background: var(--c); }
  &[aria-pressed="true"] svg { color: white; }
  &[aria-pressed="true"] svg path { stroke-dashoffset: 0; }
  &[aria-pressed="true"] small { color: white; }
  &.is-week::before { background: color-mix(in oklab, var(--c) 18%, var(--aph-habits-paper)); }
  &.is-week svg { color: var(--c); }
  &.is-week svg path { stroke-dashoffset: 0; }
  &:active { transform: scale(.88); }
}
.aph-habits .aph-habits-archived {
  padding: 0 18px 8px; font-size: 12px; color: var(--aph-habits-mute);
  &:empty { display: none; }
  & > button { text-decoration: underline; text-underline-offset: 3px; text-decoration-color: var(--aph-habits-line2); }
  & ul { margin-top: 6px; display: grid; gap: 4px; }
  & li { display: flex; justify-content: space-between; gap: 8px; align-items: center; }
  & li button { font-weight: 650; color: var(--aph-habits-ink); padding: 3px 8px; border-radius: 6px; border: 1px solid var(--aph-habits-line2); }
}
.aph-habits .aph-habits-sidefoot {
  display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 10px 14px 14px; border-top: 1px solid var(--aph-habits-line);
}
.aph-habits .aph-habits-new {
  display: inline-flex; align-items: center; gap: 6px; height: 34px; padding: 0 12px 0 9px; border-radius: 10px;
  background: var(--aph-habits-ink); color: var(--aph-habits-paper); font-weight: 650;
  transition: transform .15s var(--aph-habits-ease);
  & kbd { background: transparent; color: color-mix(in oklab, var(--aph-habits-paper) 70%, transparent); border-color: color-mix(in oklab, var(--aph-habits-paper) 35%, transparent); }
  &:active { transform: scale(.96); }
}
.aph-habits .aph-habits-keys { font-size: 11px; color: var(--aph-habits-faint); display: flex; align-items: center; gap: 3px; }

/* ── main ── */
.aph-habits .aph-habits-main {
  grid-area: main; overflow: auto; overscroll-behavior: contain; padding: 18px 24px 24px; min-width: 0;
  container-type: inline-size; container-name: aph-habits-main;
  scrollbar-width: thin; scrollbar-color: var(--aph-habits-line2) transparent;
}
.aph-habits .aph-habits-head {
  display: flex; align-items: flex-start; gap: 14px;
  & .aph-habits-back { display: none; width: 36px; height: 36px; border-radius: 10px; place-items: center; border: 1px solid var(--aph-habits-line2); flex: none; }
  & .aph-habits-swatch { width: 14px; height: 14px; margin-top: 9px; border-radius: 4px; background: var(--aph-habits-hc); flex: none; box-shadow: 0 0 0 4px color-mix(in oklab, var(--aph-habits-hc) 20%, transparent); }
  & h2 { font: 600 clamp(24px, 4.2cqi, 34px)/1.05 var(--aph-habits-serif); letter-spacing: -.025em; }
  & p { color: var(--aph-habits-mute); margin-top: 5px; }
  & .aph-habits-headtx { flex: 1; min-width: 0; }
  & .aph-habits-more { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; border: 1px solid var(--aph-habits-line2); flex: none; transition: background .15s; }
  & .aph-habits-more:hover, & .aph-habits-more[aria-expanded="true"] { background: var(--aph-habits-card); }
}
.aph-habits .aph-habits-stats {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; margin: 16px 0 18px;
  & > div { padding: 11px 13px 12px; border-radius: 12px; background: var(--aph-habits-card); border: 1px solid var(--aph-habits-line); min-width: 0; }
  & small { display: block; font-size: 10.5px; text-transform: uppercase; letter-spacing: .1em; font-weight: 700; color: var(--aph-habits-faint); }
  & b { display: block; font: 600 clamp(22px, 3.6cqi, 30px)/1.1 var(--aph-habits-serif); letter-spacing: -.02em; font-variant-numeric: tabular-nums; margin-top: 2px; }
  & b sub { font: 600 12px system-ui; vertical-align: baseline; color: var(--aph-habits-mute); margin-left: 3px; letter-spacing: 0; }
  & span { font-size: 11.5px; color: var(--aph-habits-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; display: block; }
  & .is-hot b { color: var(--aph-habits-deep); }
  & .aph-habits-count { font-style: normal; counter-reset: aph-habits-n var(--aph-habits-n); transition: --aph-habits-n .7s var(--aph-habits-ease); }
  & .aph-habits-count::before { content: counter(aph-habits-n); }
}
.aph-habits .aph-habits-bar {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 12px; flex-wrap: wrap;
}
.aph-habits .aph-habits-seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--aph-habits-sunk); border: 1px solid var(--aph-habits-line);
  & button { height: 28px; padding: 0 12px; border-radius: 7px; font-weight: 600; font-size: 12.5px; color: var(--aph-habits-mute); display: inline-flex; align-items: center; gap: 6px; transition: background .2s, color .2s; }
  & button[aria-selected="true"] { background: var(--aph-habits-card); color: var(--aph-habits-ink); box-shadow: 0 1px 2px color-mix(in oklab, var(--aph-habits-ink) 18%, transparent); }
  & button kbd { padding: 1px 3px; min-width: 14px; font-size: 9px; }
}
.aph-habits .aph-habits-nav {
  display: inline-flex; align-items: center; gap: 4px;
  & button { width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; border: 1px solid var(--aph-habits-line2); transition: background .15s; }
  & button:hover { background: var(--aph-habits-card); }
  & button[aria-disabled="true"] { opacity: .35; }
  & output { min-width: 112px; text-align: center; font: 600 15px/1 var(--aph-habits-serif); font-variant-numeric: tabular-nums; }
  & .aph-habits-totoday { width: auto; padding: 0 10px; font-size: 12px; font-weight: 600; }
}

/* the year: twelve subgrid rows that share one 31-day column template */
.aph-habits .aph-habits-cal { overflow-x: auto; overscroll-behavior-x: contain; padding: 2px 2px 6px; scrollbar-width: thin; }
.aph-habits .aph-habits-year {
  --gap: 3px; display: grid; grid-template-columns: 34px repeat(31, minmax(12px, 1fr)); gap: var(--gap); min-width: 500px;
  & .aph-habits-yrow { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center; }
  & .aph-habits-mlabel { font-size: 11px; font-weight: 650; color: var(--aph-habits-mute); letter-spacing: .02em; }
  & .aph-habits-dlabel { font: 600 9px/1 ui-monospace, Menlo, monospace; color: var(--aph-habits-faint); text-align: center; font-variant-numeric: tabular-nums; }
}
.aph-habits .aph-habits-cell {
  position: relative; aspect-ratio: 1; border-radius: 5px; background: var(--aph-habits-empty);
  transition: background .35s, transform .2s var(--aph-habits-spring), border-radius .2s;
  &:hover:not([aria-disabled="true"]) { transform: scale(1.18); z-index: 2; }
  &.is-part { background: color-mix(in oklab, var(--aph-habits-hc) calc(var(--f) * 55% + 12%), var(--aph-habits-paper)); }
  &.is-done { background: var(--aph-habits-hc); }
  &.is-done.is-cur { background: var(--aph-habits-deep); }
  &.jr { border-top-right-radius: 1px; border-bottom-right-radius: 1px; }
  &.jl { border-top-left-radius: 1px; border-bottom-left-radius: 1px; }
  &.jr::after { content: ""; position: absolute; left: 100%; top: 26%; bottom: 26%; width: var(--gap, 3px); background: inherit; }
  &.is-off { background: repeating-linear-gradient(135deg, transparent 0 3px, var(--aph-habits-line) 3px 4px); }
  &.is-future { background: transparent; box-shadow: inset 0 0 0 1px var(--aph-habits-line); }
  &.is-today { box-shadow: 0 0 0 2px var(--aph-habits-paper), 0 0 0 3.5px var(--aph-habits-ink); }
  &.is-wknd:not(.is-done):not(.is-part):not(.is-future):not(.is-off)::before { content: ""; position: absolute; left: 50%; bottom: 3px; width: 3px; height: 3px; margin-left: -1.5px; border-radius: 50%; background: var(--aph-habits-line2); }
  &[aria-disabled="true"] { cursor: default; }
  &.is-ripple { animation: aph-habits-ripple .7s var(--aph-habits-ease) both; animation-delay: calc(var(--i) * 28ms); }
  &.is-pop { animation: aph-habits-pop .5s var(--aph-habits-spring); }
}
.aph-habits .aph-habits-month {
  display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 6px; max-width: 640px;
  & .aph-habits-wd { font-size: 10.5px; text-transform: uppercase; letter-spacing: .1em; font-weight: 700; color: var(--aph-habits-faint); text-align: center; padding-bottom: 2px; }
  & .aph-habits-cell { aspect-ratio: 1.25; border-radius: 10px; display: grid; align-content: space-between; padding: 7px 8px; text-align: left; }
  & .aph-habits-cell b { font: 600 13px/1 var(--aph-habits-serif); font-variant-numeric: tabular-nums; }
  & .aph-habits-cell small { font: 600 10px/1 ui-monospace, Menlo, monospace; opacity: .8; font-variant-numeric: tabular-nums; }
  & .aph-habits-cell.is-done { color: white; }
  & .aph-habits-cell::after { display: none; }
  & .aph-habits-cell:hover:not([aria-disabled="true"]) { transform: translateY(-2px); }
}
.aph-habits .aph-habits-legend {
  display: flex; flex-wrap: wrap; gap: 6px 14px; align-items: center; margin: 10px 0 18px; font-size: 11.5px; color: var(--aph-habits-mute);
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }
  & .aph-habits-hint { margin-left: auto; color: var(--aph-habits-faint); display: inline-flex; gap: 3px; align-items: center; }
}
.aph-habits .aph-habits-cards {
  display: grid; grid-template-columns: 1.3fr 1fr 1fr; gap: 10px;
  & section { padding: 14px; border-radius: 14px; background: var(--aph-habits-card); border: 1px solid var(--aph-habits-line); min-width: 0; }
  & h3 { font-size: 11px; text-transform: uppercase; letter-spacing: .1em; font-weight: 700; color: var(--aph-habits-faint); margin-bottom: 12px; display: flex; justify-content: space-between; }
  & h3 span { text-transform: none; letter-spacing: 0; font-weight: 600; }
}
.aph-habits .aph-habits-bars {
  display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: 4px; height: 96px; align-items: end; position: relative;
  & .aph-habits-b { display: grid; grid-template-rows: minmax(0, 1fr) auto; height: 100%; gap: 4px; text-align: center; }
  & .aph-habits-b i { align-self: end; height: 100%; border-radius: 4px 4px 2px 2px; background: var(--aph-habits-hc); transform-origin: bottom; transform: scaleY(var(--v)); transition: transform .6s var(--aph-habits-spring), background .35s; transition-delay: calc(var(--i) * 30ms); }
  & .aph-habits-b i { @starting-style { transform: scaleY(0); } }
  & .aph-habits-b.is-empty i { background: var(--aph-habits-line); transform: scaleY(.04); }
  & .aph-habits-b.is-now i { background: var(--aph-habits-deep); }
  & .aph-habits-b span { font: 600 9.5px/1 ui-monospace, Menlo, monospace; color: var(--aph-habits-faint); }
  & .aph-habits-goal { position: absolute; left: 0; right: 0; border-top: 1.5px dashed var(--aph-habits-mute); pointer-events: none; }
  & .aph-habits-b { position: relative; }
  & .aph-habits-b em { position: absolute; left: 50%; translate: -50% 0; bottom: calc(var(--v) * (100% - 14px) + 18px); font: 650 9.5px/1 ui-monospace, Menlo, monospace; font-style: normal; color: var(--aph-habits-mute); opacity: 0; transition: opacity .2s; white-space: nowrap; }
  & .aph-habits-b:hover em { opacity: 1; }
}
.aph-habits .aph-habits-miles {
  display: grid; gap: 9px; font-size: 12.5px;
  & li { display: grid; grid-template-columns: 8px minmax(0, 1fr); gap: 10px; align-items: baseline; }
