const COLORS = [['Ochre', 'oklch(0.68 0.13 72)'], ['Moss', 'oklch(0.6 0.12 145)'], ['Plum', 'oklch(0.52 0.13 350)'], ['Lagoon', 'oklch(0.6 0.09 200)'], ['Slate', 'oklch(0.5 0.09 262)'], ['Clay', 'oklch(0.58 0.14 38)'], ['Walnut', 'oklch(0.48 0.07 60)'], ['Fern', 'oklch(0.55 0.1 170)']];
