const H0 = [
  { id: 'pages', n: 'Morning pages', sub: 'Three longhand pages before coffee', type: 'check', cad: 0, tod: 'Morning', c: COLORS[0][1], since: dn(2025, 5, 2), p: 0.86, tail: 23, today: 0, lapse: [dn(2026, 7, 10), dn(2026, 7, 16)] },
  { id: 'walk', n: 'Walk 8,000 steps', sub: 'Counted by the phone, any pace', type: 'count', goal: 8000, unit: 'steps', step: 1000, cad: 0, tod: 'Daytime', c: COLORS[1][1], since: dn(2025, 2, 10), p: 0.72, tail: 6, today: 5200 },
  { id: 'read', n: 'Read 20 pages', sub: 'Fiction counts. So do long essays.', type: 'count', goal: 20, unit: 'pages', step: 5, cad: 0, tod: 'Evening', c: COLORS[2][1], since: dn(2026, 0, 1), p: 0.68, tail: 4, today: 0 },
  { id: 'stretch', n: 'Stretch 10 minutes', sub: 'Hips, hamstrings, upper back', type: 'check', cad: 0, tod: 'Morning', c: COLORS[3][1], since: dn(2026, 1, 16), p: 0.62, tail: 2, today: 1 },
  { id: 'phone', n: 'Phone down by 22:30', sub: 'The charger lives in the hallway', type: 'check', cad: 0, tod: 'Evening', c: COLORS[4][1], since: dn(2026, 3, 6), p: 0.55, tail: 0, today: 0 },
  { id: 'gym', n: 'Strength training', sub: 'Three sessions a week', type: 'check', cad: 3, tod: 'Anytime', c: COLORS[5][1], since: dn(2025, 8, 1), wtail: 9, week: [0, 2] },
