  $('[data-chips]').innerHTML = ['All', ...TODS].map(t => '<button type="button" role="tab" aria-selected="' + (S.filter === t) + '" data-filter="' + t + '" data-k="f-' + t + '">' + t + '<span>' + counts[t] + '</span></button>').join('');
  const list = S.habits.filter(h => S.filter === 'All' || h.tod === S.filter);
  $('[data-list]').innerHTML = list.length ? list.map(h => {
    const wk = h.cad && weekCount(h, monOf(TODAY)) >= h.cad && !done(h, TODAY);
    const p = h.type === 'count' ? Math.min(1, amt(h, TODAY) / h.goal) : done(h, TODAY) ? 1 : h.cad ? weekCount(h, monOf(TODAY)) / h.cad : 0;
    const lbl = h.type === 'count' ? 'Log ' + h.unit + ' for today, ' + num(amt(h, TODAY)) + ' of ' + num(h.goal) : (done(h, TODAY) ? 'Undo today for ' : 'Mark today done for ') + h.n;
    return '<li class="aph-habits-item' + (h.id === S.newId ? ' is-new' : '') + '" style="--c:' + h.c + '">' +
      '<button type="button" class="aph-habits-pick" data-pick="' + h.id + '" data-k="p-' + h.id + '" aria-current="' + (h.id === S.sel) + '"><i></i><b>' + esc(h.n) + '</b><span>' + subline(h) + '</span></button>' +
      '<button type="button" class="aph-habits-check' + (wk ? ' is-week' : '') + '" data-today="' + h.id + '" data-k="t-' + h.id + '" aria-pressed="' + (h.type === 'count' ? amt(h, TODAY) >= h.goal : done(h, TODAY)) + '"' + (h.type === 'count' ? ' aria-haspopup="dialog"' : '') + ' aria-label="' + esc(lbl) + '" style="--p:' + p.toFixed(3) + '">' +
      (h.type === 'count' && amt(h, TODAY) < h.goal ? '<small>' + Math.round(p * 100) + '%</small>' : I.check) + '</button></li>';
  }).join('') : '<li style="padding:18px 12px;color:var(--aph-habits-mute)">No ' + S.filter.toLowerCase() + ' habits yet.</li>';
  S.newId = null;
  const A = $('[data-archived]');
  A.innerHTML = S.archived.length ? '<button type="button" data-act="show-arch" aria-expanded="' + S.showArch + '">' + S.archived.length + ' archived</button>' +
    (S.showArch ? '<ul>' + S.archived.map(h => '<li><span>' + esc(h.n) + '</span><button type="button" data-restore="' + h.id + '">Restore</button></li>').join('') + '</ul>' : '') : '';
}

function renderMain() {
  const h = cur();
  if (!h) { $('[data-head]').innerHTML = '<div class="aph-habits-headtx"><h2>No habits</h2><p>Create one to start a streak.</p></div>'; return; }
  root.style.setProperty('--aph-habits-hc', h.c);
  const cadTxt = h.cad ? h.cad + '× a week' : 'Every day', s = streak(h), L = longest(h), Y = yearStats(h, S.year);
  $('[data-head]').innerHTML = '<button type="button" class="aph-habits-back" data-act="back" aria-label="Back to today">' + I.prev + '</button><span class="aph-habits-swatch"></span>' +
    '<div class="aph-habits-headtx"><h2>' + esc(h.n) + '</h2><p>' + cadTxt + (h.type === 'count' ? ' · goal ' + num(h.goal) + ' ' + esc(h.unit) : '') + ' · ' + h.tod + ' · since ' + fmtD(h.since, true) + '</p></div>' +
    '<button type="button" class="aph-habits-more" data-act="menu" aria-haspopup="menu" aria-expanded="false" aria-label="Habit options">' + I.more + '</button>';
  const st = $('[data-stats]'), sameHabit = st.dataset.h === h.id;
  if (!sameHabit) {
    st.dataset.h = h.id;
    st.innerHTML = '<div class="is-hot"><small>Current streak</small><b><i class="aph-habits-count" data-n="cur"></i><sub data-unit></sub></b><span data-curtx></span></div>' +
      '<div><small>Longest</small><b><i class="aph-habits-count" data-n="long"></i><sub data-lunit></sub></b><span data-longtx></span></div>' +
      '<div><small data-ylbl></small><b><i class="aph-habits-count" data-n="rate"></i><sub>%</sub></b><span data-ratetx></span></div>' +
      '<div><small>Check-ins</small><b><i class="aph-habits-count" data-n="tot"></i></b><span>all time</span></div>';
    void st.offsetWidth; /* resolve the zero state first so the counters roll up */
  }
  const setN = (k, v) => { const el = $('[data-n="' + k + '"]', st); el.style.setProperty('--aph-habits-n', v); el.parentElement.setAttribute('aria-label', String(v)); };
  setN('cur', s.n); setN('long', L.n); setN('rate', Math.round(Y.rate * 100)); setN('tot', total(h));
  $('[data-unit]', st).textContent = s.unit + (s.n === 1 ? '' : 's');
  $('[data-lunit]', st).textContent = (h.cad ? 'week' : 'day') + (L.n === 1 ? '' : 's');
  $('[data-curtx]', st).textContent = s.n ? (s.open ? (h.cad ? 'week still open' : 'log today to keep it') : 'running since ' + fmtD(s.from)) : 'starts with the next check';
  $('[data-longtx]', st).textContent = L.n ? fmtD(L.a) + ' – ' + fmtD(L.b) : '—';
  $('[data-ylbl]', st).textContent = S.year + ' rate';
  $('[data-ratetx]', st).textContent = Y.label;
  $$('[data-mode]').forEach(b => { b.setAttribute('aria-selected', String(b.dataset.mode === S.mode)); b.tabIndex = b.dataset.mode === S.mode ? 0 : -1; });
  renderNav(h); renderCal(h); renderCards(h);
}

function renderNav(h) {
  const minY = ymd(h.since)[0];
  if (S.mode === 'year') {
    const pd = S.year <= minY, nd = S.year >= 2026;
    $('[data-nav]').innerHTML = '<button type="button" data-act="prev" data-k="nav-prev" aria-label="Previous year"' + (pd ? ' aria-disabled="true" title="No ' + esc(h.n) + ' data before ' + minY + '"' : '') + '>' + I.prev + '</button><output aria-live="polite">' + S.year + '</output>' +
      '<button type="button" data-act="next" data-k="nav-next" aria-label="Next year"' + (nd ? ' aria-disabled="true" title="' + (S.year + 1) + ' hasn’t started yet"' : '') + '>' + I.next + '</button><button type="button" class="aph-habits-totoday" data-act="today" data-k="nav-today">Today</button>';
  } else {
    const [sy, sm] = ymd(h.since), pd = dn(S.year, S.month, 1) <= dn(sy, sm, 1), nd = S.year === 2026 && S.month >= 9;
    $('[data-nav]').innerHTML = '<button type="button" data-act="prev" data-k="nav-prev" aria-label="Previous month"' + (pd ? ' aria-disabled="true" title="Nothing tracked before ' + MONF[ymd(h.since)[1]] + ' ' + ymd(h.since)[0] + '"' : '') + '>' + I.prev + '</button><output aria-live="polite">' + MON[S.month] + ' ' + S.year + '</output>' +
      '<button type="button" data-act="next" data-k="nav-next" aria-label="Next month"' + (nd ? ' aria-disabled="true" title="November hasn’t started yet"' : '') + '>' + I.next + '</button><button type="button" class="aph-habits-totoday" data-act="today" data-k="nav-today">Today</button>';
  }
}

function cellState(h, d) {
  if (d > TODAY) return { cls: 'is-future', dis: 'Hasn’t happened yet', tip: 'Not yet' };
  if (d < h.since) return { cls: 'is-off', dis: 'Before you started this habit on ' + fmtD(h.since, true), tip: 'Before you started' };
  const a = amt(h, d), ok = isDoneAmt(h, a);
  if (ok) return { cls: 'is-done', tip: h.type === 'count' ? num(a) + ' ' + h.unit : 'Done' };
  if (h.type === 'count' && a > 0) return { cls: 'is-part', f: Math.min(1, a / h.goal), tip: num(a) + ' of ' + num(h.goal) + ' ' + h.unit };
  return { cls: '', tip: d === TODAY ? 'Open' : 'Missed' };
}
function renderCal(h) {
  const box = $('[data-cal]'), s = streak(h), rip = S.ripple === h.id;
  const inCur = d => s.n > 0 && d >= s.from && d <= s.to && done(h, d);
  const cell = (d, extra) => {
    const c = cellState(h, d), y = ymd(d), cls = ['aph-habits-cell', c.cls];
    if (d === TODAY) cls.push('is-today');
    if (wd(d) > 4) cls.push('is-wknd');
    if (c.cls === 'is-done') {
      if (inCur(d)) cls.push('is-cur');
      if (S.mode === 'year') {
        if (y[2] > 1 && done(h, d - 1) && d - 1 >= h.since) cls.push('jl');
        if (y[2] < dim(y[0], y[1]) && done(h, d + 1) && d + 1 <= TODAY) cls.push('jr');
      }
      if (rip && inCur(d)) cls.push('is-ripple');
    }
    if (S.pop === d) cls.push('is-pop');
    const lbl = fmtD(d, true) + ', ' + c.tip;
    return '<button type="button" role="gridcell" class="' + cls.join(' ') + '" data-day="' + d + '" data-k="d' + d + '" tabindex="' + (d === S.focusDay ? 0 : -1) + '" aria-label="' + esc(lbl) + '" data-tip="' + esc(c.tip) + '"' +
      (c.dis ? ' aria-disabled="true" title="' + esc(c.dis) + '"' : ' aria-pressed="' + (c.cls === 'is-done') + '"') + ' style="' + (c.f != null ? '--f:' + c.f.toFixed(2) + ';' : '') + (rip ? '--i:' + Math.max(0, s.to - d) : '') + '">' + (extra || '') + '</button>';
  };
  if (S.mode === 'year') {
    const y = S.year;
    let html = '<div class="aph-habits-year" role="grid" aria-label="' + esc(h.n) + ', ' + y + '"><div class="aph-habits-yrow" role="row"><span></span>' + Array.from({ length: 31 }, (_, i) => '<span class="aph-habits-dlabel" role="columnheader">' + (i % 5 === 0 || i === 30 ? i + 1 : '') + '</span>').join('') + '</div>';
    for (let m = 0; m < 12; m++) {
      html += '<div class="aph-habits-yrow" role="row"><span class="aph-habits-mlabel" role="rowheader">' + MON[m] + '</span>';
      for (let d = 1; d <= 31; d++) html += d <= dim(y, m) ? cell(dn(y, m, d)) : '<span></span>';
      html += '</div>';
    }
    box.innerHTML = html + '</div>';
  } else {
    const y = S.year, m = S.month, first = dn(y, m, 1), lead = wd(first);
    let html = '<div class="aph-habits-month" role="grid" aria-label="' + esc(h.n) + ', ' + MONF[m] + ' ' + y + '">' + WDS.map(w => '<span class="aph-habits-wd" role="columnheader">' + w.slice(0, 2) + '</span>').join('');
    for (let i = 0; i < lead; i++) html += '<span></span>';
    for (let d = 1; d <= dim(y, m); d++) { const n = dn(y, m, d), a = amt(h, n); html += cell(n, '<b>' + d + '</b><small>' + (h.type === 'count' && a && n <= TODAY && n >= h.since ? (h.unit === 'steps' ? (a / 1000).toFixed(1) + 'k' : a) : '') + '</small>'); }
    box.innerHTML = html + '</div>';
  }
  S.ripple = null; S.pop = null;
  $('[data-legend]').innerHTML = '<span><i style="background:var(--aph-habits-hc)"></i>Done</span><span><i style="background:var(--aph-habits-deep)"></i>Current streak</span>' +
    (h.type === 'count' ? '<span><i style="background:var(--aph-habits-soft)"></i>Partly</span>' : '') + '<span><i style="background:var(--aph-habits-empty)"></i>Missed</span><span><i style="background:repeating-linear-gradient(135deg,transparent 0 3px,var(--aph-habits-line2) 3px 4px)"></i>Not tracked</span>' +
    '<span class="aph-habits-hint"><kbd>←</kbd><kbd>→</kbd><kbd>↑</kbd><kbd>↓</kbd> move · <kbd>↵</kbd> ' + (h.type === 'count' ? 'edit' : 'toggle') + '</span>';
}

function renderCards(h) {
  const y = S.year, rates = MON.map((_, m) => monthRate(h, y, m)), nowM = y === 2026 ? 9 : -1;
  const best = rates.reduce((b, r, m) => (r && (!b || r.v > b.v) ? { v: r.v, m } : b), null);
  const wdDone = [0, 0, 0, 0, 0, 0, 0], wdAll = [0, 0, 0, 0, 0, 0, 0];
  for (let d = Math.max(h.since, dn(y, 0, 1)); d <= Math.min(TODAY, dn(y, 11, 31)); d++) { wdAll[wd(d)]++; if (done(h, d)) wdDone[wd(d)]++; }
  const wsum = wdDone.reduce((a, b) => a + b, 0) || 1;
  const wv = wdDone.map((v, i) => (h.cad ? v / Math.max(...wdDone, 1) : wdAll[i] ? v / wdAll[i] : 0));
  const tot = total(h);
  let hundred = null; if (tot >= 100) { let n = 0; for (let d = h.since; d <= TODAY; d++) if (done(h, d) && ++n === 100) { hundred = d; break; } }
  const L = longest(h);
  const html =
    '<section><h3>' + (h.cad ? 'Target met by month' : 'Days done by month') + '<span>' + y + '</span></h3><div class="aph-habits-bars" role="img" aria-label="' + esc(MON.map((n, m) => rates[m] ? n + ' ' + Math.round(rates[m].v * 100) + '%' : '').filter(Boolean).join(', ')) + '">' +
      MON.map((n, m) => { const r = rates[m]; return '<div class="aph-habits-b' + (r ? '' : ' is-empty') + (m === nowM ? ' is-now' : '') + '" style="--v:' + (r ? Math.max(0.03, r.v).toFixed(3) : 0) + ';--i:' + m + '"><em>' + (r ? Math.round(r.v * 100) + '% · ' + r.lbl : '') + '</em><i></i><span>' + n[0] + '</span></div>'; }).join('') + '</div></section>' +
    '<section><h3>By weekday<span>' + (h.cad ? 'sessions' : '% of days') + '</span></h3><div class="aph-habits-bars" role="img" aria-label="' + esc(WDS.map((w, i) => w + ' ' + (h.cad ? wdDone[i] : Math.round(wv[i] * 100) + '%')).join(', ')) + '">' +
      WDS.map((w, i) => '<div class="aph-habits-b" style="--v:' + Math.max(0.03, wv[i]).toFixed(3) + ';--i:' + i + '"><em>' + (h.cad ? wdDone[i] + ' · ' + Math.round(wdDone[i] / wsum * 100) + '%' : Math.round(wv[i] * 100) + '%') + '</em><i></i><span>' + w[0] + '</span></div>').join('') + '</div></section>' +
    '<section><h3>Milestones</h3><ul class="aph-habits-miles">' +
      '<li><div><b>Started ' + fmtD(h.since, true) + '</b><span>' + num(tot) + ' check-ins since</span></div></li>' +
      '<li><div><b>' + (hundred ? '100th check-in ' + fmtD(hundred) : (100 - tot) + ' to your 100th') + '</b><span>' + (hundred ? 'a three-digit habit' : 'at the current pace, about ' + Math.ceil((100 - tot) / Math.max(0.1, yearStats(h, 2026).rate * (h.cad ? h.cad / 7 : 1))) + ' days') + '</span></div></li>' +
      '<li><div><b>Longest run: ' + L.n + ' ' + (h.cad ? 'week' : 'day') + (L.n === 1 ? '' : 's') + '</b><span>' + (L.n ? fmtD(L.a, true) + ' – ' + fmtD(L.b, true) : 'nothing yet') + '</span></div></li>' +
      (best ? '<li><div><b>Best month: ' + MONF[best.m] + '</b><span>' + Math.round(best.v * 100) + '% · ' + rates[best.m].lbl + '</span></div></li>' : '') +
    '</ul></section>';
  const box = $('[data-cards]'), key = h.id + ':' + y + ':' + h.cad;
  if (box.dataset.key !== key) { box.dataset.key = key; box.innerHTML = html; return; }
  const tmp = doc.createElement('div'); tmp.innerHTML = html;
  const nb = $$('.aph-habits-b', tmp), ob = $$('.aph-habits-b', box);
  ob.forEach((el, i) => { if (!nb[i]) return; el.className = nb[i].className; el.style.cssText = nb[i].style.cssText; el.querySelector('em').textContent = nb[i].querySelector('em').textContent; });
  $$('.aph-habits-bars', box).forEach((el, i) => el.setAttribute('aria-label', $$('.aph-habits-bars', tmp)[i].getAttribute('aria-label')));
  $('.aph-habits-miles', box).innerHTML = $('.aph-habits-miles', tmp).innerHTML;
}

/* ── amount editor (count habits) and habit menu share one floating layer ── */
let pop = null;
function placeLayer(el, anchor, alignRight) {
  const rb = root.getBoundingClientRect(), ab = anchor.getBoundingClientRect();
  el.hidden = false;
  let x = alignRight ? ab.right - rb.left - el.offsetWidth : ab.left - rb.left + ab.width / 2 - el.offsetWidth / 2;
  x = clamp(x, 8, rb.width - el.offsetWidth - 8);
  let y = ab.bottom - rb.top + 6;
  if (y + el.offsetHeight > rb.height - 8) y = ab.top - rb.top - el.offsetHeight - 6;
  el.style.left = x + 'px'; el.style.top = Math.max(8, y) + 'px';
}
function openAmount(h, d, anchor) {
  pop = { id: h.id, d, anchor: anchor.dataset.k, touched: false };
  drawAmount(anchor);
}
function drawAmount(anchor) {
  const h = hab(pop.id), a = amt(h, pop.d), M = $('[data-menu]');
  M.setAttribute('role', 'dialog'); M.setAttribute('aria-label', h.n + ', ' + fmtD(pop.d));
  M.innerHTML = '<div style="padding:8px 10px 4px"><small style="font-size:11px;color:var(--aph-habits-mute);font-weight:650">' + esc(h.n) + ' · ' + fmtD(pop.d) + '</small>' +
    '<div style="display:flex;align-items:center;gap:8px;margin:8px 0 6px"><button type="button" data-amt="-1" aria-label="Less"' + (a <= 0 ? ' aria-disabled="true" title="Already zero"' : '') + ' style="width:34px;height:34px;justify-content:center;border:1px solid var(--aph-habits-line2)">' + I.minus + '</button>' +
    '<output style="flex:1;text-align:center;font:600 24px/1 var(--aph-habits-serif);font-variant-numeric:tabular-nums">' + num(a) + '<small style="font:600 11px system-ui;color:var(--aph-habits-mute);margin-left:4px">' + esc(h.unit) + '</small></output>' +
    '<button type="button" data-amt="1" aria-label="More" style="width:34px;height:34px;justify-content:center;border:1px solid var(--aph-habits-line2)">' + I.plus + '</button></div>' +
    '<div style="height:5px;border-radius:3px;background:var(--aph-habits-line);overflow:hidden"><i style="display:block;height:100%;width:' + Math.min(100, a / h.goal * 100) + '%;background:' + h.c + ';transition:width .3s"></i></div></div><hr>' +
    '<button type="button" data-amt="goal"' + (a >= h.goal ? ' aria-disabled="true" title="Goal already met"' : '') + '>' + I.check + 'Log the goal · ' + num(h.goal) + '</button>' +
    '<button type="button" data-amt="clear"' + (a <= 0 ? ' aria-disabled="true" title="Nothing logged"' : '') + '>' + I.minus + 'Clear the day</button>';
  placeLayer(M, anchor || root.querySelector('[data-k="' + pop.anchor + '"]') || root, false);
}
function amountStep(kind) {
  const h = hab(pop.id); if (!h) return;
  if (!pop.touched) { remember(); pop.touched = true; }
  const before = done(h, pop.d), a = amt(h, pop.d);
  h.rec[pop.d] = kind === 'goal' ? h.goal : kind === 'clear' ? 0 : Math.max(0, a + (+kind) * h.step);
  if (!before && done(h, pop.d)) { S.ripple = h.id; S.pop = pop.d; }
  const k = pop.anchor; render();
  const anchor = root.querySelector('[data-k="' + k + '"]');
  drawAmount(anchor);
  if (!before && done(h, pop.d)) toast(h.n + ' · goal met for ' + fmtD(pop.d), true);
}
function closePop(refocus) {
  const M = $('[data-menu]'); if (M.hidden) return;
  M.hidden = true; M.setAttribute('role', 'menu');
  const k = pop ? pop.anchor : 'menu'; pop = null;
  const b = root.querySelector('[data-act="menu"]'); if (b) b.setAttribute('aria-expanded', 'false');
  if (refocus) { const el = k === 'menu' ? b : root.querySelector('[data-k="' + k + '"]'); if (el) el.focus(); }
}
function openMenu(btn) {
  pop = null;
  const M = $('[data-menu]'); M.setAttribute('role', 'menu'); M.removeAttribute('aria-label');
  M.innerHTML = '<button type="button" role="menuitem" data-act="edit">' + I.edit + 'Edit habit…</button><button type="button" role="menuitem" data-act="today-toggle">' + I.check + (cur().type === 'count' ? 'Log today…' : done(cur(), TODAY) ? 'Undo today' : 'Mark today done') + '<kbd style="margin-left:auto">T</kbd></button><hr><button type="button" role="menuitem" class="is-danger" data-act="archive">' + I.archive + 'Archive habit</button>';
  placeLayer(M, btn, true); btn.setAttribute('aria-expanded', 'true'); M.querySelector('button').focus();
}

/* ── actions ── */
function toggleDay(h, d) {
  if (d > TODAY || d < h.since) return;
  remember();
  const was = done(h, d);
  h.rec[d] = was ? 0 : 1;
  if (!was) { S.ripple = h.id; S.pop = d; }
  render();
  const s = streak(h);
  toast(was ? h.n + ' · ' + fmtD(d) + ' cleared' : h.n + ' · ' + fmtD(d) + ' done' + (s.n > 1 && d >= s.from ? ' · ' + s.n + '-' + s.unit + ' streak' : ''), true);
}
function todayAction(h, anchor) {
  if (h.type === 'count') { openAmount(h, TODAY, anchor); return; }
  toggleDay(h, TODAY);
}
function visibleAnchor() {
  return [root.querySelector('[data-k="t-' + S.sel + '"]'), root.querySelector('[data-k="d' + TODAY + '"]'), $('[data-act="menu"]')].find(x => x && x.getClientRects().length) || root;
}
function select(id, toDetail) {
  S.sel = id; closePop();
  const h = cur(); if (S.year < ymd(h.since)[0]) S.year = ymd(h.since)[0];
  render();
  if (toDetail && root.clientWidth < 760) { root.dataset.view = 'detail'; $('[data-main]').scrollTop = 0; const b = $('[data-act="back"]'); if (b) b.focus(); }
}
function moveSel(d) {
  const list = S.habits.filter(h => S.filter === 'All' || h.tod === S.filter);
  if (!list.length) return;
  const i = Math.max(0, list.findIndex(h => h.id === S.sel)), j = clamp(i + d, 0, list.length - 1);
  if (j !== i) select(list[j].id);
}
function archive() {
  const h = cur(); if (!h) return;
  remember();
  S.habits = S.habits.filter(x => x.id !== h.id); S.archived.push(h);
  S.sel = S.habits[0] ? S.habits[0].id : null;
  closePop(); render(); toast(h.n + ' archived — its history is kept', true);
}
function restore(id) {
  const h = S.archived.find(x => x.id === id); if (!h) return;
  remember();
  S.archived = S.archived.filter(x => x.id !== id); S.habits.push(h); S.sel = id; S.newId = id;
  render(); toast(h.n + ' restored', true);
}

/* ── new / edit drawer ── */
