/* Larder: a week of meals on the left, the shopping list it implies on the right. */
@property --aph-meals-fill { syntax: "<number>"; inherits: false; initial-value: 0; }

.aph-meals {
  /* re-theme: paper, ink, accent (tomato), herb */
  --aph-meals-paper: oklch(0.975 0.014 95);
  --aph-meals-ink: oklch(0.28 0.035 135);
  --aph-meals-accent: oklch(0.63 0.19 33);
  --aph-meals-herb: oklch(0.56 0.11 142);
  --aph-meals-card: color-mix(in oklab, var(--aph-meals-paper) 40%, white);
  --aph-meals-sunk: color-mix(in oklab, var(--aph-meals-paper) 92%, var(--aph-meals-ink));
  --aph-meals-line: color-mix(in oklab, var(--aph-meals-ink) 11%, transparent);
  --aph-meals-line2: color-mix(in oklab, var(--aph-meals-ink) 20%, transparent);
  --aph-meals-mute: color-mix(in oklab, var(--aph-meals-ink) 62%, var(--aph-meals-paper));
  --aph-meals-faint: color-mix(in oklab, var(--aph-meals-ink) 40%, var(--aph-meals-paper));
  --aph-meals-tint: color-mix(in oklab, var(--aph-meals-accent) 10%, var(--aph-meals-paper));
  --aph-meals-herbtint: color-mix(in oklab, var(--aph-meals-herb) 12%, var(--aph-meals-paper));
  --aph-meals-round: ui-rounded, "SF Pro Rounded", system-ui, -apple-system, "Segoe UI", sans-serif;
  --aph-meals-ease: cubic-bezier(.2, .8, .2, 1);
  --aph-meals-spring: linear(0, 0.1 4%, 0.38 10%, 0.75 17%, 0.98 24%, 1.06 30%, 1.06 36%, 1.02 46%, 0.995 60%, 1);

  position: relative; width: 100%; height: var(--aph-meals-h, 680px);
  container-type: inline-size; container-name: aph-meals; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--aph-meals-paper); color: var(--aph-meals-ink); color-scheme: light; accent-color: var(--aph-meals-herb);
  border-radius: 14px; font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--aph-meals-accent); outline-offset: 2px; border-radius: 6px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button[aria-disabled="true"] { cursor: not-allowed; opacity: .4; }
  & h2, & h3, & h4, & p, & ul, & ol { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & h2, & h3 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; display: inline-block; text-align: center; border: 1px solid var(--aph-meals-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--aph-meals-mute); background: var(--aph-meals-card); }
  & [hidden] { display: none !important; }
}
.aph-meals .aph-meals-app {
  height: 100%; display: grid; grid-template-columns: 252px minmax(0, 1fr) 300px; grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "lib board list" "tabs tabs tabs";
}

/* ── recipe library ── */
.aph-meals .aph-meals-lib {
  grid-area: lib; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto auto minmax(0, 1fr) auto; min-height: 0; min-width: 0;
  background: var(--aph-meals-sunk); border-right: 1px solid var(--aph-meals-line);
}
.aph-meals .aph-meals-brand {
  display: flex; align-items: center; gap: 8px; padding: 16px 16px 12px;
  & svg { width: 22px; height: 22px; color: var(--aph-meals-accent); stroke-width: 2; }
  & b { font: 750 16px/1 var(--aph-meals-round); letter-spacing: -.01em; }
  & span { margin-left: auto; font-size: 11.5px; color: var(--aph-meals-mute); }
}
.aph-meals .aph-meals-search {
  display: flex; align-items: center; gap: 8px; margin: 0 12px 10px; height: 36px; padding: 0 8px 0 10px; border-radius: 10px; background: var(--aph-meals-card); border: 1px solid var(--aph-meals-line2);
  & svg { width: 16px; height: 16px; color: var(--aph-meals-faint); }
  & input { flex: 1; width: 100%; min-width: 0; border: 0; background: none; outline: none; font-size: 13px; }
  &:focus-within { outline: 2px solid var(--aph-meals-accent); outline-offset: 1px; }
}
.aph-meals .aph-meals-tags {
  display: flex; flex-wrap: wrap; gap: 4px; padding: 0 12px 10px;
  & button { height: 26px; padding: 0 10px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--aph-meals-mute); border: 1px solid var(--aph-meals-line2); transition: background .15s, color .15s; }
  & button[aria-selected="true"] { background: var(--aph-meals-ink); border-color: var(--aph-meals-ink); color: var(--aph-meals-paper); }
}
.aph-meals .aph-meals-recipes {
  overflow: auto; overscroll-behavior: contain; padding: 2px 10px 10px; display: grid; align-content: start; gap: 4px;
  scrollbar-width: thin; scrollbar-color: var(--aph-meals-line2) transparent;
}
.aph-meals .aph-meals-recipe {
  display: grid; grid-template-columns: 44px minmax(0, 1fr); gap: 2px 10px; align-items: center; text-align: left; padding: 8px; border-radius: 12px;
  cursor: grab; touch-action: none; user-select: none; transition: background .15s, box-shadow .2s, transform .2s var(--aph-meals-ease);
  & b { font-weight: 650; line-height: 1.25; }
  & span { font-size: 11.5px; color: var(--aph-meals-mute); font-variant-numeric: tabular-nums; }
  & .aph-meals-plate { grid-row: span 2; }
  &:hover { background: var(--aph-meals-card); }
  &[aria-pressed="true"] { background: var(--aph-meals-card); box-shadow: 0 0 0 2px var(--aph-meals-accent); }
  &.is-dragging { opacity: .35; }
  &.is-in-week b::after { content: ""; display: inline-block; width: 6px; height: 6px; margin-left: 6px; border-radius: 50%; background: var(--aph-meals-herb); vertical-align: middle; }
}
/* a plate drawn from the recipe's three colours */
.aph-meals .aph-meals-plate {
  width: 44px; height: 44px; border-radius: 50%; flex: none;
  background:
    radial-gradient(circle at 34% 38%, var(--c1) 0 22%, transparent 23%),
    radial-gradient(circle at 64% 42%, var(--c2) 0 19%, transparent 20%),
    radial-gradient(circle at 48% 68%, var(--c3) 0 17%, transparent 18%),
    radial-gradient(circle, var(--aph-meals-card) 0 66%, color-mix(in oklab, var(--aph-meals-ink) 8%, var(--aph-meals-card)) 67% 70%, var(--aph-meals-card) 71%);
  box-shadow: 0 1px 2px color-mix(in oklab, var(--aph-meals-ink) 20%, transparent), inset 0 0 0 1px var(--aph-meals-line);
}
.aph-meals .aph-meals-tip { padding: 10px 16px 14px; font-size: 11.5px; color: var(--aph-meals-faint); border-top: 1px solid var(--aph-meals-line); }

/* ── week board ── */
.aph-meals .aph-meals-board {
  grid-area: board; display: grid; grid-template-rows: auto auto minmax(0, 1fr); min-height: 0; min-width: 0;
  container-type: inline-size; container-name: aph-meals-board;
}
.aph-meals .aph-meals-bhead {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 14px 18px 10px; flex-wrap: wrap;
}
.aph-meals .aph-meals-week {
  display: flex; align-items: center; gap: 8px;
  & > button { width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; border: 1px solid var(--aph-meals-line2); transition: background .15s; }
  & > button:hover { background: var(--aph-meals-card); }
  & h2 { font: 750 clamp(17px, 3.2cqi, 21px)/1.1 var(--aph-meals-round); letter-spacing: -.02em; white-space: nowrap; }
  & p { font-size: 11.5px; color: var(--aph-meals-mute); font-variant-numeric: tabular-nums; }
}
.aph-meals .aph-meals-bacts { display: flex; gap: 6px; }
.aph-meals .aph-meals-ghost {
  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 11px; border-radius: 9px; border: 1px solid var(--aph-meals-line2); font-size: 12.5px; font-weight: 600;
  transition: background .15s, transform .15s var(--aph-meals-ease);
  & svg { width: 15px; height: 15px; }
  &:hover { background: var(--aph-meals-card); }
  &:active { transform: scale(.97); }
}
.aph-meals .aph-meals-placing {
  margin: 0 18px 8px; padding: 8px 8px 8px 12px; border-radius: 10px; display: flex; align-items: center; gap: 10px;
  background: var(--aph-meals-accent); color: white; font-weight: 600; font-size: 12.5px;
  transition: opacity .2s, transform .3s var(--aph-meals-spring);
  @starting-style { opacity: 0; transform: translateY(-6px); }
  & span { flex: 1; min-width: 0; }
  & kbd { background: transparent; color: white; border-color: oklch(1 0 0 / .45); }
  & button { height: 26px; padding: 0 10px; border-radius: 7px; background: oklch(1 0 0 / .2); font-weight: 700; }
}
.aph-meals .aph-meals-grid {
  overflow: auto; overscroll-behavior: contain; padding: 0 18px 18px; display: grid; grid-template-columns: 56px repeat(3, minmax(0, 1fr)); gap: 6px; align-content: start;
  scrollbar-width: thin; scrollbar-color: var(--aph-meals-line2) transparent;
}
.aph-meals .aph-meals-row {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: stretch;
  &.is-head { position: sticky; top: 0; z-index: 2; background: var(--aph-meals-paper); padding: 2px 0 4px; }
  &.is-head span { font-size: 10.5px; text-transform: uppercase; letter-spacing: .12em; font-weight: 700; color: var(--aph-meals-faint); padding-left: 4px; }
  &.is-today .aph-meals-day b { color: var(--aph-meals-accent); }
}
.aph-meals .aph-meals-day {
  display: grid; align-content: center; justify-items: start; padding-left: 2px;
  & b { font: 750 14px/1 var(--aph-meals-round); }
  & span { font: 600 11px/1.3 ui-monospace, Menlo, monospace; color: var(--aph-meals-faint); font-variant-numeric: tabular-nums; }
}
.aph-meals .aph-meals-slot {
  position: relative; min-height: 60px; border-radius: 11px; text-align: left; display: grid; align-content: center;
  border: 1.5px dashed var(--aph-meals-line2); color: var(--aph-meals-faint); font-size: 12px; padding: 8px 10px;
  transition: background .15s, border-color .15s, transform .25s var(--aph-meals-spring), box-shadow .2s;
  & .aph-meals-add { display: inline-flex; align-items: center; gap: 4px; opacity: 0; transition: opacity .15s; }
  & .aph-meals-add svg { width: 14px; height: 14px; }
  &:hover .aph-meals-add, &:focus-visible .aph-meals-add { opacity: 1; }
  &.is-over { border-color: var(--aph-meals-accent); background: var(--aph-meals-tint); transform: scale(1.03); }
  &.is-filled {
    border: 0; background: var(--aph-meals-card); color: var(--aph-meals-ink); padding-left: 14px; cursor: grab; touch-action: none; user-select: none;
    box-shadow: 0 1px 0 var(--aph-meals-line), 0 0 0 1px var(--aph-meals-line);
  }
  &.is-filled::before { content: ""; position: absolute; left: 5px; top: 8px; bottom: 8px; width: 3px; border-radius: 2px; background: var(--c1); }
  &.is-filled b { font-weight: 640; font-size: 12.5px; line-height: 1.25; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
  &.is-filled span { font-size: 11px; color: var(--aph-meals-mute); font-variant-numeric: tabular-nums; margin-top: 2px; }
  &.is-filled:hover { box-shadow: 0 1px 0 var(--aph-meals-line), 0 0 0 1px var(--aph-meals-line2), 0 6px 16px -10px color-mix(in oklab, var(--aph-meals-ink) 40%, transparent); }
  &.is-left { background: repeating-linear-gradient(135deg, var(--aph-meals-card) 0 6px, var(--aph-meals-herbtint) 6px 12px); }
  &.is-left b::before { content: "Leftover · "; color: var(--aph-meals-herb); font-weight: 700; }
  &.is-new { animation: aph-meals-drop .5s var(--aph-meals-spring); }
  &.is-dragging { opacity: .35; }
  &.is-past { opacity: .55; }
}
.aph-meals[data-placing] .aph-meals-slot:not(.is-filled) { border-color: color-mix(in oklab, var(--aph-meals-accent) 55%, transparent); color: var(--aph-meals-accent); }
.aph-meals[data-placing] .aph-meals-slot .aph-meals-add { opacity: 1; }

/* ── shopping list ── */
.aph-meals .aph-meals-list {
  grid-area: list; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0; background: var(--aph-meals-card); border-left: 1px solid var(--aph-meals-line);
}
.aph-meals .aph-meals-lhead {
  padding: 16px 16px 12px; border-bottom: 1px solid var(--aph-meals-line); display: grid; gap: 10px;
  & .aph-meals-ltop { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
  & h3 { font: 750 17px/1.1 var(--aph-meals-round); letter-spacing: -.01em; }
  & .aph-meals-total { font: 700 20px/1 ui-monospace, Menlo, monospace; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & p { font-size: 11.5px; color: var(--aph-meals-mute); font-variant-numeric: tabular-nums; }
  & .aph-meals-meter { height: 6px; border-radius: 3px; background: var(--aph-meals-line); overflow: hidden; }
  & .aph-meals-meter i { display: block; height: 100%; width: 100%; background: var(--aph-meals-herb); transform-origin: left; transform: scaleX(var(--aph-meals-fill)); transition: --aph-meals-fill .6s var(--aph-meals-spring); }
  & .aph-meals-seg { display: inline-flex; padding: 2px; border-radius: 9px; background: var(--aph-meals-sunk); justify-self: start; }
  & .aph-meals-seg button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--aph-meals-mute); }
  & .aph-meals-seg button[aria-selected="true"] { background: var(--aph-meals-card); color: var(--aph-meals-ink); box-shadow: 0 1px 2px color-mix(in oklab, var(--aph-meals-ink) 15%, transparent); }
}
.aph-meals .aph-meals-lbody {
  overflow: auto; overscroll-behavior: contain; padding: 4px 8px 14px; scrollbar-width: thin; scrollbar-color: var(--aph-meals-line2) transparent;
  & h4 { position: sticky; top: 0; z-index: 1; display: flex; justify-content: space-between; padding: 10px 8px 6px; font-size: 10.5px; text-transform: uppercase; letter-spacing: .12em; font-weight: 700; color: var(--aph-meals-faint); background: var(--aph-meals-card); }
  & .aph-meals-empty { padding: 30px 14px; text-align: center; color: var(--aph-meals-mute); }
}
.aph-meals .aph-meals-line {
  display: grid; grid-template-columns: 26px minmax(0, 1fr) auto 28px; gap: 2px 8px; align-items: center; padding: 6px 4px 6px 8px; border-radius: 9px;
  transition: background .15s, opacity .2s;
  &.is-enter { animation: aph-meals-enter .45s var(--aph-meals-ease) both; animation-delay: calc(var(--i, 0) * 40ms); }
  &:hover { background: var(--aph-meals-paper); }
  & .aph-meals-tx { min-width: 0; }
  & .aph-meals-tx b { font-weight: 600; display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .aph-meals-tx span { font-size: 11px; color: var(--aph-meals-faint); display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .aph-meals-q { text-align: right; font: 650 12px/1.2 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & .aph-meals-q small { display: block; font-weight: 500; color: var(--aph-meals-faint); font-size: 10.5px; }
  &.is-got .aph-meals-tx b { text-decoration: line-through; text-decoration-color: var(--aph-meals-faint); color: var(--aph-meals-faint); }
  &.is-got .aph-meals-q { color: var(--aph-meals-faint); }
  &.is-bump .aph-meals-q { animation: aph-meals-bump .7s var(--aph-meals-ease); }
}
.aph-meals .aph-meals-box {
  width: 22px; height: 22px; border-radius: 7px; border: 1.75px solid var(--aph-meals-line2); display: grid; place-items: center; color: transparent;
  transition: background .2s, border-color .2s, transform .2s var(--aph-meals-spring);
  & svg { width: 14px; height: 14px; stroke-width: 2.8; }
  &[aria-checked="true"] { background: var(--aph-meals-herb); border-color: var(--aph-meals-herb); color: white; }
  &:active { transform: scale(.85); }
}
.aph-meals .aph-meals-have {
  width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; color: var(--aph-meals-faint); opacity: .55; transition: opacity .15s, background .15s, color .15s;
  & svg { width: 15px; height: 15px; }
  &:hover, &:focus-visible { opacity: 1; background: var(--aph-meals-sunk); }
  &[aria-pressed="true"] { opacity: 1; color: var(--aph-meals-herb); }
}
.aph-meals .aph-meals-lfoot { display: flex; justify-content: space-between; gap: 8px; padding: 10px 12px 12px; border-top: 1px solid var(--aph-meals-line); }
.aph-meals .aph-meals-primary {
  display: inline-flex; align-items: center; gap: 7px; height: 34px; padding: 0 14px 0 11px; border-radius: 10px; background: var(--aph-meals-ink); color: var(--aph-meals-paper); font-weight: 650;
  transition: transform .15s var(--aph-meals-ease);
  & svg { width: 16px; height: 16px; }
  &:active { transform: scale(.96); }
}

/* ── tabs (narrow) ── */
.aph-meals .aph-meals-tabs {
  grid-area: tabs; display: none; gap: 4px; padding: 6px 8px; border-top: 1px solid var(--aph-meals-line); background: var(--aph-meals-sunk);
  & button { flex: 1; display: grid; justify-items: center; gap: 2px; padding: 5px 0 3px; border-radius: 9px; font-size: 10.5px; font-weight: 650; color: var(--aph-meals-faint); position: relative; }
  & button[aria-current="page"] { color: var(--aph-meals-accent); background: var(--aph-meals-card); }
  & button b { position: absolute; top: 2px; left: calc(50% + 8px); min-width: 16px; height: 16px; padding: 0 4px; border-radius: 99px; background: var(--aph-meals-accent); color: white; font-size: 9.5px; line-height: 16px; }
  & button b:empty { display: none; }
}

/* ── floating layers ── */
.aph-meals .aph-meals-pop {
  position: absolute; z-index: 30; width: 264px; padding: 12px; border-radius: 14px; background: var(--aph-meals-card); border: 1px solid var(--aph-meals-line2);
  box-shadow: 0 22px 50px -16px color-mix(in oklab, var(--aph-meals-ink) 50%, transparent);
  transition: opacity .15s, transform .25s var(--aph-meals-spring); transform-origin: top center;
  @starting-style { opacity: 0; transform: scale(.95) translateY(-4px); }
  & h4 { font: 700 14px/1.2 var(--aph-meals-round); }
  & p { font-size: 11.5px; color: var(--aph-meals-mute); margin-top: 2px; }
  & .aph-meals-srv { display: flex; align-items: center; justify-content: space-between; margin: 12px 0 10px; padding: 6px; border-radius: 10px; background: var(--aph-meals-sunk); }
  & .aph-meals-srv button { width: 30px; height: 30px; border-radius: 8px; background: var(--aph-meals-card); display: grid; place-items: center; }
  & .aph-meals-srv output { font: 700 15px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
  & .aph-meals-srv output small { font: 500 11px system-ui; color: var(--aph-meals-mute); margin-left: 4px; }
  & .aph-meals-popacts { display: grid; gap: 2px; }
  & .aph-meals-popacts button { display: flex; align-items: center; gap: 8px; padding: 8px; border-radius: 8px; text-align: left; font-size: 12.5px; }
  & .aph-meals-popacts button:hover, & .aph-meals-popacts button:focus-visible { background: var(--aph-meals-sunk); outline: none; }
  & .aph-meals-popacts svg { width: 15px; height: 15px; color: var(--aph-meals-mute); }
  & .aph-meals-popacts .is-danger { color: oklch(0.52 0.17 28); }
  & .aph-meals-popacts .is-danger svg { color: currentColor; }
  & .aph-meals-quick { display: grid; gap: 2px; max-height: 260px; overflow: auto; margin-top: 8px; }
  & .aph-meals-quick button { display: grid; grid-template-columns: 26px minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 5px 6px; border-radius: 8px; text-align: left; font-size: 12.5px; }
  & .aph-meals-quick button:hover, & .aph-meals-quick button:focus-visible { background: var(--aph-meals-sunk); outline: none; }
  & .aph-meals-quick .aph-meals-plate { width: 26px; height: 26px; }
  & .aph-meals-quick span { font-size: 11px; color: var(--aph-meals-faint); font-variant-numeric: tabular-nums; }
}
.aph-meals .aph-meals-ghostcard {
  position: absolute; z-index: 60; left: 0; top: 0; pointer-events: none; display: flex; align-items: center; gap: 10px; padding: 8px 12px 8px 8px; border-radius: 12px;
  background: var(--aph-meals-card); box-shadow: 0 18px 40px -12px color-mix(in oklab, var(--aph-meals-ink) 55%, transparent), 0 0 0 1.5px var(--aph-meals-accent);
  font-weight: 650; rotate: -2deg; white-space: nowrap;
}
.aph-meals .aph-meals-scrim { position: absolute; inset: 0; z-index: 40; background: color-mix(in oklab, var(--aph-meals-ink) 30%, transparent); transition: opacity .25s; @starting-style { opacity: 0; } }
.aph-meals .aph-meals-sheet {
  position: absolute; z-index: 41; left: 50%; top: 50%; translate: -50% -50%; width: min(440px, calc(100% - 28px)); max-height: calc(100% - 40px); overflow: auto;
  padding: 20px; border-radius: 18px; background: var(--aph-meals-card); box-shadow: 0 30px 70px -20px color-mix(in oklab, var(--aph-meals-ink) 60%, transparent);
  display: grid; gap: 12px; transition: opacity .2s, transform .35s var(--aph-meals-spring);
  @starting-style { opacity: 0; transform: translateY(14px) scale(.97); }
  & h3 { font: 750 19px/1.1 var(--aph-meals-round); }
  & p { font-size: 12px; color: var(--aph-meals-mute); }
  & textarea { width: 100%; height: 240px; resize: none; padding: 12px; border-radius: 12px; border: 1px solid var(--aph-meals-line2); background: var(--aph-meals-paper); font: 12px/1.55 ui-monospace, Menlo, monospace; }
  & .aph-meals-shacts { display: flex; justify-content: flex-end; gap: 8px; }
}
.aph-meals .aph-meals-toast {
  position: absolute; z-index: 50; left: 50%; bottom: 16px; translate: -50% 0; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 24px);
  padding: 9px 9px 9px 14px; border-radius: 12px; background: var(--aph-meals-ink); color: var(--aph-meals-paper); font-size: 12.5px; font-weight: 550;
  box-shadow: 0 14px 34px -10px color-mix(in oklab, var(--aph-meals-ink) 70%, transparent); transition: opacity .25s, translate .45s var(--aph-meals-spring);
  &:empty { display: none; }
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & button { height: 28px; padding: 0 10px; border-radius: 8px; background: color-mix(in oklab, var(--aph-meals-paper) 16%, transparent); font-weight: 700; white-space: nowrap; }
  & button kbd { background: transparent; color: inherit; opacity: .7; border-color: color-mix(in oklab, var(--aph-meals-paper) 30%, transparent); }
  @starting-style { opacity: 0; translate: -50% 14px; }
}
@keyframes aph-meals-drop { 0% { transform: scale(.85); opacity: 0; } 100% { transform: none; opacity: 1; } }
@keyframes aph-meals-enter { from { opacity: 0; transform: translateX(14px); background: var(--aph-meals-herbtint); } }
@keyframes aph-meals-bump { 0%, 100% { color: inherit; } 25% { color: var(--aph-meals-accent); transform: scale(1.06); } }

/* recipes ease in as they scroll into the library's own scroller */
@supports (animation-timeline: view()) {
  .aph-meals .aph-meals-recipe { animation: aph-meals-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 60%; }
}
@keyframes aph-meals-rise { from { opacity: .3; transform: translateY(10px); } }

/* ── responsive ── */
@container aph-meals (max-width: 1099px) {
  .aph-meals .aph-meals-app { grid-template-columns: 220px minmax(0, 1fr) 270px; }
  .aph-meals .aph-meals-bacts .aph-meals-ghost span { display: none; }
}
@container aph-meals (max-width: 959px) {
  .aph-meals .aph-meals-app { grid-template-columns: 220px minmax(0, 1fr); grid-template-areas: "lib board" "tabs tabs"; }
  .aph-meals .aph-meals-list { grid-area: board; border-left: 0; }
  .aph-meals .aph-meals-tabs { display: flex; }
  .aph-meals .aph-meals-tabs [data-view-to="lib"] { display: none; }
  .aph-meals[data-view="list"] .aph-meals-board { display: none; }
  .aph-meals:not([data-view="list"]) .aph-meals-list { display: none; }
}
@container aph-meals (max-width: 759px) {
  .aph-meals .aph-meals-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "board" "tabs"; }
  .aph-meals .aph-meals-lib { grid-area: board; border-right: 0; }
  .aph-meals:not([data-view="lib"]) .aph-meals-lib { display: none; }
  .aph-meals[data-view="lib"] .aph-meals-board { display: none; }
  .aph-meals .aph-meals-tabs [data-view-to="lib"] { display: grid; }
  .aph-meals .aph-meals-toast { bottom: 70px; }
}
@container aph-meals-board (max-width: 480px) {
  .aph-meals .aph-meals-grid { grid-template-columns: 40px repeat(3, minmax(0, 1fr)); gap: 4px; padding: 0 10px 14px; }
  .aph-meals .aph-meals-bhead { padding: 12px 10px 8px; }
  .aph-meals .aph-meals-slot { min-height: 54px; padding: 6px 7px; }
  .aph-meals .aph-meals-slot.is-filled { padding-left: 11px; }
  .aph-meals .aph-meals-slot.is-filled::before { left: 4px; }
  .aph-meals .aph-meals-slot.is-filled b { font-size: 11.5px; }
  .aph-meals .aph-meals-slot.is-filled span { display: none; }
  .aph-meals .aph-meals-slot.is-left b::before { content: "↺ "; }
  .aph-meals .aph-meals-row.is-head span { font-size: 9px; letter-spacing: .06em; }
  .aph-meals .aph-meals-bacts .aph-meals-ghost span { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .aph-meals *, .aph-meals *::before, .aph-meals *::after { animation: none !important; transition-duration: 1ms !important; transition-delay: 0ms !important; }
  .aph-meals .aph-meals-ghostcard { rotate: 0deg; }
  .aph-meals .aph-meals-slot.is-over { transform: none; }
}

