/* Larder. The plan is the only state that matters: every shopping line, pack count
   and price is recomputed from it, so the list can never disagree with the week. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const eur = n => '€' + (Math.round(n * 100) / 100).toFixed(2);
const DAY = 864e5;
const dn = (y, m, d) => Math.round(Date.UTC(y, m, d) / DAY);
const ymd = n => { const t = new Date(n * DAY); return [t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate()]; };
const TODAY = dn(2026, 9, 2);
const MONF = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const DAYF = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const MEALS = ['Breakfast', 'Lunch', 'Dinner'];
const I = {
  plus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 6v12M6 12h12"/></svg>',
  minus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 12h12"/></svg>',
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  home: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 11 12 4l8 7M6 9.5V20h12V9.5"/><path d="M10 20v-5h4v5"/></svg>',
  trash: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.5 7h15M10 4h4M6.5 7l1 13h9l1-13"/></svg>',
  swap: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 4 4 7l3 3M4 7h12a4 4 0 0 1 4 4M17 20l3-3-3-3M20 17H8a4 4 0 0 1-4-4"/></svg>',
  box: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 8h16v4H4zM6 12v8h12v-8M12 8v12M12 8c-2-4-6-4-6-1.5S10 8 12 8c2 0 6 1 6-1.5S14 4 12 8"/></svg>',
};

/* ingredient: name, aisle, unit, pack size (in units), pack label, pack price, staple */
const ING = {
  onion: ['Onions', 'Produce', 'pc', 1, '', 0.25], garlic: ['Garlic', 'Produce', 'clove', 10, 'bulb', 0.6], ginger: ['Fresh ginger', 'Produce', 'g', 50, 'knob', 0.5],
  tomato: ['Vine tomatoes', 'Produce', 'pc', 1, '', 0.45], spinach: ['Baby spinach', 'Produce', 'g', 200, 'bag', 1.8], lemon: ['Lemons', 'Produce', 'pc', 1, '', 0.5],
