      const L = lines[ik] || (lines[ik] = { key: ik, need: 0, from: [] });
      L.need += q * k; if (L.from.indexOf(rc.short) < 0) L.from.push(rc.short);
    });
  });
  return Object.values(lines).map(L => {
    const [name, aisle, unit, pack, label, price] = ING[L.key];
    const packs = Math.max(1, Math.ceil(L.need / pack - 1e-6));
    return Object.assign(L, { name, aisle, unit, pack, label, packs, cost: Math.round(packs * price * 100) / 100, have: haveOf(L.key) });
