/* Longline: one goal time drives every pace, split and weekly total. */
@property --aph-run-t { syntax: "<integer>"; inherits: false; initial-value: 0; }
@property --aph-run-p { syntax: "<integer>"; inherits: false; initial-value: 0; }

.aph-run {
  /* re-theme: bg, ink, accent (volt) */
  --aph-run-bg: oklch(0.19 0.018 165);
  --aph-run-ink: oklch(0.95 0.012 120);
  --aph-run-accent: oklch(0.9 0.2 125);
  --aph-run-panel: color-mix(in oklab, var(--aph-run-bg) 93%, var(--aph-run-ink));
  --aph-run-raise: color-mix(in oklab, var(--aph-run-bg) 86%, var(--aph-run-ink));
  --aph-run-sunk: color-mix(in oklab, var(--aph-run-bg) 80%, black);
  --aph-run-line: color-mix(in oklab, var(--aph-run-ink) 10%, transparent);
  --aph-run-line2: color-mix(in oklab, var(--aph-run-ink) 18%, transparent);
  --aph-run-mute: color-mix(in oklab, var(--aph-run-ink) 62%, var(--aph-run-bg));
  --aph-run-faint: color-mix(in oklab, var(--aph-run-ink) 38%, var(--aph-run-bg));
  --aph-run-on: color-mix(in oklab, var(--aph-run-accent) 12%, black);
  /* zones */
  --aph-run-zE: oklch(0.64 0.07 168); --aph-run-zL: oklch(0.66 0.1 225); --aph-run-zM: oklch(0.76 0.13 85);
  --aph-run-zT: oklch(0.72 0.16 52); --aph-run-zI: var(--aph-run-accent); --aph-run-zR: oklch(0.7 0.17 350);
  --aph-run-zG: oklch(0.86 0.15 95); --aph-run-zJ: oklch(0.46 0.03 168);
  --aph-run-ease: cubic-bezier(.2, .8, .2, 1);
  --aph-run-spring: linear(0, 0.1 4%, 0.38 10%, 0.75 17%, 0.98 24%, 1.06 30%, 1.06 36%, 1.02 46%, 0.995 60%, 1);

  position: relative; width: 100%; height: var(--aph-run-h, 680px);
  container-type: inline-size; container-name: aph-run; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--aph-run-bg); color: var(--aph-run-ink); color-scheme: dark; accent-color: var(--aph-run-accent);
  border-radius: 14px; font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--aph-run-accent); outline-offset: 2px; border-radius: 6px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button[aria-disabled="true"] { cursor: not-allowed; opacity: .4; }
  & h2, & h3, & h4, & p, & ul, & ol, & dl, & dd, & dt { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & h2, & h3 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; display: inline-block; text-align: center; border: 1px solid var(--aph-run-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--aph-run-mute); }
  & [hidden] { display: none !important; }
  & .aph-run-num { font-family: ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
}
.aph-run .aph-run-app {
  height: 100%; display: grid; grid-template-columns: 262px minmax(0, 1fr) 318px; grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "goal plan detail" "tabs tabs tabs";
}

/* ── goal rail ── */
.aph-run .aph-run-goal {
  grid-area: goal; overflow: auto; overscroll-behavior: contain; padding: 0 16px 18px; border-right: 1px solid var(--aph-run-line); background: var(--aph-run-sunk);
  display: grid; grid-template-columns: minmax(0, 1fr); align-content: start; gap: 14px; min-width: 0; scrollbar-width: thin; scrollbar-color: var(--aph-run-line2) transparent;
}
.aph-run .aph-run-brand {
  display: flex; align-items: center; gap: 8px; padding: 16px 0 2px;
  & svg { color: var(--aph-run-accent); width: 22px; height: 22px; stroke-width: 2.2; }
  & b { font-weight: 800; letter-spacing: -.02em; font-size: 15px; font-style: italic; }
  & span { margin-left: auto; font-size: 11.5px; color: var(--aph-run-mute); }
}
.aph-run .aph-run-race {
  & small { font-size: 10px; text-transform: uppercase; letter-spacing: .14em; color: var(--aph-run-faint); font-weight: 700; }
  & h2 { font-size: clamp(20px, 2.1cqi, 24px); font-weight: 800; letter-spacing: -.03em; line-height: 1.1; margin-top: 2px; }
  & p { color: var(--aph-run-mute); font-size: 12px; margin-top: 3px; }
  & p b { color: var(--aph-run-accent); font-weight: 700; }
}
.aph-run .aph-run-target {
  padding: 14px 12px 12px; border-radius: 16px; background: var(--aph-run-panel); border: 1px solid var(--aph-run-line); display: grid; justify-items: center; gap: 4px;
  & .aph-run-tline { display: flex; align-items: center; gap: 6px; width: 100%; justify-content: space-between; }
  & .aph-run-tline button { width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center; background: var(--aph-run-raise); transition: transform .15s var(--aph-run-spring), background .15s; }
  & .aph-run-tline button:active { transform: scale(.88); }
  & .aph-run-gp { font-size: 12px; color: var(--aph-run-mute); font-variant-numeric: tabular-nums; }
  & .aph-run-gp b { color: var(--aph-run-ink); font-family: ui-monospace, Menlo, monospace; }
  & .aph-run-reset { font-size: 11.5px; color: var(--aph-run-accent); text-decoration: underline; text-underline-offset: 3px; text-decoration-color: color-mix(in oklab, var(--aph-run-accent) 40%, transparent); }
}
/* the goal clock and every pace roll through integer @properties; CSS splits h:mm:ss with round() and mod() */
.aph-run .aph-run-clock { font: 750 clamp(30px, 3.4cqi, 38px)/1 ui-monospace, Menlo, monospace; letter-spacing: -.05em; font-variant-numeric: tabular-nums; }
.aph-run .aph-run-ctr, .aph-run .aph-run-pctr { display: none; }
@supports (width: round(down, 7.5px, 1px)) and (width: mod(7px, 3px)) {
  .aph-run .aph-run-fall { display: none; }
  .aph-run .aph-run-ctr {
    display: inline; transition: --aph-run-t .9s var(--aph-run-ease);
    counter-reset: aph-run-h round(down, var(--aph-run-t) / 3600, 1) aph-run-m mod(round(down, var(--aph-run-t) / 60, 1), 60) aph-run-s mod(var(--aph-run-t), 60);
    &::before { content: counter(aph-run-h) ":" counter(aph-run-m, decimal-leading-zero) ":" counter(aph-run-s, decimal-leading-zero); }
  }
  .aph-run .aph-run-pctr {
    display: inline; transition: --aph-run-p .9s var(--aph-run-ease); transition-delay: calc(var(--i, 0) * 50ms);
    counter-reset: aph-run-pm round(down, var(--aph-run-p) / 60, 1) aph-run-ps mod(var(--aph-run-p), 60);
    &::before { content: counter(aph-run-pm) ":" counter(aph-run-ps, decimal-leading-zero); }
  }
}
.aph-run .aph-run-units {
  display: grid; grid-template-columns: 1fr 1fr; padding: 3px; border-radius: 10px; background: var(--aph-run-panel); border: 1px solid var(--aph-run-line);
  & button { height: 28px; border-radius: 7px; font-weight: 650; font-size: 12px; color: var(--aph-run-mute); transition: background .2s, color .2s; }
  & button[aria-checked="true"] { background: var(--aph-run-ink); color: var(--aph-run-bg); }
}
.aph-run .aph-run-zones, .aph-run .aph-run-pred {
  & h3 { font-size: 10.5px; text-transform: uppercase; letter-spacing: .13em; color: var(--aph-run-faint); font-weight: 700; display: flex; justify-content: space-between; margin-bottom: 8px; }
  & h3 span { text-transform: none; letter-spacing: 0; font-family: ui-monospace, Menlo, monospace; }
}
.aph-run .aph-run-zones ul { display: grid; gap: 2px; }
.aph-run .aph-run-zones li {
  display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 6px 8px; border-radius: 9px;
  & i { width: 8px; height: 22px; border-radius: 3px; background: var(--z); }
  & b { font-weight: 640; font-size: 12.5px; }
  & .aph-run-zd { display: block; font-size: 11px; color: var(--aph-run-faint); }
  & em { font: 650 13px/1 ui-monospace, Menlo, monospace; font-style: normal; font-variant-numeric: tabular-nums; text-align: right; }
  & em small { display: block; font: 500 10.5px/1.4 ui-monospace, Menlo, monospace; color: var(--aph-run-faint); }
  &.is-hot { background: color-mix(in oklab, var(--z) 14%, transparent); }
  &.is-flash em { animation: aph-run-flash .8s var(--aph-run-ease); }
}
.aph-run .aph-run-pred {
  & dl { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
  & dl div { padding: 8px; border-radius: 10px; background: var(--aph-run-panel); }
  & dt { font-size: 10px; text-transform: uppercase; letter-spacing: .1em; color: var(--aph-run-faint); font-weight: 700; }
  & dd { font: 700 13.5px/1.3 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; letter-spacing: -.03em; }
  & p { font-size: 11px; color: var(--aph-run-faint); margin-top: 8px; }
}

/* ── plan ── */
.aph-run .aph-run-plan { grid-area: plan; display: grid; grid-template-rows: auto auto minmax(0, 1fr); min-height: 0; min-width: 0; container-type: inline-size; container-name: aph-run-plan; }
.aph-run .aph-run-phead {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 10px; padding: 16px 16px 8px; flex-wrap: wrap;
  & h2 { font-size: clamp(17px, 3.4cqi, 21px); font-weight: 800; letter-spacing: -.025em; }
  & p { font-size: 12px; color: var(--aph-run-mute); font-variant-numeric: tabular-nums; }
}
.aph-run .aph-run-seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--aph-run-panel); border: 1px solid var(--aph-run-line);
  & button { height: 26px; padding: 0 11px; border-radius: 7px; font-size: 12px; font-weight: 650; color: var(--aph-run-mute); transition: background .2s, color .2s; }
  & button[aria-selected="true"] { background: var(--aph-run-raise); color: var(--aph-run-ink); }
}
.aph-run .aph-run-legend {
  display: flex; flex-wrap: wrap; gap: 4px 12px; padding: 0 16px 8px; font-size: 11px; color: var(--aph-run-mute);
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 9px; height: 9px; border-radius: 3px; background: var(--z); }
}
.aph-run .aph-run-body { overflow: auto; overscroll-behavior: contain; padding: 0 16px 16px; scrollbar-width: thin; scrollbar-color: var(--aph-run-line2) transparent; }
.aph-run .aph-run-grid {
  display: grid; grid-template-columns: 50px repeat(7, minmax(0, 1fr)) 62px; gap: 4px; min-width: 470px;
  & .aph-run-wrow { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: stretch; }
  & .aph-run-wrow.is-head { position: sticky; top: 0; z-index: 2; background: var(--aph-run-bg); padding-bottom: 2px; }
  & .aph-run-wrow.is-head span { font-size: 10px; text-transform: uppercase; letter-spacing: .1em; color: var(--aph-run-faint); font-weight: 700; text-align: center; }
  & .aph-run-wrow.is-now .aph-run-wk b { color: var(--aph-run-accent); }
  & .aph-run-wrow.is-phase { margin-top: 6px; }
  & .aph-run-wk { display: grid; align-content: center; line-height: 1.1; }
  & .aph-run-wk b { font: 700 12px/1 ui-monospace, Menlo, monospace; }
  & .aph-run-wk span { font-size: 9.5px; text-transform: uppercase; letter-spacing: .1em; color: var(--aph-run-faint); font-weight: 700; margin-top: 3px; }
  & .aph-run-tot { display: grid; align-content: center; justify-items: end; gap: 4px; font: 650 12px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
  & .aph-run-tot i { width: 100%; height: 4px; border-radius: 2px; background: linear-gradient(90deg, var(--aph-run-accent) calc(var(--d) * 100%), var(--aph-run-line2) 0); }
}
.aph-run .aph-run-day {
  --z: var(--aph-run-line2);
  position: relative; min-height: 38px; border-radius: 8px; display: grid; align-content: center; justify-items: start; padding: 4px 6px; text-align: left;
  background: color-mix(in oklab, var(--z) 16%, var(--aph-run-bg)); border: 1px solid color-mix(in oklab, var(--z) 30%, transparent);
  cursor: pointer; touch-action: none; user-select: none; transition: transform .2s var(--aph-run-spring), background .2s, border-color .2s, box-shadow .2s;
  & b { font-size: 9.5px; text-transform: uppercase; letter-spacing: .08em; font-weight: 800; color: color-mix(in oklab, var(--z) 85%, var(--aph-run-ink)); }
  & span { font: 650 12px/1.1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; letter-spacing: -.03em; }
  & svg { position: absolute; right: 5px; bottom: 6px; width: 11px; height: 11px; stroke-width: 3; color: var(--aph-run-on); }
  &:hover { border-color: var(--z); }
  &.is-rest { background: transparent; border: 1px dashed var(--aph-run-line); }
  &.is-rest b { color: var(--aph-run-faint); }
  &.is-done { background: var(--z); border-color: var(--z); }
  &.is-done b, &.is-done span { color: var(--aph-run-on); }
  &.is-skip { background: repeating-linear-gradient(135deg, transparent 0 4px, var(--aph-run-line) 4px 5px); }
  &.is-skip span { text-decoration: line-through; color: var(--aph-run-faint); }
  &.is-today { box-shadow: 0 0 0 2px var(--aph-run-bg), 0 0 0 3.5px var(--aph-run-ink); }
  &[aria-selected="true"] { box-shadow: 0 0 0 2px var(--aph-run-bg), 0 0 0 4px var(--aph-run-accent); transform: scale(1.04); z-index: 1; }
  &.is-over { border: 1.5px dashed var(--aph-run-accent); transform: scale(1.06); }
  &.is-dragging { opacity: .3; }
  &.is-moved { animation: aph-run-land .5s var(--aph-run-spring); }
}
.aph-run .aph-run-load {
  & svg { width: 100%; height: auto; display: block; overflow: visible; }
  & text { font: 600 10px ui-monospace, Menlo, monospace; fill: var(--aph-run-faint); stroke: none; }
  & .aph-run-gl { stroke: var(--aph-run-line); stroke-width: 1; }
  & .aph-run-bp { fill: var(--aph-run-line2); stroke: none; }
  & .aph-run-bd { fill: var(--aph-run-accent); stroke: none; transform-box: fill-box; transform-origin: bottom; animation: aph-run-grow .7s var(--aph-run-spring) both; animation-delay: calc(var(--i) * 35ms); }
  & .aph-run-ll { stroke: var(--aph-run-zL); stroke-width: 2; fill: none; }
  & .aph-run-lp { fill: var(--aph-run-bg); stroke: var(--aph-run-zL); stroke-width: 2; }
  & .aph-run-now { stroke: var(--aph-run-ink); stroke-dasharray: 2 3; }
  & p { font-size: 11.5px; color: var(--aph-run-mute); margin-top: 8px; }
  & table { width: 100%; border-collapse: collapse; margin-top: 14px; font-size: 12px; font-variant-numeric: tabular-nums; }
  & th { text-align: right; font-size: 10px; text-transform: uppercase; letter-spacing: .1em; color: var(--aph-run-faint); font-weight: 700; padding: 0 0 6px; }
  & th:first-child, & td:first-child { text-align: left; }
  & td { padding: 6px 0; border-top: 1px solid var(--aph-run-line); text-align: right; font-family: ui-monospace, Menlo, monospace; }
  & tfoot td { font-weight: 750; border-top: 1px solid var(--aph-run-line2); }
}

/* ── detail ── */
.aph-run .aph-run-detail {
  grid-area: detail; overflow: hidden auto; overscroll-behavior: contain; border-left: 1px solid var(--aph-run-line); padding: 16px 16px 20px;
  display: grid; grid-template-columns: minmax(0, 1fr); align-content: start; gap: 14px; min-width: 0; scrollbar-width: thin; scrollbar-color: var(--aph-run-line2) transparent;
  & .aph-run-dtop { display: flex; align-items: center; gap: 8px; }
  & .aph-run-badge { font-size: 10px; text-transform: uppercase; letter-spacing: .12em; font-weight: 800; padding: 3px 7px; border-radius: 5px; background: var(--z); color: var(--aph-run-on); }
  & .aph-run-dtop span { font-size: 12px; color: var(--aph-run-mute); }
  & .aph-run-dtop .aph-run-st { margin-left: auto; font-weight: 650; }
  & h2 { font-size: clamp(20px, 2.1cqi, 25px); font-weight: 800; letter-spacing: -.03em; line-height: 1.1; }
  & .aph-run-why { color: var(--aph-run-mute); font-size: 12.5px; margin-top: -6px; }
  & .aph-run-kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
  & .aph-run-kpis div { padding: 9px 10px; border-radius: 11px; background: var(--aph-run-panel); }
  & .aph-run-kpis small { display: block; font-size: 9.5px; text-transform: uppercase; letter-spacing: .12em; color: var(--aph-run-faint); font-weight: 700; }
  & .aph-run-kpis b { font: 700 16px/1.25 ui-monospace, Menlo, monospace; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
}
.aph-run .aph-run-bar {
  display: flex; height: 30px; gap: 2px; border-radius: 8px; overflow: hidden;
  & i { flex: var(--w) 1 0; background: var(--z); min-width: 2px; transform-origin: left; animation: aph-run-seg .6s var(--aph-run-ease) both; animation-delay: calc(var(--i) * 25ms); }
  & i.is-low { height: 55%; align-self: end; }
}
.aph-run .aph-run-segs {
  display: grid; gap: 1px;
  & li { display: grid; grid-template-columns: 8px minmax(0, 1fr) auto auto; gap: 10px; align-items: center; padding: 7px 2px; border-top: 1px solid var(--aph-run-line); font-size: 12.5px; }
  & li:first-child { border-top: 0; }
  & li i { width: 8px; height: 8px; border-radius: 2px; background: var(--z); }
  & li span { color: var(--aph-run-mute); font: 600 11.5px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; text-align: right; }
  & li b { font: 650 12px/1 ui-monospace, Menlo, monospace; text-align: right; min-width: 44px; font-variant-numeric: tabular-nums; }
  & li.is-total { border-top: 1px solid var(--aph-run-line2); font-weight: 750; }
}
.aph-run .aph-run-acts { display: flex; flex-wrap: wrap; gap: 6px; }
.aph-run .aph-run-btn {
  display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 12px; border-radius: 10px; font-weight: 650; font-size: 12.5px;
  background: var(--aph-run-raise); transition: transform .15s var(--aph-run-spring), filter .15s;
  & svg { width: 16px; height: 16px; }
  &:active { transform: scale(.96); }
  &.is-primary { background: var(--aph-run-accent); color: var(--aph-run-on); }
  &.is-primary:hover { filter: brightness(1.06); }
}
.aph-run .aph-run-log {
  display: grid; gap: 10px; padding: 14px; border-radius: 14px; background: var(--aph-run-panel); border: 1px solid var(--aph-run-line2);
  transition: opacity .2s, transform .35s var(--aph-run-spring);
  @starting-style { opacity: 0; transform: translateY(8px); }
  & h4 { font-size: 13px; font-weight: 750; }
  & .aph-run-f2 { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
  & label { display: grid; gap: 4px; font-size: 11px; color: var(--aph-run-mute); font-weight: 650; }
  & input, & textarea { width: 100%; min-width: 0; height: 36px; padding: 0 10px; border-radius: 9px; border: 1px solid var(--aph-run-line2); background: var(--aph-run-sunk); font: 600 14px/1 ui-monospace, Menlo, monospace; }
  & textarea { height: 54px; padding: 8px 10px; font: 13px/1.4 system-ui; resize: none; }
  & input:focus, & textarea:focus { outline: 2px solid var(--aph-run-accent); outline-offset: 0; }
  & [aria-invalid="true"] { border-color: oklch(0.65 0.2 25); }
  & .aph-run-feel { display: flex; gap: 4px; }
  & .aph-run-feel button { flex: 1; height: 30px; border-radius: 8px; background: var(--aph-run-sunk); font-size: 11.5px; font-weight: 650; color: var(--aph-run-mute); }
  & .aph-run-feel button[aria-checked="true"] { background: var(--aph-run-ink); color: var(--aph-run-bg); }
  & .aph-run-err { color: oklch(0.75 0.16 30); font-size: 12px; min-height: 0; }
  & .aph-run-err:empty { display: none; }
}
.aph-run .aph-run-actual { padding: 12px; border-radius: 12px; background: color-mix(in oklab, var(--aph-run-accent) 10%, var(--aph-run-bg)); border: 1px solid color-mix(in oklab, var(--aph-run-accent) 30%, transparent); font-size: 12.5px; }
.aph-run .aph-run-actual b { font-family: ui-monospace, Menlo, monospace; }

/* ── tabs, menu, toast ── */
.aph-run .aph-run-tabs {
  grid-area: tabs; display: none; gap: 4px; padding: 6px 8px; border-top: 1px solid var(--aph-run-line); background: var(--aph-run-sunk);
  & button { flex: 1; display: grid; justify-items: center; gap: 2px; padding: 5px 0 3px; border-radius: 9px; font-size: 10.5px; font-weight: 650; color: var(--aph-run-faint); }
  & button[aria-current="page"] { color: var(--aph-run-accent); background: var(--aph-run-panel); }
}
.aph-run .aph-run-menu {
  position: absolute; z-index: 30; min-width: 220px; padding: 6px; border-radius: 12px; background: var(--aph-run-raise); border: 1px solid var(--aph-run-line2);
  box-shadow: 0 18px 50px oklch(0 0 0 / .5); transition: opacity .15s, transform .22s var(--aph-run-ease);
  @starting-style { opacity: 0; transform: translateY(-4px) scale(.97); }
  & small { display: block; padding: 6px 10px 4px; font-size: 10px; text-transform: uppercase; letter-spacing: .12em; color: var(--aph-run-faint); font-weight: 700; }
  & button { width: 100%; display: flex; justify-content: space-between; gap: 10px; padding: 8px 10px; border-radius: 8px; text-align: left; font-size: 12.5px; }
  & button span { color: var(--aph-run-faint); font-size: 11.5px; }
  & button:hover, & button:focus-visible { background: var(--aph-run-panel); outline: none; }
}
.aph-run .aph-run-toast {
  position: absolute; z-index: 40; left: 50%; bottom: 16px; translate: -50% 0; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 24px);
  padding: 9px 9px 9px 14px; border-radius: 12px; background: var(--aph-run-ink); color: var(--aph-run-bg); font-weight: 600; font-size: 12.5px;
  box-shadow: 0 14px 40px oklch(0 0 0 / .5); transition: opacity .25s, translate .45s var(--aph-run-spring);
  &:empty { display: none; }
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & button { height: 28px; padding: 0 10px; border-radius: 8px; background: color-mix(in oklab, var(--aph-run-bg) 12%, transparent); font-weight: 750; white-space: nowrap; }
  @starting-style { opacity: 0; translate: -50% 16px; }
}
@keyframes aph-run-flash { 0% { color: var(--aph-run-accent); } 100% { color: inherit; } }
@keyframes aph-run-land { from { transform: scale(.8); } }
@keyframes aph-run-grow { from { transform: scaleY(0); } }
@keyframes aph-run-seg { from { transform: scaleX(0); opacity: 0; } }

/* the plan scroller dims weeks that have scrolled under the sticky day header */
@supports (animation-timeline: view()) {
  .aph-run .aph-run-wrow:not(.is-head) { animation: aph-run-under linear both; animation-timeline: view(); animation-range: exit 60% exit 100%; }
}
@keyframes aph-run-under { to { opacity: .25; } }

/* ── responsive ── */
@container aph-run (max-width: 1099px) {
  .aph-run .aph-run-app { grid-template-columns: 236px minmax(0, 1fr) 290px; }
}
@container aph-run (max-width: 959px) {
  .aph-run .aph-run-app { grid-template-columns: 236px minmax(0, 1fr); grid-template-areas: "goal plan" "tabs tabs"; }
  .aph-run .aph-run-detail { grid-area: plan; border-left: 0; }
  .aph-run .aph-run-tabs { display: flex; }
  .aph-run .aph-run-tabs [data-view-to="goal"] { display: none; }
  .aph-run[data-view="detail"] .aph-run-plan { display: none; }
  .aph-run:not([data-view="detail"]) .aph-run-detail { display: none; }
}
@container aph-run (max-width: 759px) {
  .aph-run .aph-run-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "plan" "tabs"; }
  .aph-run .aph-run-goal { grid-area: plan; border-right: 0; }
  .aph-run:not([data-view="goal"]) .aph-run-goal { display: none; }
