}
@container aph-run-plan (max-width: 500px) {
  .aph-run .aph-run-grid { grid-template-columns: 34px repeat(7, minmax(0, 1fr)) 44px; gap: 3px; min-width: 0; }
  .aph-run .aph-run-day { min-height: 34px; padding: 3px; justify-items: center; }
