/* Longline. The goal time is the only pace input: zone pace = goal pace × zone factor,
   segment time = distance × zone pace, and every total is a sum of those. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const DAY = 864e5;
const dn = (y, m, d) => Math.round(Date.UTC(y, m, d) / DAY);
const ymd = n => { const t = new Date(n * DAY); return [t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate()]; };
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const WD = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const START = dn(2026, 8, 7), RACE = dn(2026, 10, 29), TODAY = dn(2026, 9, 2), GOAL0 = 6300;
const HALF = 21.0975, MI = 1.609344;
const fmtD = n => WD[(n - START) % 7] + ' ' + ymd(n)[2] + ' ' + MON[ymd(n)[1]];
const hms = s => { s = Math.round(s); const h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60), x = s % 60; return (h ? h + ':' + String(m).padStart(2, '0') : m) + ':' + String(x).padStart(2, '0'); };
const I = {
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  skip: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 5l14 14M19 5 5 19"/></svg>',
  move: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h16M8 8l-4 4 4 4M16 8l4 4-4 4"/></svg>',
  back: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 7 4 12l5 5M4 12h11a5 5 0 0 1 0 10h-1"/></svg>',
  edit: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h4L19 9l-4-4L4 16z"/></svg>',
};

/* ── zones: factor × goal pace ── */
const Z = {
  E: { n: 'Easy', f: 1.26, lo: 1.22, hi: 1.30, why: 'Conversational. Most of the week lives here.' },
  L: { n: 'Long', f: 1.2, lo: 1.17, hi: 1.24, why: 'Steady and patient; time on feet matters more than pace.' },
  M: { n: 'Steady', f: 1.07, lo: 1.05, hi: 1.09, why: 'Comfortably hard, a notch slower than goal pace.' },
  T: { n: 'Threshold', f: 0.97, lo: 0.955, hi: 0.985, why: 'The pace you could hold for about an hour.' },
  I: { n: 'Interval', f: 0.91, lo: 0.895, hi: 0.925, why: 'Hard repeats with jog recoveries; even splits.' },
  R: { n: 'Repetition', f: 0.86, lo: 0.85, hi: 0.87, why: 'Short, fast and relaxed. Full recovery between.' },
  G: { n: 'Goal', f: 1, lo: 1, hi: 1, why: 'Race pace — rehearse it so it feels familiar.' },
  J: { n: 'Jog', f: 1.42, lo: 1.38, hi: 1.46, why: 'Recovery between repeats.' },
};
const ZLIST = ['E', 'L', 'M', 'T', 'I', 'R'];

/* ── workout builders ── */
let uid = 0;
const mk = (type, abbr, z, title, segs) => ({ id: 'w' + (++uid), type, abbr, z, title, segs });
const E = d => mk('easy', 'Easy', 'E', d + ' km easy', [{ z: 'E', d, l: 'Easy' }]);
const S = d => mk('easy', 'Easy+', 'E', d + ' km easy + strides', [{ z: 'E', d: d - 0.6, l: 'Easy' }, { z: 'R', d: 0.6, l: '6 × 100 m strides', n: 6, each: 0.1, rec: 0 }]);
const L = d => mk('long', 'Long', 'L', d + ' km long run', [{ z: 'L', d, l: 'Long, conversational' }]);
const T = d => mk('tempo', 'Tempo', 'T', d + ' km tempo', [{ z: 'E', d: 2, l: 'Warm-up' }, { z: 'T', d, l: 'Tempo' }, { z: 'E', d: 1.5, l: 'Cool-down' }]);
const M = d => mk('steady', 'Steady', 'M', d + ' km steady', [{ z: 'E', d: 1.5, l: 'Warm-up' }, { z: 'M', d, l: 'Steady' }, { z: 'E', d: 1.5, l: 'Cool-down' }]);
const Iv = (n, rep, rec, z = 'I') => mk(z === 'R' ? 'reps' : z === 'G' ? 'goal' : 'int', z === 'R' ? 'Reps' : z === 'G' ? 'Pace' : 'Int', z, n + ' × ' + (rep >= 1 ? rep + ' km' : rep * 1000 + ' m') + (z === 'G' ? ' at goal' : ''),
  [{ z: 'E', d: 2, l: 'Warm-up' }, { z, d: +(n * rep).toFixed(2), l: n + ' × ' + (rep >= 1 ? rep + ' km' : rep * 1000 + ' m'), n, each: rep, rec }, { z: 'J', d: +((n - 1) * rec).toFixed(2), l: (n - 1) + ' × ' + rec * 1000 + ' m jog' }, { z: 'E', d: 1.5, l: 'Cool-down' }]);
const RACEW = () => mk('race', 'Race', 'G', 'Riverside Half', [{ z: 'G', d: HALF, l: 'Race at goal pace' }]);
const PLAN = [
  ['Base', Iv(5, 0.6, 0.4), E(6), T(4), S(5), L(12)], ['Base', Iv(6, 0.6, 0.4), E(6), T(5), S(5), L(13)],
  ['Base', Iv(5, 0.8, 0.4), E(7), M(6), S(5), L(14)], ['Base', Iv(4, 1, 0.4), E(6), T(4), S(5), L(12)],
  ['Build', Iv(6, 0.8, 0.4), E(7), T(6), S(6), L(15)], ['Build', Iv(5, 1, 0.4), E(7), M(8), S(6), L(16)],
  ['Build', Iv(8, 0.4, 0.2, 'R'), E(8), T(7), S(6), L(17)], ['Build', Iv(5, 1, 0.4), E(6), M(6), S(5), L(14)],
  ['Peak', Iv(6, 1, 0.4), E(8), T(8), S(6), L(18)], ['Peak', Iv(4, 1.6, 0.6), E(8), M(10), S(6), L(19)],
  ['Taper', Iv(6, 0.8, 0.4), E(6), T(5), S(5), L(14)], ['Race', Iv(3, 1, 0.4, 'G'), E(5), E(4), S(3), RACEW()],
].map(([ph, tue, wed, thu, fri, sun]) => ({ ph, days: [null, tue, wed, thu, fri, null, sun] }));

/* ── state ── */
const St = { goal: GOAL0, unit: 'km', sel: TODAY, pv: 'cal', view: 'plan', log: null, status: {}, moved: null };
const dist = w => w ? w.segs.reduce((a, s) => a + s.d, 0) : 0;
const pace = z => St.goal / HALF * Z[z].f;
const secs = w => w ? w.segs.reduce((a, s) => a + s.d * pace(s.z), 0) : 0;
const dayOf = (wi, d) => START + wi * 7 + d;
const at = n => { const o = n - START; if (o < 0 || o >= 84) return null; return { wi: Math.floor(o / 7), d: o % 7 }; };
const wkOf = n => at(n).wi;
const work = n => { const p = at(n); return p ? PLAN[p.wi].days[p.d] : null; };
(function seed() {
  let r = 7;
  const rnd = () => { r = (r * 16807) % 2147483647; return r / 2147483647; };
  for (let n = START; n < TODAY; n++) {
    const w = work(n); if (!w) continue;
    if (n === START + 9) { St.status[w.id] = { st: 'skip' }; continue; }
    const d = Math.round((dist(w) + (rnd() < 0.4 ? 0.1 : 0)) * 10) / 10;
    St.status[w.id] = { st: 'done', d, t: Math.round(secs(w) * (0.975 + rnd() * 0.06)), feel: 2 + Math.floor(rnd() * 3), note: '' };
  }
})();
const status = w => (w && St.status[w.id]) || null;

/* units */
const ud = km => St.unit === 'km' ? km : km / MI;
const dTxt = km => (Math.round(ud(km) * 10) / 10).toFixed(1);
const pTxt = s => hms(St.unit === 'km' ? s : s * MI);
const pSec = s => Math.round(St.unit === 'km' ? s : s * MI);
const U = () => St.unit === 'km' ? 'km' : 'mi';

/* ── undo & toast ── */
const undoStack = [];
function remember() { undoStack.push(JSON.stringify({ goal: St.goal, status: St.status, plan: PLAN.map(w => w.days.map(x => x && x.id)) })); if (undoStack.length > 40) undoStack.shift(); }
const byId = {}; PLAN.forEach(w => w.days.forEach(x => { if (x) byId[x.id] = x; }));
function undo() {
  const v = undoStack.pop(); if (!v) { toast('Nothing to undo'); return; }
  const o = JSON.parse(v); St.goal = o.goal; St.status = o.status;
  o.plan.forEach((days, wi) => { PLAN[wi].days = days.map(id => id ? byId[id] : null); });
  St.log = null; render(); toast('Undone');
}
let toastT = 0;
function toast(msg, withUndo) {
  const t = $('[data-toast]');
  t.innerHTML = '<span>' + msg + '</span>' + (withUndo ? '<button type="button" data-act="undo">Undo <kbd>⌘Z</kbd></button>' : '');
  clearTimeout(toastT); toastT = setTimeout(() => { if (root.isConnected) t.innerHTML = ''; }, withUndo ? 6000 : 3500);
}

/* ── render ── */
function keepFocus(fn) {
  const a = doc.activeElement, k = a && root.contains(a) && a.dataset ? a.dataset.k : null;
  fn();
  if (k) { const el = root.querySelector('[data-k="' + k + '"]'); if (el && el !== doc.activeElement) el.focus({ preventScroll: true }); }
}
function render() { keepFocus(() => { renderGoal(); renderPlan(); renderDetail(); renderTabs(); }); }

function renderGoal() {
  $('[data-days]').textContent = (RACE - TODAY) + ' days to go';
  $('.aph-run-ctr').style.setProperty('--aph-run-t', St.goal);
  $('[data-goaltxt]').textContent = hms(St.goal);
  $('[data-goal]').setAttribute('aria-label', 'Goal time ' + hms(St.goal));
  $('[data-goalpace]').innerHTML = 'Goal pace <b>' + pTxt(St.goal / HALF) + '</b> /' + U();
  const gm = $('[data-act="goal-"]'), gp = $('[data-act="goal+"]');
  if (St.goal <= 4500) { gm.setAttribute('aria-disabled', 'true'); gm.title = '1:15:00 is the fastest goal this plan supports'; } else { gm.removeAttribute('aria-disabled'); gm.title = 'One minute faster ( [ ), Shift for ten seconds'; }
  if (St.goal >= 9900) { gp.setAttribute('aria-disabled', 'true'); gp.title = '2:45:00 is the slowest goal this plan supports'; } else { gp.removeAttribute('aria-disabled'); gp.title = 'One minute slower ( ] ), Shift for ten seconds'; }
  $('[data-act="goal-reset"]').hidden = St.goal === GOAL0;
  $$('[data-unit]').forEach(b => b.setAttribute('aria-checked', String(b.dataset.unit === St.unit)));
  $('[data-perunit]').textContent = '/' + U();
  const sel = work(St.sel), used = new Set(sel ? sel.segs.map(s => s.z) : []);
  const ul = $('[data-zones]');
  if (!ul.firstChild) ul.innerHTML = ZLIST.map((z, i) => '<li style="--z:var(--aph-run-z' + z + ')" data-z="' + z + '"><i></i><div><b>' + Z[z].n + '</b><span class="aph-run-zd">' + Z[z].why + '</span></div><em><span class="aph-run-pctr" style="--i:' + i + '"></span><span class="aph-run-fall"></span><small></small></em></li>').join('');
  $$('li', ul).forEach(li => {
    const z = li.dataset.z, p = pace(z);
    li.classList.toggle('is-hot', used.has(z));
    li.querySelector('.aph-run-pctr').style.setProperty('--aph-run-p', pSec(p));
    li.querySelector('.aph-run-fall').textContent = pTxt(p);
    li.querySelector('small').textContent = Z[z].lo === Z[z].hi ? '' : pTxt(St.goal / HALF * Z[z].lo) + '–' + pTxt(St.goal / HALF * Z[z].hi);
    li.querySelector('em').setAttribute('aria-label', Z[z].n + ' pace ' + pTxt(p) + ' per ' + (St.unit === 'km' ? 'kilometre' : 'mile'));
  });
  const rg = (d) => St.goal * Math.pow(d / HALF, 1.06);
  $('[data-pred]').innerHTML = [['5K', 5], ['10K', 10], ['Marathon', 42.195]].map(([n, d]) => '<div><dt>' + n + '</dt><dd>' + hms(rg(d)) + '</dd></div>').join('');
}

function weekTotals(wi) {
  const days = PLAN[wi].days; let plan = 0, done = 0, t = 0;
  days.forEach(w => { if (!w) return; plan += dist(w); t += secs(w); const s = status(w); if (s && s.st === 'done') done += s.d; });
  return { plan, done, t };
}
function renderPlan() {
  const wi = clamp(wkOf(TODAY), 0, 11), wt = weekTotals(wi);
  $('[data-plansub]').textContent = 'Week ' + (wi + 1) + ' of 12 · ' + PLAN[wi].ph + ' · ' + dTxt(wt.done) + ' of ' + dTxt(wt.plan) + ' ' + U() + ' this week';
  $$('[data-pv]').forEach(b => b.setAttribute('aria-selected', String(b.dataset.pv === St.pv)));
  const types = [['E', 'Easy'], ['L', 'Long'], ['M', 'Steady'], ['T', 'Tempo'], ['I', 'Intervals'], ['R', 'Reps'], ['G', 'Goal pace']];
  $('[data-legend]').innerHTML = types.map(([z, n]) => '<span style="--z:var(--aph-run-z' + z + ')"><i></i>' + n + '</span>').join('') + '<span style="margin-left:auto;color:var(--aph-run-faint)"><kbd>←</kbd><kbd>→</kbd> day · <kbd>L</kbd> log · <kbd>Alt</kbd>+<kbd>→</kbd> move</span>';
  const body = $('[data-body]');
  if (St.pv === 'load') { renderLoad(body); return; }
  let html = '<div class="aph-run-grid" role="grid" aria-label="Training plan"><div class="aph-run-wrow is-head" role="row"><span></span>' + WD.map(d => '<span role="columnheader">' + d.slice(0, 2) + '</span>').join('') + '<span role="columnheader">' + U() + '</span></div>';
  PLAN.forEach((wk, i) => {
    const t = weekTotals(i), first = !i || PLAN[i - 1].ph !== wk.ph;
    html += '<div class="aph-run-wrow' + (i === wkOf(TODAY) ? ' is-now' : '') + (first && i ? ' is-phase' : '') + '" role="row"><div class="aph-run-wk" role="rowheader"><b>W' + (i + 1) + '</b>' + (first ? '<span>' + wk.ph + '</span>' : '') + '</div>';
    wk.days.forEach((w, d) => {
      const n = dayOf(i, d), s = status(w), cls = ['aph-run-day'];
      if (!w) cls.push('is-rest'); else if (s && s.st === 'done') cls.push('is-done'); else if (s && s.st === 'skip') cls.push('is-skip');
      if (n === TODAY) cls.push('is-today');
      if (St.moved && w && St.moved === w.id) cls.push('is-moved');
      const lbl = fmtD(n) + ': ' + (w ? w.title + (s ? ', ' + (s.st === 'done' ? 'done' : 'skipped') : n < TODAY ? ', missed' : '') : 'rest');
      html += '<button type="button" role="gridcell" class="' + cls.join(' ') + '" style="--z:var(--aph-run-z' + (w ? w.z : 'E') + ')" data-day="' + n + '" data-k="d' + n + '" aria-selected="' + (n === St.sel) + '" tabindex="' + (n === St.sel ? 0 : -1) + '" aria-label="' + esc(lbl) + '"' + (w && !s && n >= TODAY ? ' data-drag="1"' : '') + '>' +
        (w ? '<b>' + w.abbr + '</b><span>' + dTxt(dist(w)) + '</span>' + (s && s.st === 'done' ? I.check : '') : '<b>Rest</b>') + '</button>';
    });
    html += '<div class="aph-run-tot" title="' + dTxt(t.done) + ' of ' + dTxt(t.plan) + ' ' + U() + ' done"><span>' + dTxt(t.plan) + '</span><i style="--d:' + (t.plan ? Math.min(1, t.done / t.plan).toFixed(3) : 0) + '"></i></div></div>';
  });
  body.innerHTML = html + '</div>';
  St.moved = null;
}
function renderLoad(body) {
  const W = 520, H = 210, pl = 30, pr = 8, pt = 10, pb = 24;
  const rows = PLAN.map((wk, i) => ({ i, ...weekTotals(i), long: dist(wk.days[6]) }));
  const max = Math.ceil(Math.max(...rows.map(r => ud(r.plan))) / 10) * 10;
  const bw = (W - pl - pr) / 12, Y = v => pt + (H - pt - pb) * (1 - ud(v) / max);
  const lines = [0, max / 2, max].map(v => '<line class="aph-run-gl" x1="' + pl + '" x2="' + (W - pr) + '" y1="' + (pt + (H - pt - pb) * (1 - v / max)) + '" y2="' + (pt + (H - pt - pb) * (1 - v / max)) + '"/><text x="' + (pl - 6) + '" y="' + (pt + (H - pt - pb) * (1 - v / max) + 3) + '" text-anchor="end">' + v + '</text>').join('');
  const bars = rows.map(r => { const x = pl + r.i * bw + bw * 0.18, w = bw * 0.64; return '<rect class="aph-run-bp" x="' + x.toFixed(1) + '" y="' + Y(r.plan).toFixed(1) + '" width="' + w.toFixed(1) + '" height="' + (H - pb - Y(r.plan)).toFixed(1) + '" rx="3"/>' + (r.done ? '<rect class="aph-run-bd" style="--i:' + r.i + '" x="' + x.toFixed(1) + '" y="' + Y(r.done).toFixed(1) + '" width="' + w.toFixed(1) + '" height="' + (H - pb - Y(r.done)).toFixed(1) + '" rx="3"/>' : '') + '<text x="' + (x + w / 2).toFixed(1) + '" y="' + (H - 8) + '" text-anchor="middle">' + (r.i + 1) + '</text>'; }).join('');
  const lp = rows.map(r => [pl + r.i * bw + bw / 2, Y(r.long)]);
  const nowX = pl + wkOf(TODAY) * bw + bw / 2;
  const tot = rows.reduce((a, r) => ({ plan: a.plan + r.plan, done: a.done + r.done, t: a.t + r.t }), { plan: 0, done: 0, t: 0 });
  body.innerHTML = '<div class="aph-run-load"><svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Weekly ' + U() + ', planned and done, with the long run as a line">' + lines + bars +
    '<line class="aph-run-now" x1="' + nowX + '" x2="' + nowX + '" y1="' + pt + '" y2="' + (H - pb) + '"/>' +
    '<path class="aph-run-ll" d="' + lp.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' ') + '"/>' + lp.map(p => '<circle class="aph-run-lp" cx="' + p[0].toFixed(1) + '" cy="' + p[1].toFixed(1) + '" r="3"/>').join('') + '</svg>' +
    '<p>Grey bars are planned ' + U() + ', volt is what you have logged, the blue line is each week’s long run. Times use your ' + hms(St.goal) + ' paces.</p>' +
    '<table><thead><tr><th>Week</th><th>Planned</th><th>Done</th><th>Long</th><th>Time</th></tr></thead><tbody>' +
    rows.map(r => '<tr><td>W' + (r.i + 1) + ' · ' + PLAN[r.i].ph + '</td><td>' + dTxt(r.plan) + '</td><td>' + (r.done ? dTxt(r.done) : '–') + '</td><td>' + dTxt(r.long) + '</td><td>' + hms(r.t) + '</td></tr>').join('') +
    '</tbody><tfoot><tr><td>Total</td><td>' + dTxt(tot.plan) + '</td><td>' + dTxt(tot.done) + '</td><td></td><td>' + hms(tot.t) + '</td></tr></tfoot></table></div>';
}

function segRows(w) {
  const out = [];
  w.segs.forEach(s => {
    if (s.n && s.rec) { for (let k = 0; k < s.n; k++) { out.push({ z: s.z, d: s.each }); if (k < s.n - 1) out.push({ z: 'J', d: s.rec, low: true }); } }
