}
function renderDetail() {
  const n = St.sel, w = work(n), s = status(w), box = $('[data-detail]');
  if (!w) {
    const wi = wkOf(n), t = weekTotals(wi);
    box.innerHTML = '<div class="aph-run-dtop"><span class="aph-run-badge" style="--z:var(--aph-run-line2);color:var(--aph-run-ink)">Rest</span><span>' + fmtD(n) + (n === TODAY ? ' · today' : '') + '</span></div><h2>Rest day</h2><p class="aph-run-why">Sleep, walk, eat well. Rest is where the training lands. Nothing to log.</p>' +
      '<div class="aph-run-kpis"><div><small>Week ' + (wi + 1) + '</small><b>' + dTxt(t.plan) + '</b></div><div><small>Logged</small><b>' + dTxt(t.done) + '</b></div><div><small>Week time</small><b>' + hms(t.t) + '</b></div></div>';
    return;
  }
