/* Nightbook: a sleep diary. Each night is drawn on a 24-hour dial; the rail
   on the right only ever reports what the diary itself shows. */

.aph-sleep {
  /* re-theme: bg, ink, accent (amber), rose */
  --aph-sleep-bg: oklch(0.175 0.014 48);
  --aph-sleep-ink: oklch(0.93 0.025 80);
  --aph-sleep-accent: oklch(0.8 0.13 72);
  --aph-sleep-rose: oklch(0.72 0.1 22);
  --aph-sleep-panel: color-mix(in oklab, var(--aph-sleep-bg) 94%, var(--aph-sleep-ink));
  --aph-sleep-raise: color-mix(in oklab, var(--aph-sleep-bg) 87%, var(--aph-sleep-ink));
  --aph-sleep-sunk: color-mix(in oklab, var(--aph-sleep-bg) 78%, black);
  --aph-sleep-line: color-mix(in oklab, var(--aph-sleep-ink) 10%, transparent);
  --aph-sleep-line2: color-mix(in oklab, var(--aph-sleep-ink) 18%, transparent);
  --aph-sleep-mute: color-mix(in oklab, var(--aph-sleep-ink) 60%, var(--aph-sleep-bg));
  --aph-sleep-faint: color-mix(in oklab, var(--aph-sleep-ink) 36%, var(--aph-sleep-bg));
  --aph-sleep-glow: color-mix(in oklab, var(--aph-sleep-accent) 22%, transparent);
  --aph-sleep-on: color-mix(in oklab, var(--aph-sleep-accent) 14%, black);
  --aph-sleep-ease: cubic-bezier(.2, .8, .2, 1);
  --aph-sleep-slow: cubic-bezier(.45, 0, .2, 1);
  --aph-sleep-spring: linear(0, 0.1 4%, 0.38 10%, 0.75 17%, 0.98 24%, 1.06 30%, 1.06 36%, 1.02 46%, 0.995 60%, 1);

  position: relative; width: 100%; height: var(--aph-sleep-h, 680px);
  container-type: inline-size; container-name: aph-sleep; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: radial-gradient(120% 70% at 50% -10%, color-mix(in oklab, var(--aph-sleep-accent) 7%, transparent), transparent 60%), var(--aph-sleep-bg);
  color: var(--aph-sleep-ink); color-scheme: dark; accent-color: var(--aph-sleep-accent);
  border-radius: 14px; font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--aph-sleep-accent); outline-offset: 2px; border-radius: 6px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button[aria-disabled="true"] { cursor: not-allowed; opacity: .4; }
  & h2, & h3, & h4, & p, & ul, & ol, & dl, & dd, & dt { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & h2, & h3 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; display: inline-block; text-align: center; border: 1px solid var(--aph-sleep-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--aph-sleep-mute); }
  & [hidden] { display: none !important; }
}
.aph-sleep .aph-sleep-app {
  height: 100%; display: grid; grid-template-columns: 268px minmax(0, 1fr) 300px; grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "nights edit ins" "tabs tabs tabs";
}

/* ── nights ── */
.aph-sleep .aph-sleep-nights {
  grid-area: nights; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto auto minmax(0, 1fr); min-height: 0; min-width: 0;
  border-right: 1px solid var(--aph-sleep-line); background: color-mix(in oklab, var(--aph-sleep-sunk) 70%, transparent);
}
.aph-sleep .aph-sleep-brand {
  display: flex; align-items: center; gap: 8px; padding: 16px 16px 12px;
  & svg { color: var(--aph-sleep-accent); width: 22px; height: 22px; }
  & b { font-weight: 650; letter-spacing: .01em; font-size: 15px; }
  & span { margin-left: auto; font-size: 11.5px; color: var(--aph-sleep-mute); }
}
.aph-sleep .aph-sleep-filter {
  display: flex; gap: 3px; margin: 0 12px 8px; padding: 3px; border-radius: 10px; background: var(--aph-sleep-panel); border: 1px solid var(--aph-sleep-line);
  & button { flex: 1; height: 26px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--aph-sleep-mute); white-space: nowrap; transition: background .2s, color .2s; }
  & button[aria-selected="true"] { background: var(--aph-sleep-raise); color: var(--aph-sleep-ink); }
