.aph-sleep .aph-sleep-axis {
  display: flex; justify-content: space-between; margin: 0 16px 0 96px; padding-bottom: 4px; font: 600 9px/1 ui-monospace, Menlo, monospace; color: var(--aph-sleep-faint); border-bottom: 1px solid var(--aph-sleep-line);
