  ['nap', 'Afternoon nap', '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 18h16M6 18v-5a3 3 0 0 1 3-3h6a3 3 0 0 1 3 3v5M15 3h4l-4 4h4"/></svg>'],
