/* ── a month of nights, seeded; each night is keyed by the evening's date ── */
const FIRST = dn(2026, 8, 2), LAST = dn(2026, 9, 1);
const NIGHTS = {};
(function seed() {
  let s = 11; const r = () => { s = (s * 16807) % 2147483647; return s / 2147483647; };
  const g = () => (r() + r() + r() - 1.5) * 1.15;
  for (let n = FIRST; n < LAST; n++) {
    const wk = wd(n) === 4 || wd(n) === 5;
    const t = new Set();
    if (r() < 0.3) t.add('caf'); if (r() < (wk ? 0.55 : 0.14)) t.add('alc'); if (r() < 0.2) t.add('meal');
    if (!wk && r() < 0.5) t.add('ex'); if (r() < 0.33) t.add('scr'); if (!wk && r() < 0.25) t.add('str'); if (r() < (wk ? 0.3 : 0.08)) t.add('nap');
    const bed = Math.round((680 + g() * 22 + (wk ? 55 : 0) + (t.has('scr') ? 22 : 0)) / 5) * 5;
    const wake = Math.round((1145 + g() * 14 + (wk ? 70 : 0)) / 5) * 5;
    const lat = Math.max(4, Math.round(11 + (t.has('caf') ? 17 : 0) + (t.has('meal') ? 9 : 0) + (t.has('scr') ? 8 : 0) + (t.has('nap') ? 13 : 0) - (t.has('ex') ? 5 : 0) + r() * 7));
    const awake = Math.round(7 + (t.has('alc') ? 23 : 0) + (t.has('str') ? 14 : 0) + r() * 9);
    const asleep = wake - bed - lat - awake;
    const rating = clamp(Math.round(3.4 - (t.has('alc') ? 0.9 : 0) - (t.has('str') ? 0.8 : 0) - (t.has('caf') ? 0.4 : 0) + (t.has('ex') ? 0.5 : 0) + (asleep - 420) / 60 * 0.7 + g() * 0.5), 1, 5);
    NIGHTS[n] = { bed, wake, lat, awake, rating, tags: [...t], note: '' };
  }
  NIGHTS[dn(2026, 8, 25)].note = 'Neighbour’s party until 1. Earplugs helped.';
  NIGHTS[dn(2026, 8, 29)].note = 'Deadline day — mind racing.';
})();
const ALL = []; for (let n = LAST; n >= FIRST; n--) ALL.push(n);

/* ── state ── */
const S = { sel: LAST, drafts: {}, filter: 'all', fact: null, range: 14, view: 'edit' };
const rec = n => NIGHTS[n] || null;
const blankFor = n => ({ bed: 685, wake: 1140, lat: 15, awake: 10, rating: 0, tags: [], note: '' });
const cur = n => S.drafts[n] || rec(n) || blankFor(n);
const asleepOf = v => Math.max(0, v.wake - v.bed - v.lat - v.awake);
const isDirty = n => !!S.drafts[n];
function edit(fn) {
  const n = S.sel, base = cur(n), d = JSON.parse(JSON.stringify(base));
  fn(d);
  S.drafts[n] = d;
}

/* ── undo & toast ── */
const undoStack = [];
function remember() { undoStack.push(JSON.stringify({ nights: NIGHTS, drafts: S.drafts })); if (undoStack.length > 30) undoStack.shift(); }
function undo() {
  const v = undoStack.pop(); if (!v) { toast('Nothing to undo'); return; }
  const o = JSON.parse(v); Object.keys(NIGHTS).forEach(k => delete NIGHTS[k]); Object.assign(NIGHTS, o.nights); S.drafts = o.drafts;
  render(); toast('Undone');
}
let toastT = 0;
function toast(msg, withUndo) {
  const t = $('[data-toast]');
  t.innerHTML = '<span>' + msg + '</span>' + (withUndo ? '<button type="button" data-act="undo">Undo <kbd>⌘Z</kbd></button>' : '');
  clearTimeout(toastT); toastT = setTimeout(() => { if (root.isConnected) t.innerHTML = ''; }, withUndo ? 6000 : 3500);
}

/* ── render ── */
function keepFocus(fn) {
  const a = doc.activeElement, k = a && root.contains(a) && a.dataset ? a.dataset.k : null;
  fn();
  if (k) { const el = root.querySelector('[data-k="' + k + '"]'); if (el && el !== doc.activeElement) el.focus({ preventScroll: true }); }
}
function render() { keepFocus(() => { renderList(); renderEdit(); renderIns(); renderTabs(); }); }
const AX0 = 480, AXW = 960; /* the list axis runs 20:00 → 12:00 */

function visibleNights() {
  return ALL.filter(n => {
    const wk = wd(n) === 4 || wd(n) === 5;
    if (S.filter === 'week' && wk) return false;
    if (S.filter === 'wkend' && !wk) return false;
    if (S.fact) { const r = rec(n); if (!r || !r.tags.includes(S.fact)) return false; }
    return true;
  });
}
function renderList() {
  $('[data-filter]').innerHTML = [['all', 'All'], ['week', 'Weeknights'], ['wkend', 'Weekends']].map(([k, l]) => '<button type="button" role="tab" aria-selected="' + (S.filter === k) + '" data-filt="' + k + '" data-k="f-' + k + '">' + l + '</button>').join('');
  const list = visibleNights();
  $('[data-list]').innerHTML = (S.fact ? '<div class="aph-sleep-fhint"><span>' + list.length + ' nights with <b>' + TAG[S.fact][1].toLowerCase() + '</b></span><button type="button" data-act="clear-fact">Show all</button></div>' : '') +
    list.map(n => {
      const r = rec(n), v = cur(n), open = !r && !isDirty(n), as = asleepOf(v);
      return '<button type="button" role="option" class="aph-sleep-night' + (open ? ' is-open' : '') + (isDirty(n) ? ' is-draft' : '') + (S.saved === n ? ' is-saved' : '') + '" aria-selected="' + (n === S.sel) + '" tabindex="' + (n === S.sel ? 0 : -1) + '" data-night="' + n + '" data-k="n' + n + '" aria-label="' + esc('Night of ' + dShort(n) + (open ? ', not logged' : ', ' + dur(as) + ' asleep, ' + clock(v.bed) + ' to ' + clock(v.wake))) + '">' +
        '<span class="aph-sleep-nd">' + WD[wd(n)] + ' ' + ymd(n)[2] + '<small>' + (open ? '—' : dur(as)) + '</small></span>' +
        '<span class="aph-sleep-track">' + (open ? '' : '<i class="aph-sleep-win" style="--a:' + ((v.bed - AX0) / AXW).toFixed(4) + ';--w:' + ((v.wake - v.bed) / AXW).toFixed(4) + ';--l:' + (v.lat / (v.wake - v.bed)).toFixed(3) + '"></i>') + '</span>' +
        '<span class="aph-sleep-dots">' + (open ? '' : [1, 2, 3, 4, 5].map(k => '<i class="' + (k <= v.rating ? 'is-on' : '') + '"></i>').join('') + '<em>' + v.tags.map(t => TAG[t][1].split(' ')[0].toLowerCase()).slice(0, 2).join(' · ') + '</em>') + '</span></button>';
    }).join('');
  S.saved = null;
}

/* the 24-hour dial: 0:00 at the top, clockwise */
const CX = 150, CY = 150, RR = 118;
const ang = m => (((m + 720) % 1440) / 1440) * Math.PI * 2 - Math.PI / 2;
const pt = (m, r) => [CX + r * Math.cos(ang(m)), CY + r * Math.sin(ang(m))];
function arc(m1, m2, r) {
  if (m2 <= m1) return '';
  const [x1, y1] = pt(m1, r), [x2, y2] = pt(m2, r), large = (m2 - m1) > 720 ? 1 : 0;
  return 'M' + x1.toFixed(2) + ' ' + y1.toFixed(2) + ' A' + r + ' ' + r + ' 0 ' + large + ' 1 ' + x2.toFixed(2) + ' ' + y2.toFixed(2);
}
function dialSvg(v) {
  let ticks = '';
  for (let h = 0; h < 24; h++) {
    const m = (h * 60 + 720) % 1440, [x1, y1] = pt(m, RR + 16), [x2, y2] = pt(m, RR + (h % 6 ? 21 : 25));
    ticks += '<line class="aph-sleep-tick' + (h % 6 ? '' : ' is-major') + '" x1="' + x1.toFixed(1) + '" y1="' + y1.toFixed(1) + '" x2="' + x2.toFixed(1) + '" y2="' + y2.toFixed(1) + '"/>';
    if (h % 3 === 0) { const [lx, ly] = pt(m, RR + 37); ticks += '<text class="aph-sleep-lbl" x="' + lx.toFixed(1) + '" y="' + (ly + 3.5).toFixed(1) + '" text-anchor="middle">' + String(h).padStart(2, '0') + '</text>'; }
  }
  const lat = v.bed + v.lat, sleepEnd = v.wake - v.awake;
  const [bx, by] = pt(v.bed, RR), [wx, wy] = pt(v.wake, RR);
  return '<svg viewBox="-10 -10 320 320" aria-hidden="false" role="group" aria-label="Sleep window on a 24-hour clock">' +
    '<path class="aph-sleep-target" d="' + arc(660, 1140, RR) + '"><title>Target window 23:00 – 07:00</title></path>' +
    '<circle class="aph-sleep-ring" cx="' + CX + '" cy="' + CY + '" r="' + RR + '"/>' + ticks +
    '<path class="aph-sleep-bedarc" d="' + arc(v.bed, v.wake, RR) + '"/>' +
    '<path class="aph-sleep-latarc" d="' + arc(v.bed + 2, lat, RR - 26) + '"/>' +
    '<path class="aph-sleep-sleeparc" d="' + arc(lat + 4, sleepEnd - 2, RR - 26) + '"/>' +
    '<path class="aph-sleep-awakearc" d="' + arc(sleepEnd + 2, v.wake - 1, RR - 26) + '"/>' +
    '<g class="aph-sleep-handle" data-h="bed" tabindex="0" role="slider" aria-label="Bedtime" aria-valuemin="420" aria-valuemax="960" aria-valuenow="' + v.bed + '" aria-valuetext="' + clock(v.bed) + '" transform="translate(' + bx.toFixed(1) + ' ' + by.toFixed(1) + ')"><circle r="15"/><path d="M4.2 2.4A5.6 5.6 0 0 1-2.4-4.2 5.6 5.6 0 1 0 4.2 2.4Z"/></g>' +
    '<g class="aph-sleep-handle" data-h="wake" tabindex="0" role="slider" aria-label="Wake time" aria-valuemin="900" aria-valuemax="1440" aria-valuenow="' + v.wake + '" aria-valuetext="' + clock(v.wake) + '" transform="translate(' + wx.toFixed(1) + ' ' + wy.toFixed(1) + ')"><circle r="15"/><circle r="3.2" style="fill:none;stroke:var(--aph-sleep-bg);stroke-width:1.6"/><path d="M0-6.5v1.6M0 4.9v1.6M-6.5 0h1.6M4.9 0h1.6M-4.6-4.6l1.1 1.1M3.5 3.5l1.1 1.1M-4.6 4.6l1.1-1.1M3.5-3.5l1.1-1.1"/></g>' +
    '</svg>';
}
function renderEdit() {
  const n = S.sel, v = cur(n), r = rec(n), dirty = isDirty(n), inBed = v.wake - v.bed, as = asleepOf(v), eff = inBed ? as / inBed : 0;
  const box = $('[data-edit]');
  const head = '<header class="aph-sleep-ehead"><div class="aph-sleep-et"><small>' + (n === LAST ? 'Last night' : (LAST - n) + ' nights ago') + '</small><h2>' + (dirty ? '<span class="aph-sleep-dirty" title="Unsaved changes"></span>' : '') + 'Night of <b>' + dShort(n) + '</b></h2></div>' +
    '<div class="aph-sleep-acts"><button type="button" class="aph-sleep-btn" data-act="revert" data-k="revert"' + (dirty ? '' : ' aria-disabled="true" title="No unsaved changes"') + '>' + I.back + 'Revert</button>' +
    '<button type="button" class="aph-sleep-btn is-primary" data-act="save" data-k="save"' + (dirty ? '' : ' aria-disabled="true" title="' + (r ? 'Saved — change something to save again' : 'Set the times or a rating first') + '"') + '>' + I.check + (r ? 'Save' : 'Log night') + ' <kbd>⌘S</kbd></button></div></header>';
  /* the dial keeps its element so dragging never loses the pointer; only its content updates */
  let dial = $('.aph-sleep-dial', box);
  if (!dial || box.dataset.n !== String(n)) {
    box.dataset.n = n;
    box.innerHTML = '<div data-head></div><div class="aph-sleep-ebody"><div class="aph-sleep-dial" data-dial></div><div class="aph-sleep-fields" data-fields></div></div><div class="aph-sleep-tags" data-tagbox></div><label class="aph-sleep-notes"><small>Notes</small><textarea data-note data-k="note" placeholder="Anything worth remembering about the night"></textarea></label>';
    dial = $('.aph-sleep-dial', box);
    $('[data-note]', box).value = v.note;
  }
  $('[data-head]', box).innerHTML = head;
  const keep = doc.activeElement && doc.activeElement.dataset && doc.activeElement.dataset.h;
  dial.innerHTML = dialSvg(v) + '<div class="aph-sleep-face"><small>Asleep</small><output aria-live="polite"><b>' + Math.floor(as / 60) + '</b>h ' + String(as % 60).padStart(2, '0') + 'm</output><span>' + dur(inBed) + ' in bed · ' + Math.round(eff * 100) + '%</span></div>';
  if (keep && !dragH) { const h = $('[data-h="' + keep + '"]', dial); if (h) h.focus({ preventScroll: true }); }
  if (dragH) { const h = $('[data-h="' + dragH + '"]', dial); if (h) h.classList.add('is-drag'); }
  $('[data-fields]', box).innerHTML =
    '<div class="aph-sleep-times"><div><small>' + I.moon + 'Bed</small><b>' + clock(v.bed) + '</b></div><div><small>' + I.sun + 'Up</small><b>' + clock(v.wake) + '</b></div></div>' +
    stepRow('lat', 'To fall asleep', 'lying awake at first', v.lat, 0, 120) + stepRow('awake', 'Awake at night', 'all wake-ups', v.awake, 0, 180) +
    '<div class="aph-sleep-rate"><small>How rested? <kbd>1</kbd>–<kbd>5</kbd></small><div role="radiogroup" aria-label="How rested">' + RATES.map((l, i) => '<button type="button" role="radio" aria-checked="' + (v.rating === i + 1) + '" data-rate="' + (i + 1) + '" data-k="rate' + (i + 1) + '"><b>' + (i + 1) + '</b>' + l + '</button>').join('') + '</div></div>';
  $('[data-tagbox]', box).innerHTML = '<small>What happened that day</small><div>' + TAGS.map(([k, l, ic]) => '<button type="button" aria-pressed="' + v.tags.includes(k) + '" data-tag="' + k + '" data-k="tag-' + k + '">' + ic + l + '</button>').join('') + '</div>';
  const note = $('[data-note]', box); if (doc.activeElement !== note && note.value !== v.note) note.value = v.note;
}
function stepRow(k, l, sub, v, lo, hi) {
  return '<div class="aph-sleep-step"><span>' + l + '<small>' + sub + '</small></span><div><button type="button" data-step="' + k + '" data-d="-5" data-k="' + k + '-" aria-label="' + l + ', 5 minutes less"' + (v <= lo ? ' aria-disabled="true" title="Already zero"' : '') + '>' + I.minus + '</button><output>' + v + ' min</output><button type="button" data-step="' + k + '" data-d="5" data-k="' + k + '+" aria-label="' + l + ', 5 minutes more"' + (v >= hi ? ' aria-disabled="true" title="That is the upper limit"' : '') + '>' + I.plus + '</button></div></div>';
}

function stats(nights) {
  const L = nights.map(n => ({ n, v: rec(n) })).filter(x => x.v);
  if (!L.length) return null;
  const mean = a => a.reduce((s, x) => s + x, 0) / a.length;
  const beds = L.map(x => x.v.bed), as = L.map(x => asleepOf(x.v));
  const mb = mean(beds), sd = Math.sqrt(mean(beds.map(b => (b - mb) ** 2)));
  return { L, bed: mb, sd, wake: mean(L.map(x => x.v.wake)), asleep: mean(as), eff: mean(L.map(x => asleepOf(x.v) / (x.v.wake - x.v.bed))), under7: as.filter(a => a < 420).length };
}
function renderIns() {
  const nights = ALL.slice(0, S.range + 1).filter(n => n !== LAST || rec(n)).slice(0, S.range);
  const st = stats(nights), box = $('[data-ins]');
  if (!st) { box.innerHTML = '<p>No nights logged yet.</p>'; return; }
  const W = 268, rowH = S.range > 20 ? 7 : 11, pad = 18, H = pad + st.L.length * rowH + 4;
  const X = m => (m - 540) / 840 * W;   /* 21:00 → 11:00 */
  const rows = st.L.slice().reverse().map((x, i) => { const v = x.v, y = pad + i * rowH, h = rowH - 3, lat = v.bed + v.lat; return '<rect class="aph-sleep-b is-lat" style="--i:' + i + '" x="' + X(v.bed).toFixed(1) + '" y="' + y + '" width="' + (X(lat) - X(v.bed)).toFixed(1) + '" height="' + h + '" rx="1.5"/><rect class="aph-sleep-b' + (x.n === S.sel ? ' is-sel' : '') + '" style="--i:' + i + '" x="' + X(lat).toFixed(1) + '" y="' + y + '" width="' + (X(v.wake) - X(lat)).toFixed(1) + '" height="' + h + '" rx="1.5"><title>' + dShort(x.n) + ': ' + clock(v.bed) + '–' + clock(v.wake) + ', ' + dur(asleepOf(v)) + ' asleep</title></rect><circle class="aph-sleep-mid" cx="' + X((v.bed + v.wake) / 2).toFixed(1) + '" cy="' + (y + h / 2) + '" r="1.8"/>'; }).join('');
  const gl = [600, 780, 960, 1140, 1320].map(m => '<line class="aph-sleep-gl" x1="' + X(m) + '" x2="' + X(m) + '" y1="' + (pad - 4) + '" y2="' + H + '"/><text x="' + X(m) + '" y="9" text-anchor="middle">' + clock(m) + '</text>').join('');
  /* tags: average asleep with vs without, inside the same window */
  const facts = TAGS.map(([k, l]) => {
    const w = st.L.filter(x => x.v.tags.includes(k)), wo = st.L.filter(x => !x.v.tags.includes(k));
    if (w.length < 2 || wo.length < 2) return null;
    const a = w.reduce((s, x) => s + asleepOf(x.v), 0) / w.length, b = wo.reduce((s, x) => s + asleepOf(x.v), 0) / wo.length;
    return { k, l, a, b, nw: w.length, nwo: wo.length, d: a - b };
  }).filter(Boolean).sort((p, q) => Math.abs(q.d) - Math.abs(p.d));
  const mx = Math.max(...facts.map(f => Math.max(f.a, f.b)), 1);
  box.innerHTML = '<section><h3>Last ' + S.range + ' nights<span class="aph-sleep-range" role="tablist" aria-label="Range">' + [14, 30].map(r => '<button type="button" role="tab" aria-selected="' + (S.range === r) + '" data-range="' + r + '" data-k="r' + r + '">' + r + '</button>').join('') + '</span></h3>' +
    '<div class="aph-sleep-avgs"><div><small>Asleep</small><b>' + dur(st.asleep) + '</b><span>' + st.under7 + ' of ' + st.L.length + ' under 7 h</span></div><div><small>Bedtime</small><b>' + clock(st.bed) + '</b><span>± ' + Math.round(st.sd) + ' min</span></div><div><small>Efficiency</small><b>' + Math.round(st.eff * 100) + '%</b><span>asleep ÷ in bed</span></div></div></section>' +
    '<section><h3>Sleep window</h3><svg class="aph-sleep-chart" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Bed to wake for each of the last ' + st.L.length + ' logged nights, oldest at the top">' +
      '<rect class="aph-sleep-band" x="' + X(660) + '" y="' + (pad - 4) + '" width="' + (X(1140) - X(660)) + '" height="' + (H - pad + 4) + '" rx="3"/>' + gl + rows + '</svg>' +
      '<footer style="margin-top:6px">Shaded: the 23:00–07:00 target. Rose: time to fall asleep. Dots: mid-sleep.</footer></section>' +
    '<section><h3>Tags and time asleep</h3><div class="aph-sleep-facts">' + (facts.length ? facts.map(f => '<button type="button" class="aph-sleep-fact" aria-pressed="' + (S.fact === f.k) + '" data-fact="' + f.k + '" data-k="fact-' + f.k + '"><b>' + esc(f.l) + '</b><em class="' + (f.d < -5 ? 'is-neg' : f.d > 5 ? 'is-pos' : '') + '">' + (f.d >= 0 ? '+' : '−') + Math.abs(Math.round(f.d)) + ' min</em>' +
      '<span class="aph-sleep-cmp"><i style="--v:' + (f.a / mx).toFixed(3) + '"></i><i style="--v:' + (f.b / mx).toFixed(3) + '"></i></span><small>' + dur(f.a) + ' with (' + f.nw + ') · ' + dur(f.b) + ' without (' + f.nwo + ')</small></button>').join('') : '<p style="color:var(--aph-sleep-mute)">Tag a few more nights to see patterns.</p>') + '</div></section>' +
    '<footer>Patterns in your own diary, not medical advice. Click a tag to list its nights.</footer>';
}
function renderTabs() { $$('[data-view-to]').forEach(b => b.setAttribute('aria-current', b.dataset.viewTo === S.view ? 'page' : 'false')); root.dataset.view = S.view; }
function setView(v) { const w = root.clientWidth; if (v === 'list' && w >= 760) v = 'edit'; if (v === 'ins' && w >= 960) v = 'edit'; S.view = v; renderTabs(); }

/* ── actions ── */
function select(n, focus) {
  S.sel = n; render();
  if (focus) { const el = root.querySelector('[data-k="n' + n + '"]'); if (el) el.focus({ preventScroll: true }); }
}
function save() {
  const n = S.sel; if (!isDirty(n)) return;
  const v = S.drafts[n];
  if (!v.rating) { toast('Pick how rested you felt (1–5) before logging'); const b = root.querySelector('[data-rate="3"]'); if (b) b.focus(); return; }
  remember();
  const was = !!rec(n); NIGHTS[n] = v; delete S.drafts[n]; S.saved = n;
  render(); toast((was ? 'Saved ' : 'Logged ') + dShort(n) + ' · ' + dur(asleepOf(v)) + ' asleep', true);
}
function revert() { const n = S.sel; if (!isDirty(n)) return; remember(); delete S.drafts[n]; render(); toast('Changes to ' + dShort(n) + ' discarded', true); }
function setTime(h, m) {
  edit(d => {
    if (h === 'bed') d.bed = clamp(Math.round(m / 5) * 5, Math.max(420, d.wake - 840), Math.min(960, d.wake - 120));
    else d.wake = clamp(Math.round(m / 5) * 5, Math.max(900, d.bed + 120), Math.min(1440, d.bed + 840));
    const room = d.wake - d.bed; d.lat = Math.min(d.lat, room - 30); d.awake = Math.min(d.awake, room - d.lat - 30);
  });
  renderEdit(); renderList();
}

/* dragging the dial handles: angle from the dial's centre → minutes, snapped to 5 */
let dragH = null;
function minutesAt(e) {
  const svg = $('[data-dial] svg'), b = svg.getBoundingClientRect(), s = b.width / 320;
  const cx = b.left + (CX + 10) * s, cy = b.top + (CY + 10) * s;
  let a = Math.atan2(e.clientY - cy, e.clientX - cx) + Math.PI / 2; if (a < 0) a += Math.PI * 2;
  const mod = a / (Math.PI * 2) * 1440;
