}
root.addEventListener('pointerdown', e => {
  const h = e.target.closest('[data-h]'); if (!h || e.button !== 0) return;
  dragH = h.dataset.h; e.preventDefault(); h.focus({ preventScroll: true }); h.classList.add('is-drag');
  try { root.setPointerCapture(e.pointerId); } catch (err) {}
});
root.addEventListener('pointermove', e => {
  if (!dragH) return;
