  if (dragH === 'wake' && m < 300) m += 1440; /* past noon the wake handle keeps going */
  if (Math.abs(m - (dragH === 'bed' ? v.bed : v.wake)) < 2.5) return;
  setTime(dragH, m);
});
function endDrag() { if (!dragH) return; dragH = null; renderEdit(); renderIns(); }
root.addEventListener('pointerup', endDrag);
root.addEventListener('pointercancel', endDrag);

root.addEventListener('click', e => {
  const t = e.target.closest('button'); if (!t || !root.contains(t)) return;
