/* Stillwell: a meditation timer whose ring is the timeline. */

.aph-breathe {
  /* re-theme: paper, ink, accent (sage), bronze */
  --aph-breathe-paper: oklch(0.955 0.012 85);
  --aph-breathe-ink: oklch(0.3 0.022 150);
  --aph-breathe-accent: oklch(0.58 0.07 150);
  --aph-breathe-bronze: oklch(0.62 0.1 65);
  --aph-breathe-card: color-mix(in oklab, var(--aph-breathe-paper) 45%, white);
  --aph-breathe-sunk: color-mix(in oklab, var(--aph-breathe-paper) 93%, var(--aph-breathe-ink));
  --aph-breathe-line: color-mix(in oklab, var(--aph-breathe-ink) 11%, transparent);
  --aph-breathe-line2: color-mix(in oklab, var(--aph-breathe-ink) 20%, transparent);
  --aph-breathe-mute: color-mix(in oklab, var(--aph-breathe-ink) 62%, var(--aph-breathe-paper));
  --aph-breathe-faint: color-mix(in oklab, var(--aph-breathe-ink) 40%, var(--aph-breathe-paper));
  --aph-breathe-mist: color-mix(in oklab, var(--aph-breathe-accent) 14%, var(--aph-breathe-paper));
  --aph-breathe-ease: cubic-bezier(.2, .8, .2, 1);
  --aph-breathe-calm: cubic-bezier(.45, .05, .25, 1);
  --aph-breathe-spring: linear(0, 0.1 4%, 0.38 10%, 0.75 17%, 0.98 24%, 1.06 30%, 1.06 36%, 1.02 46%, 0.995 60%, 1);

  position: relative; width: 100%; height: var(--aph-breathe-h, 680px);
  container-type: inline-size; container-name: aph-breathe; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--aph-breathe-paper); color: var(--aph-breathe-ink); color-scheme: light; accent-color: var(--aph-breathe-accent);
  border-radius: 14px; font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--aph-breathe-accent); outline-offset: 2px; border-radius: 6px; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button[aria-disabled="true"] { cursor: not-allowed; opacity: .4; }
  & h2, & h3, & h4, & p, & ul, & ol { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & h2, & h3 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; display: inline-block; text-align: center; border: 1px solid var(--aph-breathe-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--aph-breathe-mute); background: var(--aph-breathe-card); }
  & [hidden] { display: none !important; }
}
.aph-breathe .aph-breathe-app {
  height: 100%; display: grid; grid-template-columns: 250px minmax(0, 1fr) 292px; grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "side stage bells" "tabs tabs tabs";
}
.aph-breathe .aph-breathe-h { font-size: 10.5px; text-transform: uppercase; letter-spacing: .14em; color: var(--aph-breathe-faint); font-weight: 700; }

/* ── side ── */
.aph-breathe .aph-breathe-side {
  grid-area: side; overflow: auto; overscroll-behavior: contain; display: grid; grid-template-columns: minmax(0, 1fr); align-content: start; gap: 10px; padding: 16px 12px 16px; min-width: 0;
  background: var(--aph-breathe-sunk); border-right: 1px solid var(--aph-breathe-line); scrollbar-width: thin;
  & > .aph-breathe-h { padding: 6px 6px 0; }
}
.aph-breathe .aph-breathe-brand {
  display: flex; align-items: center; gap: 8px; padding: 0 6px 4px;
  & svg { width: 22px; height: 22px; color: var(--aph-breathe-bronze); }
  & b { font-weight: 600; font-size: 15px; letter-spacing: .02em; }
}
.aph-breathe .aph-breathe-presets { display: grid; gap: 2px; }
.aph-breathe .aph-breathe-preset {
  display: grid; grid-template-columns: 34px minmax(0, 1fr); gap: 1px 10px; align-items: center; text-align: left; padding: 8px; border-radius: 12px; transition: background .2s;
  & i { grid-row: span 2; width: 34px; height: 34px; border-radius: 50%; background: conic-gradient(var(--aph-breathe-accent) calc(var(--f) * 1turn), var(--aph-breathe-line) 0); mask: radial-gradient(farthest-side, transparent calc(100% - 4px), #000 calc(100% - 3.5px)); }
  & b { font-weight: 600; }
  & span { font-size: 11.5px; color: var(--aph-breathe-mute); font-variant-numeric: tabular-nums; }
  &:hover { background: color-mix(in oklab, var(--aph-breathe-paper) 60%, white); }
  &[aria-selected="true"] { background: var(--aph-breathe-card); box-shadow: 0 1px 0 var(--aph-breathe-line), 0 8px 20px -14px color-mix(in oklab, var(--aph-breathe-ink) 50%, transparent); }
}
.aph-breathe .aph-breathe-save {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 34px; border-radius: 10px; border: 1px dashed var(--aph-breathe-line2); font-size: 12.5px; font-weight: 600; color: var(--aph-breathe-mute);
  & svg { width: 15px; height: 15px; }
  &:hover { color: var(--aph-breathe-ink); border-style: solid; }
}
.aph-breathe .aph-breathe-week {
  margin-top: 6px; padding: 12px; border-radius: 14px; background: var(--aph-breathe-card); border: 1px solid var(--aph-breathe-line); display: grid; gap: 10px;
  & header { display: grid; gap: 4px; }
  & header div { display: flex; justify-content: space-between; align-items: baseline; }
  & header b { font: 300 22px/1 system-ui; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & header b small { font-size: 12px; color: var(--aph-breathe-mute); margin-left: 3px; font-weight: 500; }
  & header span { font-size: 11.5px; color: var(--aph-breathe-mute); }
  & .aph-breathe-days { display: grid; grid-template-columns: repeat(7, 1fr); gap: 5px; height: 70px; align-items: end; }
  & .aph-breathe-days div { display: grid; grid-template-rows: minmax(0, 1fr) auto; height: 100%; gap: 4px; text-align: center; }
  & .aph-breathe-days i { align-self: end; height: 100%; border-radius: 4px; background: var(--aph-breathe-accent); transform-origin: bottom; transform: scaleY(var(--v)); transition: transform .8s var(--aph-breathe-spring); }
  & .aph-breathe-days .is-zero i { background: var(--aph-breathe-line); transform: scaleY(.05); }
  & .aph-breathe-days .is-future i { background: transparent; border: 1px dashed var(--aph-breathe-line2); transform: none; height: 8px; }
  & .aph-breathe-days .is-today span { color: var(--aph-breathe-ink); font-weight: 750; }
  & .aph-breathe-days span { font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--aph-breathe-faint); }
}

/* ── stage ── */
.aph-breathe .aph-breathe-stage {
  grid-area: stage; position: relative; display: grid; grid-template-rows: minmax(0, 1fr) auto auto; justify-items: center; align-items: center; padding: 16px 20px 18px; min-height: 0; min-width: 0;
  background: radial-gradient(60% 55% at 50% 42%, var(--aph-breathe-mist), transparent 70%);
}
.aph-breathe .aph-breathe-ringwrap { position: relative; width: min(100%, 400px, 100cqi); aspect-ratio: 1; max-height: 100%; align-self: center; container-type: inline-size; }
.aph-breathe .aph-breathe-ring {
  width: 100%; height: 100%; display: block; overflow: visible;
  & .aph-breathe-track { fill: none; stroke: var(--aph-breathe-line); stroke-width: 10; }
  & .aph-breathe-tick { stroke: var(--aph-breathe-line2); stroke-width: 1.5; }
  & .aph-breathe-tlbl { font: 600 10px ui-monospace, Menlo, monospace; fill: var(--aph-breathe-faint); stroke: none; }
  & .aph-breathe-prog { fill: none; stroke: var(--aph-breathe-accent); stroke-width: 10; stroke-linecap: round; }
  & .aph-breathe-bell { cursor: grab; outline: none; touch-action: none; }
  & .aph-breathe-bell .aph-breathe-hit { fill: transparent; stroke: none; }
  & .aph-breathe-bell .aph-breathe-dot { fill: var(--aph-breathe-card); stroke: var(--aph-breathe-bronze); stroke-width: 2.5; transition: r .25s var(--aph-breathe-spring); }
  & .aph-breathe-bell path { stroke: var(--aph-breathe-bronze); stroke-width: 1.6; fill: none; pointer-events: none; }
  & .aph-breathe-bell .aph-breathe-ripple { fill: none; stroke: var(--aph-breathe-bronze); stroke-width: 2; opacity: 0; pointer-events: none; }
  & .aph-breathe-bell:hover .aph-breathe-dot, & .aph-breathe-bell:focus-visible .aph-breathe-dot { r: 15px; }
  & .aph-breathe-bell[aria-pressed="true"] .aph-breathe-dot { fill: var(--aph-breathe-bronze); }
  & .aph-breathe-bell[aria-pressed="true"] path { stroke: var(--aph-breathe-card); }
  & .aph-breathe-bell.is-past .aph-breathe-dot { stroke: var(--aph-breathe-faint); }
  & .aph-breathe-bell.is-past path { stroke: var(--aph-breathe-faint); }
  & .aph-breathe-bell.is-drag { cursor: grabbing; }
  & .aph-breathe-bell.is-ring .aph-breathe-ripple { animation: aph-breathe-ripple 1.6s var(--aph-breathe-calm) 3; }
  & .aph-breathe-bell:focus-visible .aph-breathe-dot { stroke: var(--aph-breathe-ink); }
  & .aph-breathe-sq { fill: none; stroke: var(--aph-breathe-line2); stroke-width: 1.5; stroke-dasharray: 3 5; }
  & .aph-breathe-pacer { fill: var(--aph-breathe-accent); }
  & .aph-breathe-orb { fill: var(--aph-breathe-mist); stroke: color-mix(in oklab, var(--aph-breathe-accent) 40%, transparent); stroke-width: 1.5; transform-origin: 200px 200px; transform-box: view-box; }
}
.aph-breathe .aph-breathe-face {
  position: absolute; inset: 30%; display: grid; place-content: center; text-align: center; pointer-events: none;
  & small { font-size: 10.5px; text-transform: uppercase; letter-spacing: .2em; color: var(--aph-breathe-mute); font-weight: 650; transition: opacity .4s; }
  & output { font: 200 clamp(38px, 15cqi, 64px)/1 system-ui, -apple-system, sans-serif; letter-spacing: -.04em; font-variant-numeric: tabular-nums; margin: 4px 0; }
  & span { font-size: 11.5px; color: var(--aph-breathe-faint); font-variant-numeric: tabular-nums; }
}
.aph-breathe[data-state="run"] .aph-breathe-face small { color: var(--aph-breathe-accent); }
.aph-breathe .aph-breathe-ctl { display: flex; align-items: center; gap: 12px; margin-top: 8px; }
.aph-breathe .aph-breathe-dur {
  display: inline-flex; align-items: center; gap: 2px; height: 44px; padding: 4px; border-radius: 99px; background: var(--aph-breathe-card); border: 1px solid var(--aph-breathe-line);
  & button { width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; transition: background .15s; }
  & button:hover { background: var(--aph-breathe-sunk); }
  & span { min-width: 64px; text-align: center; font-weight: 600; font-variant-numeric: tabular-nums; }
}
.aph-breathe .aph-breathe-go {
  display: inline-flex; align-items: center; gap: 8px; height: 50px; padding: 0 22px 0 18px; border-radius: 99px; background: var(--aph-breathe-ink); color: var(--aph-breathe-paper); font-weight: 650; font-size: 14px;
  box-shadow: 0 12px 30px -14px color-mix(in oklab, var(--aph-breathe-ink) 80%, transparent); transition: transform .2s var(--aph-breathe-spring), background .3s;
  & svg { width: 18px; height: 18px; }
  & svg path { fill: currentColor; stroke: currentColor; }
  & .aph-breathe-ipause path { fill: none; stroke-width: 2.6; }
  & .aph-breathe-ipause { display: none; }
  & kbd { background: transparent; color: color-mix(in oklab, var(--aph-breathe-paper) 65%, transparent); border-color: color-mix(in oklab, var(--aph-breathe-paper) 30%, transparent); }
  &:active { transform: scale(.95); }
}
.aph-breathe[data-state="run"] .aph-breathe-go { background: var(--aph-breathe-accent); }
.aph-breathe[data-state="run"] .aph-breathe-go .aph-breathe-iplay { display: none; }
.aph-breathe[data-state="run"] .aph-breathe-go .aph-breathe-ipause { display: block; }
.aph-breathe .aph-breathe-round { width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center; background: var(--aph-breathe-card); border: 1px solid var(--aph-breathe-line); transition: transform .3s var(--aph-breathe-spring); }
.aph-breathe .aph-breathe-round:active { transform: rotate(-90deg); }
.aph-breathe .aph-breathe-hint { margin-top: 10px; font-size: 11.5px; color: var(--aph-breathe-faint); display: flex; align-items: center; gap: 3px; flex-wrap: wrap; justify-content: center; }
.aph-breathe .aph-breathe-done {
  position: absolute; inset: auto 20px 20px; z-index: 5; margin: 0 auto; max-width: 420px; padding: 16px; border-radius: 18px; background: var(--aph-breathe-card); border: 1px solid var(--aph-breathe-line2);
  box-shadow: 0 24px 60px -24px color-mix(in oklab, var(--aph-breathe-ink) 60%, transparent); display: grid; gap: 10px;
  transition: opacity .3s, transform .5s var(--aph-breathe-spring); @starting-style { opacity: 0; transform: translateY(20px); }
  & h4 { font: 300 22px/1.1 system-ui; letter-spacing: -.02em; }
  & h4 b { font-weight: 600; }
  & p { font-size: 12.5px; color: var(--aph-breathe-mute); }
  & .aph-breathe-moods { display: flex; flex-wrap: wrap; gap: 6px; }
  & .aph-breathe-moods button { height: 30px; padding: 0 12px; border-radius: 99px; border: 1px solid var(--aph-breathe-line2); font-size: 12.5px; }
  & .aph-breathe-moods button[aria-checked="true"] { background: var(--aph-breathe-ink); color: var(--aph-breathe-paper); border-color: var(--aph-breathe-ink); }
  & .aph-breathe-dacts { display: flex; justify-content: flex-end; gap: 8px; }
}
.aph-breathe .aph-breathe-btn {
  display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 14px; border-radius: 10px; font-weight: 650; font-size: 12.5px; border: 1px solid var(--aph-breathe-line2);
  &.is-primary { background: var(--aph-breathe-ink); color: var(--aph-breathe-paper); border-color: var(--aph-breathe-ink); }
}

/* ── bells ── */
.aph-breathe .aph-breathe-bells {
  grid-area: bells; overflow: auto; overscroll-behavior: contain; border-left: 1px solid var(--aph-breathe-line); padding: 16px 14px 18px; display: grid; grid-template-columns: minmax(0, 1fr); align-content: start; gap: 12px; min-width: 0;
  scrollbar-width: thin;
}
.aph-breathe .aph-breathe-bh { display: flex; align-items: center; justify-content: space-between; }
.aph-breathe .aph-breathe-switch {
  display: inline-flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 600; color: var(--aph-breathe-mute);
  & i { position: relative; width: 32px; height: 19px; border-radius: 99px; background: var(--aph-breathe-line2); transition: background .25s; }
  & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 15px; height: 15px; border-radius: 50%; background: white; box-shadow: 0 1px 2px oklch(0 0 0 / .25); transition: transform .3s var(--aph-breathe-spring); }
  &[aria-checked="true"] i { background: var(--aph-breathe-accent); }
