}
.aph-breathe .aph-breathe-blist { display: grid; gap: 4px; }
.aph-breathe .aph-breathe-brow {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 4px 8px; padding: 8px 8px 8px 10px; border-radius: 12px; border: 1px solid transparent; transition: background .2s, border-color .2s;
