  & .aph-breathe-x:hover { background: var(--aph-breathe-sunk); color: var(--aph-breathe-ink); }
  & .aph-breathe-x svg { width: 14px; height: 14px; }
  & .aph-breathe-bed { grid-column: 1 / -1; display: none; gap: 6px; flex-wrap: wrap; align-items: center; padding-top: 6px; }
  & .aph-breathe-mini { display: inline-flex; padding: 2px; border-radius: 8px; background: var(--aph-breathe-sunk); }
  & .aph-breathe-mini button { height: 24px; min-width: 26px; padding: 0 7px; border-radius: 6px; font-size: 11.5px; font-weight: 600; color: var(--aph-breathe-mute); }
