  &:hover { background: color-mix(in oklab, var(--aph-breathe-paper) 50%, white); }
  &.is-sel { background: var(--aph-breathe-card); border-color: color-mix(in oklab, var(--aph-breathe-bronze) 45%, transparent); }
  &.is-sel .aph-breathe-bed { display: flex; }
