}
.aph-breathe .aph-breathe-pick { display: contents; }
.aph-breathe .aph-breathe-bfoot { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; }
.aph-breathe .aph-breathe-ghost {
  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 11px; border-radius: 9px; border: 1px solid var(--aph-breathe-line2); font-size: 12.5px; font-weight: 600;
  & svg { width: 15px; height: 15px; }
  &:hover { background: var(--aph-breathe-card); }
}
.aph-breathe .aph-breathe-rep {
  display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: var(--aph-breathe-mute);
  & select { height: 30px; border-radius: 8px; border: 1px solid var(--aph-breathe-line2); background: var(--aph-breathe-card); padding: 0 6px; font-size: 12px; }
}
.aph-breathe .aph-breathe-guide {
  margin-top: 4px; padding-top: 12px; border-top: 1px solid var(--aph-breathe-line); display: grid; gap: 8px;
  & p { font-size: 12px; color: var(--aph-breathe-mute); }
}
.aph-breathe .aph-breathe-gseg {
  display: grid; grid-template-columns: repeat(4, 1fr); padding: 3px; border-radius: 10px; background: var(--aph-breathe-sunk);
  & button { height: 28px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--aph-breathe-mute); }
  & button[aria-checked="true"] { background: var(--aph-breathe-card); color: var(--aph-breathe-ink); box-shadow: 0 1px 2px color-mix(in oklab, var(--aph-breathe-ink) 18%, transparent); }
}

/* ── tabs, toast ── */
.aph-breathe .aph-breathe-tabs {
  grid-area: tabs; display: none; gap: 4px; padding: 6px 8px; border-top: 1px solid var(--aph-breathe-line); background: var(--aph-breathe-sunk);
  & button { flex: 1; display: grid; justify-items: center; gap: 2px; padding: 5px 0 3px; border-radius: 9px; font-size: 10.5px; font-weight: 650; color: var(--aph-breathe-faint); }
  & button[aria-current="page"] { color: var(--aph-breathe-ink); background: var(--aph-breathe-card); }
}
.aph-breathe .aph-breathe-toast {
  position: absolute; z-index: 40; left: 50%; bottom: 16px; translate: -50% 0; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 24px);
  padding: 9px 9px 9px 14px; border-radius: 12px; background: var(--aph-breathe-ink); color: var(--aph-breathe-paper); font-size: 12.5px; font-weight: 550;
  box-shadow: 0 14px 34px -10px color-mix(in oklab, var(--aph-breathe-ink) 70%, transparent); transition: opacity .3s, translate .5s var(--aph-breathe-spring);
  &:empty { display: none; }
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & button { height: 28px; padding: 0 10px; border-radius: 8px; background: color-mix(in oklab, var(--aph-breathe-paper) 16%, transparent); font-weight: 700; white-space: nowrap; }
  & button kbd { background: transparent; color: inherit; opacity: .7; border-color: color-mix(in oklab, var(--aph-breathe-paper) 30%, transparent); }
  @starting-style { opacity: 0; translate: -50% 14px; }
}
@keyframes aph-breathe-ripple { 0% { opacity: .8; r: 12px; } 100% { opacity: 0; r: 34px; } }
@keyframes aph-breathe-flash { 0% { background: color-mix(in oklab, var(--aph-breathe-bronze) 22%, var(--aph-breathe-card)); } }

/* ── responsive ── */
@container aph-breathe (max-width: 1099px) {
  .aph-breathe .aph-breathe-app { grid-template-columns: 228px minmax(0, 1fr) 270px; }
}
@container aph-breathe (max-width: 959px) {
  .aph-breathe .aph-breathe-app { grid-template-columns: minmax(0, 1fr) 270px; grid-template-areas: "stage bells" "tabs tabs"; }
  .aph-breathe .aph-breathe-side { grid-area: stage; border-right: 0; }
  .aph-breathe .aph-breathe-tabs { display: flex; }
  .aph-breathe .aph-breathe-tabs [data-view-to="bells"] { display: none; }
  .aph-breathe[data-view="side"] .aph-breathe-stage { display: none; }
  .aph-breathe:not([data-view="side"]) .aph-breathe-side { display: none; }
}
@container aph-breathe (max-width: 759px) {
  .aph-breathe .aph-breathe-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "stage" "tabs"; }
  .aph-breathe .aph-breathe-bells { grid-area: stage; border-left: 0; }
  .aph-breathe:not([data-view="bells"]) .aph-breathe-bells { display: none; }
  .aph-breathe[data-view="bells"] .aph-breathe-stage { display: none; }
  .aph-breathe .aph-breathe-tabs [data-view-to="bells"] { display: grid; }
  .aph-breathe .aph-breathe-hint { display: none; }
  .aph-breathe .aph-breathe-ctl { gap: 8px; }
  .aph-breathe .aph-breathe-go kbd { display: none; }
  .aph-breathe .aph-breathe-toast { bottom: 70px; }
}

@media (prefers-reduced-motion: reduce) {
  .aph-breathe *, .aph-breathe *::before, .aph-breathe *::after { animation: none !important; transition-duration: 1ms !important; transition-delay: 0ms !important; }
}

