  aura: { n: 'Aura', d: 'A slow swell: in for five, out for five. Follow it loosely.', ph: [['Breathe in', 5, 'in'], ['Breathe out', 5, 'out']] },
  box: { n: 'Box', d: 'In, hold, out, hold — four counts each, tracing the square.', ph: [['Breathe in', 4, 'in'], ['Hold', 4, 'hold'], ['Breathe out', 4, 'out'], ['Hold', 4, 'holdlow']] },
  '478': { n: '4·7·8', d: 'In for four, hold for seven, out slowly for eight.', ph: [['Breathe in', 4, 'in'], ['Hold', 7, 'hold'], ['Breathe out', 8, 'out']] },
