let bid = 0;
const B = (t, l, k, tone) => ({ id: 'b' + (++bid), t, l, k, tone });
const PRESETS = [
  { id: 'morning', n: 'Morning sit', dur: 600, guide: 'aura', bells: () => [B(0, 'Start', 3, 'bowl'), B(300, 'Halfway', 1, 'chime'), B(600, 'End', 3, 'bowl')] },
  { id: 'box', n: 'Box breathing', dur: 360, guide: 'box', bells: () => [B(0, 'Start', 1, 'wood'), B(360, 'End', 2, 'bowl')] },
  { id: 'scan', n: 'Body scan', dur: 1200, guide: 'none', bells: () => [B(0, 'Start', 3, 'bowl'), B(300, 'Move attention', 1, 'chime'), B(600, 'Move attention', 1, 'chime'), B(900, 'Move attention', 1, 'chime'), B(1200, 'End', 3, 'bowl')] },
  { id: 'wind', n: 'Wind down 4·7·8', dur: 300, guide: '478', bells: () => [B(0, 'Start', 1, 'chime'), B(300, 'End', 2, 'bowl')] },
  { id: 'walk', n: 'Walking', dur: 900, guide: 'none', bells: () => [B(0, 'Start', 1, 'wood'), B(450, 'Turn around', 1, 'wood'), B(900, 'End', 2, 'bowl')] },
