const DAYS = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];

/* ── state ── */
const S = {
  presets: PRESETS.map(p => ({ id: p.id, n: p.n, dur: p.dur, guide: p.guide, bells: p.bells() })),
  preset: 'morning', dur: 600, guide: 'aura', bells: [], sel: null, sound: true, repeat: 0,
  state: 'idle', t0: 0, el: 0, rung: new Set(), view: 'timer', mood: null,
  week: [10, 0, 16, 10, 0, null, null], today: 4, before: [12, 0, 10],
