load('morning');
const sorted = () => S.bells.slice().sort((a, b) => a.t - b.t || (a.l === 'End') - (b.l === 'End'));
const elapsed = () => S.state === 'run' ? (performance.now() - S.t0) / 1000 : S.el;

/* ── undo & toast ── */
const undoStack = [];
function remember() { undoStack.push(JSON.stringify({ dur: S.dur, bells: S.bells, guide: S.guide, presets: S.presets, week: S.week, repeat: S.repeat })); if (undoStack.length > 40) undoStack.shift(); }
function undo() {
