    o.type = 'sine'; o.frequency.value = T.f * r;
    g.gain.setValueAtTime(0.0001, when); g.gain.exponentialRampToValueAtTime(amp, when + 0.006); g.gain.exponentialRampToValueAtTime(0.0001, when + dec);
