function sound(b) { if (!S.sound) return; const a = audio(); if (!a) return; for (let i = 0; i < b.k; i++) strike(b.tone, a.currentTime + 0.02 + i * 1.7); }
function ring(b) {
  S.rung.add(b.id); sound(b);
  const m = root.querySelector('[data-bell="' + b.id + '"]'); if (m) { m.classList.remove('is-ring'); void m.getBBox(); m.classList.add('is-ring'); }
  const r = root.querySelector('[data-brow="' + b.id + '"]'); if (r) { r.classList.remove('is-ring'); void r.offsetWidth; r.classList.add('is-ring'); }
