/* ── ring geometry: start at −75°, 330° clockwise ── */
const CX = 200, CY = 200, R = 170, A0 = -75, SPAN = 330;
const angOf = t => (A0 + (t / S.dur) * SPAN) * Math.PI / 180;
const ptOf = (t, r = R) => [CX + r * Math.cos(angOf(t)), CY + r * Math.sin(angOf(t))];
function arcD(r) { const a = A0 * Math.PI / 180, b = (A0 + SPAN) * Math.PI / 180; return 'M' + (CX + r * Math.cos(a)).toFixed(2) + ' ' + (CY + r * Math.sin(a)).toFixed(2) + ' A' + r + ' ' + r + ' 0 1 1 ' + (CX + r * Math.cos(b)).toFixed(2) + ' ' + (CY + r * Math.sin(b)).toFixed(2); }

/* ── render ── */
function keepFocus(fn) {
  const a = doc.activeElement, k = a && root.contains(a) && a.dataset ? a.dataset.k : null;
  fn();
  if (k) { const el = root.querySelector('[data-k="' + k + '"]'); if (el && el !== doc.activeElement) el.focus({ preventScroll: true }); }
