function render() { keepFocus(() => { renderSide(); renderRing(); renderBells(); renderGuidePick(); renderControls(); renderTabs(); paint(true); }); }

function renderSide() {
  $('[data-presets]').innerHTML = S.presets.map(p => '<button type="button" role="option" class="aph-breathe-preset" aria-selected="' + (p.id === S.preset) + '" data-preset="' + p.id + '" data-k="p-' + p.id + '"' + (S.state === 'run' ? ' aria-disabled="true" title="Pause the timer to switch sessions"' : '') + '><i style="--f:' + Math.min(1, p.dur / 1200).toFixed(2) + '"></i><b>' + esc(p.n) + '</b><span>' + Math.round(p.dur / 60) + ' min · ' + p.bells.length + ' bells · ' + GUIDES[p.guide].n.toLowerCase() + '</span></button>').join('');
