  const seq = S.before.concat(wk.slice(0, S.today + 1)); let i = seq.length - 1, streak = 0; if (!seq[i]) i--; while (i >= 0 && seq[i]) { streak++; i--; }
  $('[data-week]').innerHTML = '<header><div><h3 class="aph-breathe-h">This week</h3><b>' + tot + '<small>min</small></b></div><span>' + (streak ? streak + '-day streak' : 'No streak yet') + (wk[S.today] ? '' : ' · sit today') + '</span></header>' +
    '<div class="aph-breathe-days" role="img" aria-label="' + esc(DAYS.map((d, k) => ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'][k] + ' ' + (wk[k] == null ? 'upcoming' : wk[k] + ' min')).join(', ')) + '">' +
    wk.map((v, k) => '<div class="' + (v == null ? 'is-future' : !v ? 'is-zero' : '') + (k === S.today ? ' is-today' : '') + '" title="' + (v == null ? 'Upcoming' : v + ' min') + '"><i style="--v:' + (v ? (v / mx).toFixed(3) : 0) + '"></i><span>' + DAYS[k] + '</span></div>').join('') + '</div>';
