  const g = $('[data-bells]');
  g.innerHTML = sorted().map(b => {
    const [x, y] = ptOf(b.t);
    return '<g class="aph-breathe-bell' + (S.rung.has(b.id) ? ' is-past' : '') + '" data-bell="' + b.id + '" data-k="m-' + b.id + '" role="button" tabindex="0" aria-pressed="' + (S.sel === b.id) + '" aria-label="' + esc(b.l + ' bell at ' + mmss(b.t) + ', ' + b.k + ' strike' + (b.k > 1 ? 's' : '') + ', ' + TONES[b.tone].n.toLowerCase() + '. Drag, or arrow keys to move') + '" transform="translate(' + x.toFixed(1) + ' ' + y.toFixed(1) + ')">' +
