    '<span class="aph-breathe-mini"><button type="button" data-nudge="-15" data-k="n-' + b.id + '" aria-label="15 seconds earlier"' + (b.t <= 0 ? ' aria-disabled="true" title="Already at the start"' : '') + '>−15s</button><button type="button" data-nudge="15" data-k="n+' + b.id + '" aria-label="15 seconds later"' + (b.t >= S.dur ? ' aria-disabled="true" title="Already at the end"' : '') + '>+15s</button></span>' +
    '<button type="button" class="aph-breathe-test" data-test="' + b.id + '" data-k="test-' + b.id + '">Test</button></div></div>').join('') || '<p style="color:var(--aph-breathe-mute);font-size:12.5px;padding:6px 4px">No bells. The session will run silently.</p>';
