  const running = S.state === 'run', dm = $('[data-act="dur-"]'), dp = $('[data-act="dur+"]');
  if (running || S.dur <= 60) { dm.setAttribute('aria-disabled', 'true'); dm.title = running ? 'Pause to change the length' : 'One minute is the shortest session'; } else { dm.removeAttribute('aria-disabled'); dm.title = ''; }
  if (running || S.dur >= 3600) { dp.setAttribute('aria-disabled', 'true'); dp.title = running ? 'Pause to change the length' : 'Sixty minutes is the longest session'; } else { dp.removeAttribute('aria-disabled'); dp.title = ''; }
