  $('[data-act="toggle"]').setAttribute('aria-label', $('[data-golbl]').textContent + ' (Space)');
  const rs = $('[data-act="reset"]');
  if (S.state === 'idle') { rs.setAttribute('aria-disabled', 'true'); rs.title = 'Nothing to reset yet'; } else { rs.removeAttribute('aria-disabled'); rs.title = 'Reset (R)'; }
