/* Sip: water fills a glass; caffeine is a curve you can rearrange by dragging cups. */
@property --aph-water-lv { syntax: "<number>"; inherits: true; initial-value: 0; }

.aph-water {
  /* re-theme: paper, ink, accent (lake blue), coffee */
  --aph-water-paper: oklch(0.982 0.006 230);
  --aph-water-ink: oklch(0.27 0.03 245);
  --aph-water-accent: oklch(0.58 0.12 238);
  --aph-water-coffee: oklch(0.5 0.075 55);
  --aph-water-amber: oklch(0.72 0.13 68);
  --aph-water-card: color-mix(in oklab, var(--aph-water-paper) 40%, white);
  --aph-water-sunk: color-mix(in oklab, var(--aph-water-paper) 93%, var(--aph-water-ink));
  --aph-water-line: color-mix(in oklab, var(--aph-water-ink) 10%, transparent);
  --aph-water-line2: color-mix(in oklab, var(--aph-water-ink) 19%, transparent);
  --aph-water-mute: color-mix(in oklab, var(--aph-water-ink) 60%, var(--aph-water-paper));
  --aph-water-faint: color-mix(in oklab, var(--aph-water-ink) 38%, var(--aph-water-paper));
  --aph-water-mist: color-mix(in oklab, var(--aph-water-accent) 9%, var(--aph-water-paper));
  --aph-water-deep: color-mix(in oklab, var(--aph-water-accent) 80%, var(--aph-water-ink));
  --aph-water-tea: color-mix(in oklab, var(--aph-water-coffee) 45%, var(--aph-water-paper));
  --aph-water-ease: cubic-bezier(.2, .8, .2, 1);
  --aph-water-spring: linear(0, 0.08 4%, 0.33 10%, 0.7 17%, 0.95 24%, 1.07 31%, 1.08 37%, 1.03 47%, 0.995 60%, 1);

  position: relative; width: 100%; height: var(--aph-water-h, 680px);
  container-type: inline-size; container-name: aph-water; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--aph-water-paper); color: var(--aph-water-ink); color-scheme: light; accent-color: var(--aph-water-accent);
  border-radius: 14px; font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--aph-water-accent); outline-offset: 2px; border-radius: 6px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button[aria-disabled="true"] { cursor: not-allowed; opacity: .4; }
  & h2, & h3, & h4, & p, & ul, & ol { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & h2, & h3 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; display: inline-block; text-align: center; border: 1px solid var(--aph-water-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--aph-water-mute); background: var(--aph-water-card); }
  & [hidden] { display: none !important; }
  & h3 { font-size: 10.5px; text-transform: uppercase; letter-spacing: .13em; color: var(--aph-water-faint); font-weight: 700; }
}
.aph-water .aph-water-app {
  height: 100%; display: grid; grid-template-columns: 290px minmax(0, 1fr) 286px; grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "today day side" "tabs tabs tabs";
}

/* ── today / vessel ── */
.aph-water .aph-water-today {
  grid-area: today; overflow: auto; overscroll-behavior: contain; display: grid; grid-template-columns: minmax(0, 1fr); align-content: start; gap: 12px; padding: 16px 16px 18px; min-width: 0;
  border-right: 1px solid var(--aph-water-line); background: linear-gradient(var(--aph-water-mist), var(--aph-water-paper) 70%); scrollbar-width: thin;
}
.aph-water .aph-water-brand {
  display: flex; align-items: center; gap: 8px;
  & svg { width: 22px; height: 22px; color: var(--aph-water-accent); fill: color-mix(in oklab, var(--aph-water-accent) 20%, transparent); }
  & b { font-weight: 750; font-size: 16px; letter-spacing: -.02em; }
  & span { margin-left: auto; font-size: 11.5px; color: var(--aph-water-mute); }
}
.aph-water .aph-water-daynav {
  display: grid; grid-template-columns: 30px minmax(0, 1fr) 30px; align-items: center; gap: 6px;
  & button { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; border: 1px solid var(--aph-water-line2); background: var(--aph-water-card); }
  & div { text-align: center; }
  & b { display: block; font-weight: 700; font-size: 14px; }
  & span { font-size: 11.5px; color: var(--aph-water-mute); }
}
.aph-water .aph-water-vessel { display: grid; grid-template-columns: 112px minmax(0, 1fr); gap: 16px; align-items: end; padding: 4px 4px 0; }
.aph-water .aph-water-glass {
  --lv: var(--aph-water-lv);
  position: relative; width: 112px; aspect-ratio: .66; padding: 2.5px; background: var(--aph-water-line2);
  clip-path: polygon(0 0, 100% 0, 86% 100%, 14% 100%);
  &::before { content: ""; position: absolute; inset: 2.5px; clip-path: polygon(0 0, 100% 0, 86% 100%, 14% 100%); background: var(--aph-water-card); }
  & .aph-water-liquid { position: absolute; inset: 2.5px; clip-path: polygon(0 0, 100% 0, 86% 100%, 14% 100%); background: transparent; }
  & .aph-water-liquid::before { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: calc(min(var(--lv), 1) * 100%); background: linear-gradient(color-mix(in oklab, var(--aph-water-accent) 78%, white), var(--aph-water-accent)); }
  & .aph-water-other { position: absolute; left: 0; right: 0; bottom: 0; height: calc(min(var(--lv), 1) * var(--o, 0) * 100%); background: repeating-linear-gradient(-45deg, var(--aph-water-tea) 0 5px, color-mix(in oklab, var(--aph-water-tea) 80%, white) 5px 10px); z-index: 1; }
  & .aph-water-wave { position: absolute; left: 0; width: 200%; height: 12px; bottom: calc(min(var(--lv), 1) * 100% - 6px); fill: color-mix(in oklab, var(--aph-water-accent) 78%, white); stroke: none; animation: aph-water-wave 3.2s linear infinite; z-index: 2; }
  & .aph-water-goalmark { position: absolute; left: 6%; right: 6%; bottom: calc(var(--pace, 0) * 100%); border-top: 1.5px dashed var(--aph-water-ink); opacity: .45; z-index: 3; transition: bottom .6s var(--aph-water-ease); }
  transition: --aph-water-lv 1.1s var(--aph-water-spring);
}
.aph-water[data-off] .aph-water-wave { animation-play-state: paused; }
.aph-water .aph-water-read {
  display: grid; gap: 2px; padding-bottom: 6px;
  & output { font: 250 clamp(30px, 3.4cqi, 38px)/1 system-ui; letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
  & output small { font-size: 14px; color: var(--aph-water-mute); margin-left: 2px; font-weight: 500; letter-spacing: 0; }
  & span { font-size: 12px; color: var(--aph-water-mute); font-variant-numeric: tabular-nums; }
  & small { font-size: 11.5px; font-weight: 650; }
  & .is-ahead { color: oklch(0.52 0.12 150); }
  & .is-behind { color: var(--aph-water-coffee); }
}
