  clearTimeout(toastT); toastT = setTimeout(() => { if (root.isConnected) t.innerHTML = ''; }, withUndo ? 6000 : 3500);
}

/* ── render ── */
function keepFocus(fn) {
  const a = doc.activeElement, k = a && root.contains(a) && a.dataset ? a.dataset.k : null;
  fn();
  if (k) { const el = root.querySelector('[data-k="' + k + '"]'); if (el && el !== doc.activeElement) el.focus({ preventScroll: true }); }
}
function render() { keepFocus(() => { renderToday(); renderChart(); renderHyd(); renderSide(); renderTabs(); }); }

function renderToday() {
  const t = totals(S.day), n = now();
  $('[data-dayname]').textContent = isToday() ? 'Today' : ({ Sat: 'Saturday', Sun: 'Sunday', Mon: 'Monday', Tue: 'Tuesday', Wed: 'Wednesday', Thu: 'Thursday' })[DAYS[S.day].slice(0, 3)];
  $('[data-daysub]').textContent = DAYS[S.day] + (isToday() ? ' · ' + hm(n) : '');
  const pv = $('[data-act="day-prev"]'), nx = $('[data-act="day-next"]');
  if (S.day === 0) { pv.setAttribute('aria-disabled', 'true'); pv.title = 'History starts on ' + DAYS[0]; } else { pv.removeAttribute('aria-disabled'); pv.title = 'Previous day ( [ )'; }
  if (isToday()) { nx.setAttribute('aria-disabled', 'true'); nx.title = 'Tomorrow hasn’t started'; } else { nx.removeAttribute('aria-disabled'); nx.title = 'Next day ( ] )'; }
  const g = $('.aph-water-glass'), lv = t.all / S.goal;
  g.style.setProperty('--aph-water-lv', lv.toFixed(4));
  g.style.setProperty('--o', t.all ? (t.other / t.all).toFixed(3) : 0);
  const pace = isToday() ? paceAt(n) : 1;
  g.style.setProperty('--pace', pace.toFixed(3));
  $('[data-vessel]').setAttribute('aria-label', ml(t.all) + ' of ' + ml(S.goal) + ' ml, ' + ml(t.water) + ' ml of it water');
  $('[data-total]').innerHTML = ml(t.all) + '<small>ml</small>';
  $('[data-goaltxt]').textContent = Math.round(lv * 100) + '% of ' + ml(S.goal) + ' · ' + ml(t.water) + ' water, ' + ml(t.other) + ' other';
  const exp = S.goal * pace, diff = t.all - exp, P = $('[data-pace]');
  P.className = diff >= 0 ? 'is-ahead' : 'is-behind';
  P.textContent = lv >= 1 ? 'Goal reached' + (isToday() ? ' — nicely done' : '') : isToday() ? (Math.abs(diff) < 50 ? 'Right on pace' : ml(Math.abs(diff)) + ' ml ' + (diff > 0 ? 'ahead of' : 'behind') + ' pace') : ml(S.goal - t.all) + ' ml short that day';
  $('[data-quick]').innerHTML = QUICK.map(k => { const d = DRINK[k]; return '<button type="button" data-add="' + k + '" data-kind="' + d.kind + '" data-k="q-' + k + '" aria-label="Add ' + d.n + ', ' + d.ml + ' ml' + (d.mg ? ', ' + d.mg + ' mg caffeine' : '') + '"><span class="aph-water-ico">' + d.ic + '</span><b>' + d.n.replace(' of water', '') + '</b><span>' + d.ml + ' ml' + (d.mg ? ' · ' + d.mg + ' mg' : '') + '</span></button>'; }).join('') +
    '<button type="button" class="aph-water-more" data-act="more" data-k="more" aria-haspopup="menu" aria-expanded="false">More drinks…</button>';
}

const X0 = 34, X1 = 516, AX = 360, AXW = 1080;
const xOf = t => X0 + (clamp(t, AX, 1440) - AX) / AXW * (X1 - X0);
function renderChart(onlyCurve) {
  const box = $('[data-chart]'), n = isToday() ? now() : 1440, L = log();
  const pts = []; let peak = 0;
  for (let t = AX; t <= 1440; t += 10) { const c = caf(S.day, t); pts.push([t, c]); peak = Math.max(peak, c); }
  const top = Math.max(200, Math.ceil(peak / 50) * 50), H = 190, Y0 = 8, Y1 = 168, yOf = c => Y1 - c / top * (Y1 - Y0);
  const past = pts.filter(p => p[0] <= n), fut = pts.filter(p => p[0] >= n - 10);
  const line = arr => arr.map((p, i) => (i ? 'L' : 'M') + xOf(p[0]).toFixed(1) + ' ' + yOf(p[1]).toFixed(1)).join(' ');
  const area = arr => arr.length ? line(arr) + ' L' + xOf(arr[arr.length - 1][0]).toFixed(1) + ' ' + Y1 + ' L' + xOf(arr[0][0]).toFixed(1) + ' ' + Y1 + 'Z' : '';
  const bedC = caf(S.day, S.bed), peakAt = pts.reduce((b, p) => (p[1] > b[1] ? p : b), [0, 0]);
  let grid = '';
  for (let c = 0; c <= top; c += top > 300 ? 100 : 50) grid += '<line class="aph-water-gl" x1="' + X0 + '" x2="' + X1 + '" y1="' + yOf(c).toFixed(1) + '" y2="' + yOf(c).toFixed(1) + '"/><text x="' + (X0 - 6) + '" y="' + (yOf(c) + 3).toFixed(1) + '" text-anchor="end">' + c + '</text>';
  for (let t = AX; t <= 1440; t += 180) grid += '<text x="' + xOf(t).toFixed(1) + '" y="' + (H - 6) + '" text-anchor="middle">' + (t === 1440 ? '24' : hm(t).slice(0, 2)) + '</text>';
