  const pins = sorted.map(d => { const x = (clamp(d.t, AX, 1440) - AX) / AXW; let row = x - lastX[0] < 0.045 ? (x - lastX[1] < 0.045 ? 0 : 1) : 0; lastX[row] = x; const D = DRINK[d.k];
    return '<button type="button" class="aph-water-pin' + (d.id === S.newId ? ' is-new' : '') + '" style="--x:' + x.toFixed(4) + ';--row:' + row + '" data-pin="' + d.id + '" data-kind="' + D.kind + '" data-k="pin-' + d.id + '" aria-pressed="' + (S.sel === d.id) + '" aria-label="' + esc(D.n + ' at ' + hm(d.t) + '. Drag, or arrow keys to move by 5 minutes') + '">' + D.ic + '</button>'; }).join('');
  const hov = S.hover != null ? '<line class="aph-water-cross" x1="' + xOf(S.hover).toFixed(1) + '" x2="' + xOf(S.hover).toFixed(1) + '" y1="' + Y0 + '" y2="' + Y1 + '"/><circle class="aph-water-dot" cx="' + xOf(S.hover).toFixed(1) + '" cy="' + yOf(caf(S.day, S.hover)).toFixed(1) + '" r="4"/>' +
    '<rect class="aph-water-tagb" x="' + clamp(xOf(S.hover) - 42, X0, X1 - 84).toFixed(1) + '" y="' + (Y0 - 2) + '" width="84" height="18" rx="5"/><text class="aph-water-tagt" x="' + clamp(xOf(S.hover), X0 + 42, X1 - 42).toFixed(1) + '" y="' + (Y0 + 10) + '" text-anchor="middle">' + hm(S.hover) + ' · ' + Math.round(caf(S.day, S.hover)) + ' mg</text>' : '';
  const svgHtml = '<svg class="aph-water-svg" data-csvg viewBox="0 0 520 ' + H + '" role="img" aria-label="Estimated caffeine in your system, peaking at ' + Math.round(peakAt[1]) + ' mg around ' + hm(peakAt[0]) + ', about ' + Math.round(bedC) + ' mg at bedtime">' + grid +
      (isToday() ? '<rect class="aph-water-future" x="' + xOf(n).toFixed(1) + '" y="' + Y0 + '" width="' + (X1 - xOf(n)).toFixed(1) + '" height="' + (Y1 - Y0) + '"/>' : '') +
      '<path class="aph-water-area" d="' + area(pts) + '"/><path class="aph-water-curve" d="' + line(past) + '"/>' + (isToday() ? '<path class="aph-water-curve" style="stroke-dasharray:4 4" d="' + line(fut) + '"/>' : '') +
      '<line class="aph-water-bed" x1="' + xOf(S.bed).toFixed(1) + '" x2="' + xOf(S.bed).toFixed(1) + '" y1="' + Y0 + '" y2="' + Y1 + '"/><text x="' + (xOf(S.bed) - 4).toFixed(1) + '" y="' + (Y0 + 24) + '" text-anchor="end">bed ' + hm(S.bed) + '</text>' +
      '<circle class="aph-water-dot" cx="' + xOf(S.bed).toFixed(1) + '" cy="' + yOf(bedC).toFixed(1) + '" r="4"/>' +
      (isToday() ? '<line class="aph-water-now" x1="' + xOf(n).toFixed(1) + '" x2="' + xOf(n).toFixed(1) + '" y1="' + Y0 + '" y2="' + Y1 + '"/><text x="' + (xOf(n) + 4).toFixed(1) + '" y="' + (Y1 - 4) + '">now</text>' : '') + hov + '</svg>';
