  box.innerHTML = '<div class="aph-water-lane" data-lane>' + pins + '</div>' + svgHtml;
  const tot = totals(S.day);
  $('[data-cafsub]').textContent = tot.mg + ' mg across ' + L.filter(d => DRINK[d.k].mg).length + ' drinks · peak ≈ ' + Math.round(peakAt[1]) + ' mg at ' + hm(peakAt[0]) + ' · half-life ' + S.half + ' h';
  $('[data-bedmg]').innerHTML = '≈ ' + Math.round(bedC) + '<small> mg</small>';
