}
function renderHyd() {
  const L = log().slice().sort((a, b) => a.t - b.t), n = isToday() ? now() : 1440, t = totals(S.day);
  const W = 520, H = 110, Y0 = 6, Y1 = 92, top = Math.max(S.goal, t.all, L.reduce((a, d) => a + DRINK[d.k].ml, 0)) * 1.08, yOf = v => Y1 - v / top * (Y1 - Y0);
  let acc = 0, d = 'M' + xOf(AX).toFixed(1) + ' ' + Y1;
  L.forEach(x => { if (x.t > n) return; d += ' H' + xOf(x.t).toFixed(1); acc += DRINK[x.k].ml; d += ' V' + yOf(acc).toFixed(1); });
  d += ' H' + xOf(n).toFixed(1);
  const pace = 'M' + xOf(420).toFixed(1) + ' ' + Y1 + ' L' + xOf(1260).toFixed(1) + ' ' + yOf(S.goal).toFixed(1) + ' H' + xOf(1440).toFixed(1);
  $('[data-hyd]').innerHTML = '<svg class="aph-water-svg" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="' + ml(acc) + ' ml by ' + hm(n) + ' against a pace line to ' + ml(S.goal) + ' ml by 21:00">' +
    '<line class="aph-water-gl" x1="' + X0 + '" x2="' + X1 + '" y1="' + yOf(S.goal).toFixed(1) + '" y2="' + yOf(S.goal).toFixed(1) + '"/><text x="' + (X0 - 6) + '" y="' + (yOf(S.goal) + 3).toFixed(1) + '" text-anchor="end">' + (S.goal / 1000).toFixed(1) + 'l</text>' +
    '<path class="aph-water-pace" d="' + pace + '"/><path class="aph-water-stepa" d="' + d + ' V' + Y1 + 'Z"/><path class="aph-water-step" d="' + d + '"/>' +
    [360, 540, 720, 900, 1080, 1260, 1440].map(m => '<text x="' + xOf(m).toFixed(1) + '" y="' + (H - 4) + '" text-anchor="middle">' + (m === 1440 ? '24' : hm(m).slice(0, 2)) + '</text>').join('') + '</svg>';
  $('[data-hydsub]').textContent = 'dashed: pace to ' + ml(S.goal) + ' ml by 21:00';
}
function renderSide() {
  const L = log().slice().sort((a, b) => a.t - b.t), n = isToday() ? now() : 1440, t = totals(S.day);
  $('[data-logsum]').textContent = L.length + ' drinks · ' + t.mg + ' mg';
  $('[data-log]').innerHTML = L.map(d => { const D = DRINK[d.k], fut = d.t > n;
    return '<div class="aph-water-row' + (S.sel === d.id ? ' is-sel' : '') + (d.id === S.newRowId ? ' is-new' : '') + '"><button type="button" role="option" aria-selected="' + (S.sel === d.id) + '" data-row="' + d.id + '" data-k="row-' + d.id + '"><time>' + hm(d.t) + '</time><i class="' + (D.mg ? 'is-caf' : '') + '"></i><b>' + esc(D.n) + (fut ? ' · planned' : '') + '</b><em>' + D.ml + ' ml' + (D.mg ? '<small>' + D.mg + ' mg</small>' : '') + '</em></button>' +
      '<div class="aph-water-rowed"><button type="button" data-shift="-15" data-k="sh-' + d.id + '">−15 min</button><button type="button" data-shift="15" data-k="sh+' + d.id + '">+15 min</button><button type="button" class="is-danger" data-del="' + d.id + '" data-k="del-' + d.id + '">Remove</button></div></div>'; }).join('') || '<p style="color:var(--aph-water-mute);font-size:12.5px;padding:8px">Nothing logged yet.</p>';
