  $('[data-weeksum]').textContent = 'avg ' + ml(avg) + ' ml · ' + Math.round(wk.slice(0, 6).reduce((a, x) => a + x.mg, 0) / 6) + ' mg';
  $('[data-week]').innerHTML = '<div class="aph-water-wbars"><i class="aph-water-goal" aria-hidden="true"></i>' + wk.map((x, i) => '<button type="button" data-wday="' + i + '" data-k="w-' + i + '" aria-current="' + (i === S.day) + '" aria-label="' + DAYS[i] + ': ' + ml(x.all) + ' ml, ' + x.mg + ' mg caffeine"><span class="aph-water-wb" style="--v:' + (x.all / S.goal).toFixed(3) + ';--c:' + x.mg + '"><i class="' + (x.all < S.goal ? 'is-short' : '') + '"></i><b></b></span><span>' + DAYS[i].slice(0, 2) + '</span></button>').join('') + '</div>' +
    '<div class="aph-water-wleg"><span><i></i>fluid vs goal</span><span><i class="is-dot"></i>caffeine (0–400 mg)</span></div>';
  $('[data-settings]').innerHTML = '<h3>Settings</h3>' +
    '<div class="aph-water-srow"><span>Daily goal</span><span class="aph-water-step"><button type="button" data-set="goal" data-d="-250" data-k="goal-" aria-label="Goal 250 ml less"' + (S.goal <= 1500 ? ' aria-disabled="true" title="1,500 ml is the lowest goal"' : '') + '>' + I.minus + '</button><output>' + ml(S.goal) + ' ml</output><button type="button" data-set="goal" data-d="250" data-k="goal+" aria-label="Goal 250 ml more"' + (S.goal >= 4000 ? ' aria-disabled="true" title="4,000 ml is the highest goal"' : '') + '>' + I.plus + '</button></span></div>' +
    '<div class="aph-water-srow"><span>Bedtime</span><span class="aph-water-step"><button type="button" data-set="bed" data-d="-30" data-k="bed-" aria-label="Bedtime 30 minutes earlier"' + (S.bed <= 1260 ? ' aria-disabled="true" title="21:00 is the earliest"' : '') + '>' + I.minus + '</button><output>' + hm(S.bed) + '</output><button type="button" data-set="bed" data-d="30" data-k="bed+" aria-label="Bedtime 30 minutes later"' + (S.bed >= 1440 ? ' aria-disabled="true" title="Midnight is the latest the chart shows"' : '') + '>' + I.plus + '</button></span></div>' +
    '<div class="aph-water-srow"><span>Caffeine half-life<small>varies person to person</small></span><span class="aph-water-seg" role="radiogroup" aria-label="Caffeine half-life">' + [4, 5, 6].map(h => '<button type="button" role="radio" aria-checked="' + (S.half === h) + '" data-half="' + h + '" data-k="half-' + h + '">' + h + ' h</button>').join('') + '</span></div>';
}
function renderTabs() { $$('[data-view-to]').forEach(b => b.setAttribute('aria-current', b.dataset.viewTo === S.view ? 'page' : 'false')); root.dataset.view = S.view; }
function setView(v) { const w = root.clientWidth; if (v === 'today' && w >= 760) v = 'day'; if (v === 'side' && w >= 960) v = 'day'; S.view = v; renderTabs(); }

/* ── actions ── */
function add(k) {
  const L = log(), t = isToday() ? now() : Math.min(1435, (L.length ? Math.max(...L.map(d => d.t)) : 690) + 30);
  remember();
  const d = { id: 'd' + (++uid), t, k }; L.push(d); S.newId = d.id; S.newRowId = d.id; S.sel = null;
  render();
  const D = DRINK[k], tt = totals(S.day);
  toast(D.n + ' at ' + hm(t) + ' · ' + ml(tt.all) + ' ml' + (D.mg ? ' · ≈ ' + Math.round(caf(S.day, S.bed)) + ' mg at bedtime' : ''), true);
}
function remove(id) {
  const L = log(), d = L.find(x => x.id === id); if (!d) return;
  remember(); S.days[S.day] = L.filter(x => x.id !== id); if (S.sel === id) S.sel = null;
  render(); toast(DRINK[d.k].n + ' at ' + hm(d.t) + ' removed', true);
}
function shift(id, by, quiet) {
