}
function closeMenu(refocus) { const M = $('[data-menu]'); if (M.hidden) return; M.hidden = true; const b = $('[data-act="more"]'); if (b) { b.setAttribute('aria-expanded', 'false'); if (refocus) b.focus(); } }

/* ── drag pins along the day; hover the curve for a readout ── */
let drag = null, swallow = false;
root.addEventListener('pointerdown', e => {
  if (!e.target.closest('[data-menu], [data-act="more"]')) closeMenu();
  const p = e.target.closest('[data-pin]'); if (!p || e.button !== 0) return;
  drag = { id: p.dataset.pin, x: e.clientX, on: false, pid: e.pointerId };
});
root.addEventListener('pointermove', e => {
  if (drag) {
    if (!drag.on) { if (Math.abs(e.clientX - drag.x) < 4) return; drag.on = true; remember(); try { root.setPointerCapture(drag.pid); } catch (err) {} }
    const lane = $('[data-lane]').getBoundingClientRect(), t = AX + clamp((e.clientX - lane.left) / lane.width, 0, 1) * AXW;
    const d = log().find(x => x.id === drag.id);
    if (d && shift(drag.id, t - d.t, true)) { S.sel = drag.id; renderChart(); renderHyd(); renderSide(); renderToday(); const pin = root.querySelector('[data-pin="' + drag.id + '"]'); if (pin) pin.classList.add('is-drag'); }
    return;
  }
  const svg = e.target.closest && e.target.closest('[data-csvg]');
  if (svg) {
    const b = svg.getBoundingClientRect(), x = (e.clientX - b.left) / b.width * 520;
    const t = clamp(Math.round((AX + (x - X0) / (X1 - X0) * AXW) / 5) * 5, AX, 1440);
    if (t !== S.hover) { S.hover = t; renderChart(true); }
  } else if (S.hover != null && !e.target.closest('[data-chart]')) { S.hover = null; renderChart(true); }
});
root.addEventListener('pointerleave', () => { if (S.hover != null) { S.hover = null; renderChart(true); } });
function endDrag() {
  if (!drag) return; const d = drag; drag = null; if (!d.on) return;
  swallow = true; setTimeout(() => { swallow = false; }, 0);
  const x = log().find(z => z.id === d.id); render();
  if (x) toast(DRINK[x.k].n + ' moved to ' + hm(x.t) + ' · ≈ ' + Math.round(caf(S.day, S.bed)) + ' mg at bedtime', true);
}
root.addEventListener('pointerup', endDrag);
root.addEventListener('pointercancel', endDrag);

root.addEventListener('click', e => {
  if (swallow) return;
  const t = e.target.closest('button'); if (!t || !root.contains(t)) return;
  if (t.getAttribute('aria-disabled') === 'true') { if (t.title) toast(t.title); return; }
  const a = t.dataset.act;
  if (t.dataset.add) { closeMenu(); add(t.dataset.add); return; }
  if (t.dataset.pin) { S.sel = S.sel === t.dataset.pin ? null : t.dataset.pin; renderChart(); renderSide(); const p = root.querySelector('[data-pin="' + t.dataset.pin + '"]'); if (p) p.focus({ preventScroll: true }); return; }
  if (t.dataset.row) { S.sel = S.sel === t.dataset.row ? null : t.dataset.row; renderChart(); renderSide(); return; }
  if (t.dataset.shift) { if (shift(S.sel, +t.dataset.shift)) { render(); const d = log().find(x => x.id === S.sel); toast(DRINK[d.k].n + ' now at ' + hm(d.t), true); } return; }
