  if (t.dataset.half) { remember(); S.half = +t.dataset.half; render(); toast('Half-life ' + S.half + ' h · ≈ ' + Math.round(caf(S.day, S.bed)) + ' mg at bedtime', true); return; }
  if (t.dataset.set) { remember(); if (t.dataset.set === 'goal') S.goal = clamp(S.goal + +t.dataset.d, 1500, 4000); else S.bed = clamp(S.bed + +t.dataset.d, 1260, 1440); render(); return; }
  if (t.dataset.viewTo) { setView(t.dataset.viewTo); return; }
  switch (a) {
    case 'day-prev': S.day = Math.max(0, S.day - 1); S.sel = null; render(); break;
    case 'day-next': S.day = Math.min(6, S.day + 1); S.sel = null; render(); break;
    case 'more': { const M = $('[data-menu]'); if (!M.hidden) closeMenu(true); else openMore(t); break; }
    case 'undo': undo(); break;
  }
});
root.addEventListener('keydown', e => {
  const k = e.key, t = e.target, M = $('[data-menu]');
  if (!M.hidden) {
    const items = $$('button', M), i = items.indexOf(doc.activeElement);
    if (k === 'Escape') { e.preventDefault(); closeMenu(true); }
    else if (k === 'ArrowDown' || k === 'ArrowUp') { e.preventDefault(); items[(i + (k === 'ArrowDown' ? 1 : -1) + items.length) % items.length].focus(); }
    else if (k === 'Tab') closeMenu();
