/* Loosen: a mobility routine player with a forward-kinematics demo figure. */
@property --aph-mobility-flip { syntax: "<number>"; inherits: false; initial-value: 1; }

.aph-mobility {
  /* re-theme: paper, ink, accent (coral) */
  --aph-mobility-paper: oklch(0.972 0.012 70);
  --aph-mobility-ink: oklch(0.26 0.025 40);
  --aph-mobility-accent: oklch(0.66 0.17 35);
  --aph-mobility-card: color-mix(in oklab, var(--aph-mobility-paper) 40%, white);
  --aph-mobility-sunk: color-mix(in oklab, var(--aph-mobility-paper) 93%, var(--aph-mobility-ink));
  --aph-mobility-line: color-mix(in oklab, var(--aph-mobility-ink) 11%, transparent);
  --aph-mobility-line2: color-mix(in oklab, var(--aph-mobility-ink) 20%, transparent);
  --aph-mobility-mute: color-mix(in oklab, var(--aph-mobility-ink) 62%, var(--aph-mobility-paper));
  --aph-mobility-faint: color-mix(in oklab, var(--aph-mobility-ink) 40%, var(--aph-mobility-paper));
  --aph-mobility-blush: color-mix(in oklab, var(--aph-mobility-accent) 13%, var(--aph-mobility-paper));
  --aph-mobility-far: color-mix(in oklab, var(--aph-mobility-accent) 62%, var(--aph-mobility-paper));
  --aph-mobility-ease: cubic-bezier(.2, .8, .2, 1);
  --aph-mobility-spring: linear(0, 0.1 4%, 0.38 10%, 0.75 17%, 0.98 24%, 1.06 30%, 1.06 36%, 1.02 46%, 0.995 60%, 1);

  position: relative; width: 100%; height: var(--aph-mobility-h, 680px);
  container-type: inline-size; container-name: aph-mobility; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--aph-mobility-paper); color: var(--aph-mobility-ink); color-scheme: light; accent-color: var(--aph-mobility-accent);
  border-radius: 14px; font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--aph-mobility-accent); outline-offset: 2px; border-radius: 6px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button[aria-disabled="true"] { cursor: not-allowed; opacity: .4; }
  & h2, & h3, & h4, & p, & ul, & ol { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & h2, & h3 { text-wrap: balance; }
  & p { text-wrap: pretty; }
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; display: inline-block; text-align: center; border: 1px solid var(--aph-mobility-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--aph-mobility-mute); background: var(--aph-mobility-card); }
  & [hidden] { display: none !important; }
  & h3 { font-size: 10.5px; text-transform: uppercase; letter-spacing: .13em; color: var(--aph-mobility-faint); font-weight: 700; }
}
.aph-mobility .aph-mobility-app {
  height: 100%; display: grid; grid-template-columns: 262px minmax(0, 1fr) 270px; grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "queue player lib" "tabs tabs tabs";
}

/* ── queue ── */
.aph-mobility .aph-mobility-queue {
  grid-area: queue; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr) auto; min-height: 0; min-width: 0;
  border-right: 1px solid var(--aph-mobility-line); background: var(--aph-mobility-sunk);
}
.aph-mobility .aph-mobility-brand {
  display: flex; align-items: center; gap: 8px; padding: 16px 16px 8px;
  & svg { width: 22px; height: 22px; color: var(--aph-mobility-accent); stroke-width: 2; }
  & b { font-weight: 850; font-size: 16px; letter-spacing: -.03em; }
}
.aph-mobility .aph-mobility-rhead {
  padding: 4px 16px 10px;
  & h2 { font-size: 15px; font-weight: 750; letter-spacing: -.01em; }
  & p { font-size: 11.5px; color: var(--aph-mobility-mute); font-variant-numeric: tabular-nums; }
}
.aph-mobility .aph-mobility-list {
  overflow: auto; overscroll-behavior: contain; padding: 0 8px 8px; display: grid; align-content: start; gap: 3px;
  scrollbar-width: thin; scrollbar-color: var(--aph-mobility-line2) transparent;
}
.aph-mobility .aph-mobility-item {
  position: relative; display: grid; grid-template-columns: 16px minmax(0, 1fr); align-items: center; gap: 4px; padding: 4px 6px 4px 2px; border-radius: 12px;
  background: transparent; transition: background .2s, box-shadow .2s;
  & .aph-mobility-grip { width: 16px; height: 34px; display: grid; place-items: center; color: var(--aph-mobility-faint); cursor: grab; touch-action: none; }
  & .aph-mobility-grip svg { width: 14px; height: 14px; stroke-width: 3; }
  & .aph-mobility-pick { display: grid; grid-template-columns: 44px minmax(0, 1fr) auto; align-items: center; gap: 1px 9px; text-align: left; min-width: 0; padding: 3px 0; }
  & .aph-mobility-thumb { grid-row: span 2; width: 44px; height: 32px; border-radius: 8px; background: var(--aph-mobility-card); }
  & b { font-weight: 640; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & span { font-size: 11px; color: var(--aph-mobility-mute); font-variant-numeric: tabular-nums; }
  & em { grid-row: span 2; font: 650 11.5px/1 ui-monospace, Menlo, monospace; font-style: normal; color: var(--aph-mobility-mute); font-variant-numeric: tabular-nums; }
  & .aph-mobility-iedit { grid-column: 2; display: none; gap: 4px; padding: 4px 0 4px 53px; }
  & .aph-mobility-iedit button { height: 26px; padding: 0 9px; border-radius: 7px; border: 1px solid var(--aph-mobility-line2); font-size: 11.5px; font-weight: 650; white-space: nowrap; background: var(--aph-mobility-card); }
  & .aph-mobility-iedit .is-danger { color: oklch(0.52 0.17 28); }
  &:hover { background: color-mix(in oklab, var(--aph-mobility-paper) 55%, white); }
  &.is-now { background: var(--aph-mobility-card); box-shadow: 0 1px 0 var(--aph-mobility-line), 0 8px 20px -14px color-mix(in oklab, var(--aph-mobility-ink) 50%, transparent); }
  &.is-now::before { content: ""; position: absolute; left: -8px; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--aph-mobility-accent); }
  &.is-now em { color: var(--aph-mobility-accent); }
  &.is-done b { color: var(--aph-mobility-faint); text-decoration: line-through; text-decoration-color: var(--aph-mobility-line2); }
  &.is-sel .aph-mobility-iedit { display: flex; }
  &.is-sel { box-shadow: inset 0 0 0 1px var(--aph-mobility-line2); }
  &.is-lift { z-index: 5; background: var(--aph-mobility-card); box-shadow: 0 18px 30px -14px color-mix(in oklab, var(--aph-mobility-ink) 60%, transparent); }
  &.is-new { animation: aph-mobility-in .5s var(--aph-mobility-ease); }
}
.aph-mobility .aph-mobility-qhint { padding: 10px 16px 14px; border-top: 1px solid var(--aph-mobility-line); font-size: 11px; color: var(--aph-mobility-faint); display: flex; align-items: center; gap: 3px; flex-wrap: wrap; }
.aph-mobility .aph-mobility-qhint svg { width: 12px; height: 12px; }

/* thumbnails reuse the figure's own classes */
.aph-mobility .aph-mobility-thumb, .aph-mobility .aph-mobility-fig {
  & .aph-mobility-limb { stroke: var(--aph-mobility-ink); stroke-width: 11; fill: none; }
  & .aph-mobility-limb.is-far { stroke: var(--aph-mobility-far); }
  & .aph-mobility-trunk { stroke: var(--aph-mobility-ink); stroke-width: 17; fill: none; }
  & .aph-mobility-head { fill: var(--aph-mobility-ink); stroke: none; }
  & .aph-mobility-ghost .aph-mobility-limb, & .aph-mobility-ghost .aph-mobility-trunk { stroke: var(--aph-mobility-accent); stroke-width: 2; stroke-dasharray: 3 5; }
  & .aph-mobility-ghost .aph-mobility-head { fill: none; stroke: var(--aph-mobility-accent); stroke-width: 2; stroke-dasharray: 3 5; }
  & .aph-mobility-ghost { opacity: .45; }
  & .aph-mobility-floor { stroke: var(--aph-mobility-line2); stroke-width: 2; }
  & .aph-mobility-mat { fill: color-mix(in oklab, var(--aph-mobility-accent) 22%, var(--aph-mobility-paper)); stroke: none; }
  & .aph-mobility-wall { fill: color-mix(in oklab, var(--aph-mobility-ink) 8%, var(--aph-mobility-paper)); stroke: var(--aph-mobility-line2); stroke-width: 1.5; }
}

/* ── player ── */
.aph-mobility .aph-mobility-player {
  grid-area: player; position: relative; display: grid; grid-template-rows: minmax(0, 1fr) auto auto auto; gap: 12px; padding: 16px 20px 16px; min-height: 0; min-width: 0;
  container-type: inline-size; container-name: aph-mobility-player;
}
.aph-mobility .aph-mobility-stage {
  position: relative; min-height: 0; border-radius: 22px; overflow: hidden;
  background: radial-gradient(90% 70% at 50% 100%, color-mix(in oklab, var(--aph-mobility-accent) 20%, var(--aph-mobility-paper)), var(--aph-mobility-blush) 70%);
  display: grid; place-items: center;
}
.aph-mobility .aph-mobility-fig {
  width: 100%; height: 100%; max-height: 100%; display: block;
  & .aph-mobility-shadow { fill: color-mix(in oklab, var(--aph-mobility-ink) 10%, transparent); stroke: none; transition: cx .6s var(--aph-mobility-ease); }
  & .aph-mobility-body { transform-box: view-box; transform-origin: 200px 150px; transform: scaleX(var(--aph-mobility-flip)); transition: --aph-mobility-flip .7s var(--aph-mobility-spring); }
}
.aph-mobility .aph-mobility-meta { position: absolute; left: 14px; top: 12px; display: flex; gap: 6px; z-index: 2; }
.aph-mobility .aph-mobility-area, .aph-mobility .aph-mobility-side { height: 24px; padding: 0 10px; border-radius: 99px; display: inline-flex; align-items: center; font-size: 11px; font-weight: 700; letter-spacing: .04em; background: var(--aph-mobility-card); color: var(--aph-mobility-mute); }
.aph-mobility .aph-mobility-side { background: var(--aph-mobility-ink); color: var(--aph-mobility-paper); }
.aph-mobility .aph-mobility-count {
  position: absolute; right: 16px; top: 8px; z-index: 2; text-align: right;
  & output { font: 700 clamp(30px, 7cqi, 46px)/1 ui-monospace, Menlo, monospace; letter-spacing: -.06em; font-variant-numeric: tabular-nums; color: var(--aph-mobility-ink); }
}
.aph-mobility .aph-mobility-flash {
  position: absolute; inset: 0; z-index: 3; display: grid; place-items: center; pointer-events: none; font: 850 clamp(22px, 5cqi, 34px)/1 system-ui; letter-spacing: -.03em; color: var(--aph-mobility-paper);
  background: color-mix(in oklab, var(--aph-mobility-accent) 88%, transparent); clip-path: circle(0% at 50% 50%); opacity: 0;
  &.is-on { animation: aph-mobility-flash 1.1s var(--aph-mobility-ease) both; }
}
.aph-mobility[data-state="rest"] .aph-mobility-stage::after { content: "Get ready"; position: absolute; left: 50%; bottom: 14px; translate: -50% 0; padding: 4px 12px; border-radius: 99px; background: var(--aph-mobility-ink); color: var(--aph-mobility-paper); font-size: 11.5px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; }
.aph-mobility .aph-mobility-now { display: flex; align-items: flex-end; justify-content: space-between; gap: 14px; }
.aph-mobility .aph-mobility-title {
  min-width: 0;
  & small { font-size: 10.5px; text-transform: uppercase; letter-spacing: .14em; color: var(--aph-mobility-accent); font-weight: 750; }
  & h2 { font-size: clamp(22px, 5.4cqi, 32px); font-weight: 850; letter-spacing: -.04em; line-height: 1.02; }
  & p { color: var(--aph-mobility-mute); margin-top: 4px; max-width: 46ch; }
}
.aph-mobility .aph-mobility-next {
  flex: none; display: grid; grid-template-columns: auto auto; gap: 0 8px; align-items: center; padding: 6px 10px 6px 6px; border-radius: 12px; background: var(--aph-mobility-card); border: 1px solid var(--aph-mobility-line);
  & .aph-mobility-thumb { grid-row: span 2; width: 40px; height: 30px; }
  & small { font-size: 10px; text-transform: uppercase; letter-spacing: .12em; color: var(--aph-mobility-faint); font-weight: 700; }
  & b { font-size: 12px; font-weight: 650; white-space: nowrap; }
  &:empty { display: none; }
}
.aph-mobility .aph-mobility-timeline {
  display: flex; gap: 3px; height: 14px; align-items: stretch;
  & button { position: relative; flex: var(--d) 1 0; min-width: 4px; border-radius: 4px; background: var(--aph-mobility-line); overflow: hidden; transition: background .2s, transform .2s var(--aph-mobility-ease); }
  & button i { position: absolute; inset: 0; background: var(--aph-mobility-accent); transform-origin: left; transform: scaleX(var(--f, 0)); }
  & button.is-done i { --f: 1; background: color-mix(in oklab, var(--aph-mobility-accent) 55%, var(--aph-mobility-paper)); }
  & button.is-now { background: color-mix(in oklab, var(--aph-mobility-accent) 18%, var(--aph-mobility-line)); }
  & button:hover { transform: scaleY(1.35); }
}
.aph-mobility .aph-mobility-ctl { display: flex; align-items: center; justify-content: center; gap: 8px; flex-wrap: wrap; }
.aph-mobility .aph-mobility-round { width: 42px; height: 42px; border-radius: 50%; display: grid; place-items: center; background: var(--aph-mobility-card); border: 1px solid var(--aph-mobility-line); transition: transform .2s var(--aph-mobility-spring); }
.aph-mobility .aph-mobility-round svg path { fill: currentColor; }
.aph-mobility .aph-mobility-round:active { transform: scale(.9); }
.aph-mobility .aph-mobility-play {
  display: inline-flex; align-items: center; gap: 8px; height: 48px; padding: 0 20px 0 16px; border-radius: 99px; background: var(--aph-mobility-accent); color: white; font-weight: 750; font-size: 14px;
  box-shadow: 0 14px 28px -14px color-mix(in oklab, var(--aph-mobility-accent) 90%, transparent); transition: transform .2s var(--aph-mobility-spring), filter .15s;
  & svg path { fill: currentColor; stroke: currentColor; }
  & .aph-mobility-ipause path { fill: none; stroke-width: 2.6; }
  & .aph-mobility-ipause { display: none; }
  & kbd { background: transparent; color: oklch(1 0 0 / .8); border-color: oklch(1 0 0 / .4); }
  &:hover { filter: brightness(1.05); }
  &:active { transform: scale(.95); }
}
.aph-mobility[data-state="play"] .aph-mobility-play .aph-mobility-iplay, .aph-mobility[data-state="rest"] .aph-mobility-play .aph-mobility-iplay { display: none; }
.aph-mobility[data-state="play"] .aph-mobility-play .aph-mobility-ipause, .aph-mobility[data-state="rest"] .aph-mobility-play .aph-mobility-ipause { display: block; }
.aph-mobility .aph-mobility-chip { height: 34px; padding: 0 11px; border-radius: 99px; border: 1px solid var(--aph-mobility-line2); font-size: 12px; font-weight: 650; display: inline-flex; align-items: center; gap: 5px; }
.aph-mobility .aph-mobility-chip svg { width: 15px; height: 15px; }
.aph-mobility .aph-mobility-done {
  position: absolute; z-index: 6; left: 20px; right: 20px; top: 20px; margin: 0 auto; max-width: 420px; padding: 18px; border-radius: 18px; background: var(--aph-mobility-card); border: 1px solid var(--aph-mobility-line2);
  box-shadow: 0 30px 60px -24px color-mix(in oklab, var(--aph-mobility-ink) 60%, transparent); display: grid; gap: 10px;
  transition: opacity .3s, transform .5s var(--aph-mobility-spring); @starting-style { opacity: 0; transform: translateY(16px) scale(.97); }
  & h3 { font-size: 22px; text-transform: none; letter-spacing: -.03em; color: var(--aph-mobility-ink); font-weight: 850; }
  & p { color: var(--aph-mobility-mute); }
  & div { display: flex; justify-content: flex-end; gap: 8px; }
  & button { height: 36px; padding: 0 14px; border-radius: 10px; font-weight: 700; border: 1px solid var(--aph-mobility-line2); }
  & button.is-primary { background: var(--aph-mobility-ink); color: var(--aph-mobility-paper); border-color: var(--aph-mobility-ink); }
}

/* ── library ── */
.aph-mobility .aph-mobility-lib {
  grid-area: lib; overflow: auto; overscroll-behavior: contain; border-left: 1px solid var(--aph-mobility-line); padding: 16px 14px 18px; display: grid; grid-template-columns: minmax(0, 1fr); align-content: start; gap: 10px; min-width: 0;
  scrollbar-width: thin;
}
.aph-mobility .aph-mobility-lhead { display: flex; justify-content: space-between; align-items: baseline; }
.aph-mobility .aph-mobility-lhead span { font-size: 11.5px; color: var(--aph-mobility-mute); }
.aph-mobility .aph-mobility-areas {
  display: flex; flex-wrap: wrap; gap: 4px;
  & button { height: 26px; padding: 0 10px; border-radius: 99px; border: 1px solid var(--aph-mobility-line2); font-size: 12px; font-weight: 600; color: var(--aph-mobility-mute); }
  & button[aria-selected="true"] { background: var(--aph-mobility-ink); color: var(--aph-mobility-paper); border-color: var(--aph-mobility-ink); }
}
.aph-mobility .aph-mobility-cards { display: grid; gap: 6px; }
.aph-mobility .aph-mobility-card {
  display: grid; grid-template-columns: 56px minmax(0, 1fr) auto; gap: 1px 10px; align-items: center; text-align: left; padding: 7px 8px 7px 7px; border-radius: 12px; background: var(--aph-mobility-card); border: 1px solid var(--aph-mobility-line);
  transition: border-color .15s, transform .2s var(--aph-mobility-spring), box-shadow .2s;
  & .aph-mobility-thumb { grid-row: span 2; width: 56px; height: 40px; background: var(--aph-mobility-blush); }
  & b { font-size: 12.5px; font-weight: 650; }
  & span { font-size: 11px; color: var(--aph-mobility-mute); }
  & em { grid-row: span 2; width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; background: var(--aph-mobility-sunk); font-style: normal; }
  & em svg { width: 15px; height: 15px; }
  &:hover { border-color: var(--aph-mobility-line2); box-shadow: 0 8px 18px -12px color-mix(in oklab, var(--aph-mobility-ink) 45%, transparent); }
  &:hover em { background: var(--aph-mobility-accent); color: white; }
  &:active { transform: scale(.98); }
}
.aph-mobility .aph-mobility-settings { margin-top: 6px; padding-top: 12px; border-top: 1px solid var(--aph-mobility-line); display: grid; gap: 10px; }
.aph-mobility .aph-mobility-seg {
  display: grid; grid-template-columns: repeat(3, 1fr); padding: 3px; border-radius: 10px; background: var(--aph-mobility-sunk);
  & button { height: 28px; border-radius: 7px; font-size: 12px; font-weight: 650; color: var(--aph-mobility-mute); }
  & button[aria-checked="true"] { background: var(--aph-mobility-card); color: var(--aph-mobility-ink); box-shadow: 0 1px 2px color-mix(in oklab, var(--aph-mobility-ink) 15%, transparent); }
}
.aph-mobility .aph-mobility-switch {
  display: inline-flex; align-items: center; gap: 8px; font-size: 12.5px; text-align: left;
  & i { position: relative; flex: none; width: 32px; height: 19px; border-radius: 99px; background: var(--aph-mobility-line2); transition: background .25s; }
  & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 15px; height: 15px; border-radius: 50%; background: white; box-shadow: 0 1px 2px oklch(0 0 0 / .25); transition: transform .3s var(--aph-mobility-spring); }
  &[aria-checked="true"] i { background: var(--aph-mobility-accent); }
  &[aria-checked="true"] i::after { transform: translateX(13px); }
}

/* ── tabs, toast ── */
.aph-mobility .aph-mobility-tabs {
  grid-area: tabs; display: none; gap: 4px; padding: 6px 8px; border-top: 1px solid var(--aph-mobility-line); background: var(--aph-mobility-sunk);
  & button { flex: 1; display: grid; justify-items: center; gap: 2px; padding: 5px 0 3px; border-radius: 9px; font-size: 10.5px; font-weight: 650; color: var(--aph-mobility-faint); }
  & button[aria-current="page"] { color: var(--aph-mobility-accent); background: var(--aph-mobility-card); }
}
.aph-mobility .aph-mobility-toast {
  position: absolute; z-index: 40; left: 50%; bottom: 16px; translate: -50% 0; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 24px);
  padding: 9px 9px 9px 14px; border-radius: 12px; background: var(--aph-mobility-ink); color: var(--aph-mobility-paper); font-size: 12.5px; font-weight: 550;
  box-shadow: 0 14px 34px -10px color-mix(in oklab, var(--aph-mobility-ink) 70%, transparent); transition: opacity .25s, translate .45s var(--aph-mobility-spring);
  &:empty { display: none; }
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & button { height: 28px; padding: 0 10px; border-radius: 8px; background: color-mix(in oklab, var(--aph-mobility-paper) 16%, transparent); font-weight: 700; white-space: nowrap; }
  & button kbd { background: transparent; color: inherit; opacity: .7; border-color: color-mix(in oklab, var(--aph-mobility-paper) 30%, transparent); }
  @starting-style { opacity: 0; translate: -50% 14px; }
}
@keyframes aph-mobility-flash { 0% { clip-path: circle(0% at 50% 50%); opacity: 1; } 30% { clip-path: circle(75% at 50% 50%); opacity: 1; } 75% { clip-path: circle(75% at 50% 50%); opacity: 1; } 100% { clip-path: circle(75% at 50% 50%); opacity: 0; } }
@keyframes aph-mobility-in { from { opacity: 0; transform: translateY(-8px); } }

/* library cards rise into the library's own scroller */
@supports (animation-timeline: view()) {
  .aph-mobility .aph-mobility-card { animation: aph-mobility-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 60%; }
}
@keyframes aph-mobility-rise { from { opacity: .25; transform: translateY(14px) scale(.98); } }

/* ── responsive ── */
@container aph-mobility (max-width: 1099px) {
  .aph-mobility .aph-mobility-app { grid-template-columns: 240px minmax(0, 1fr) 248px; }
}
@container aph-mobility (max-width: 959px) {
  .aph-mobility .aph-mobility-app { grid-template-columns: 240px minmax(0, 1fr); grid-template-areas: "queue player" "tabs tabs"; }
  .aph-mobility .aph-mobility-lib { grid-area: player; border-left: 0; }
  .aph-mobility .aph-mobility-tabs { display: flex; }
  .aph-mobility .aph-mobility-tabs [data-view-to="queue"] { display: none; }
  .aph-mobility[data-view="lib"] .aph-mobility-player { display: none; }
  .aph-mobility:not([data-view="lib"]) .aph-mobility-lib { display: none; }
}
@container aph-mobility (max-width: 759px) {
  .aph-mobility .aph-mobility-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "player" "tabs"; }
  .aph-mobility .aph-mobility-queue { grid-area: player; border-right: 0; }
  .aph-mobility:not([data-view="queue"]) .aph-mobility-queue { display: none; }
  .aph-mobility[data-view="queue"] .aph-mobility-player { display: none; }
  .aph-mobility .aph-mobility-tabs [data-view-to="queue"] { display: grid; }
  .aph-mobility .aph-mobility-player { padding: 12px; gap: 10px; }
  .aph-mobility .aph-mobility-toast { bottom: 70px; }
}
@container aph-mobility-player (max-width: 520px) {
  .aph-mobility .aph-mobility-next { display: none; }
  .aph-mobility .aph-mobility-play kbd { display: none; }
  .aph-mobility .aph-mobility-title p { font-size: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  .aph-mobility *, .aph-mobility *::before, .aph-mobility *::after { animation: none !important; transition-duration: 1ms !important; transition-delay: 0ms !important; }
  .aph-mobility .aph-mobility-fig .aph-mobility-body { transition: none; }
}

